    def _sync_current_centers_lagan(self, reason: str = ""):
        """
        维护 current_centers_lagan 的一致性：
        - 存“绝对坐标”
        - 内容 = current_centers(当前换热管孔) + lagan_info(普通拉杆)
        - 自由拉杆不会出现在 lagan_info 中（自由拉杆写入 red_dangban_abs）
        """

        try:
            tube_centers = list(getattr(self, "current_centers", []) or [])
        except Exception:
            tube_centers = []

        try:
            lagan_centers = list(getattr(self, "lagan_info", []) or [])
        except Exception:
            lagan_centers = []

        def key6(x, y):
            return (round(float(x), 6), round(float(y), 6))

        tube_keys = set()
        for x, y in tube_centers:
            try:
                tube_keys.add(key6(x, y))
            except Exception:
                pass

        # 先保留 tube 的原始顺序；再补齐 lagan_info 中 tube_centers 没有的点
        combined = list(tube_centers)
        for x, y in lagan_centers:
            try:
                k = key6(x, y)
            except Exception:
                continue
            if k not in tube_keys:
                combined.append((x, y))
                tube_keys.add(k)

        self.current_centers_lagan = combined

        # 调试输出：观察删除/添加换热管、拉杆后该变量是否同步刷新
        try:
            tube_count = len(tube_centers)
            lagan_count = len(lagan_centers)
            combined_count = len(self.current_centers_lagan)
            sizes = (tube_count, lagan_count, combined_count)
            last_sizes = getattr(self, "_debug_sync_last_sizes", None)
            if last_sizes != sizes:
                print(
                    f"[SYNC current_centers_lagan] reason={reason} "
                    f"tube={tube_count} lagan={lagan_count} current_centers_lagan={combined_count}",
                    flush=True,
                )
                self._debug_sync_last_sizes = sizes
        except Exception:
            pass

        # 同步缓存分组结果（后续定位/绘制用）
        try:
            (
                self.sorted_current_centers_lagan_up,
                self.sorted_current_centers_lagan_down,
            ) = self.group_centers_by_y(self.current_centers_lagan)
        except Exception:
            pass

    def _prune_slipway_centers_overlapping_current(self):
        """
        slipway_centers 记录滑道干涉删除的换热管绝对坐标；
        current_centers 记录当前仍存在的换热管。
        二者不应重合：若重合说明 slipway_centers 残留过期数据，
        从 slipway_centers 剔除即可，绝不修改 current_centers。
        """
        try:
            slipway = list(getattr(self, "slipway_centers", None) or [])
        except Exception:
            slipway = []
        if not slipway:
            return

        try:
            current = list(getattr(self, "current_centers", None) or [])
        except Exception:
            current = []

        def key6(x, y):
            return (round(float(x), 6), round(float(y), 6))

        current_keys = set()
        for c in current:
            try:
                if isinstance(c, (list, tuple)) and len(c) >= 2:
                    current_keys.add(key6(c[0], c[1]))
            except Exception:
                pass

        pruned = []
        removed = 0
        for c in slipway:
            try:
                if not (isinstance(c, (list, tuple)) and len(c) >= 2):
                    pruned.append(c)
                    continue
                if key6(c[0], c[1]) in current_keys:
                    removed += 1
                    continue
                pruned.append(c)
            except Exception:
                pruned.append(c)

        self.slipway_centers = pruned
        if removed:
            try:
                print(
                    f"[slipway] 从 slipway_centers 剔除与 current_centers 重合的 {removed} 个坐标",
                    flush=True,
                )
            except Exception:
                pass

    def _parse_slipway_centers_from_db(self, coord_raw):
        """将布管元件表类型8的坐标解析为绝对坐标列表（兼容旧版相对坐标）。"""
        import ast

        if coord_raw is None or coord_raw == "" or coord_raw == "[]":
            return []
        if isinstance(coord_raw, str):
            try:
                coord_raw = ast.literal_eval(coord_raw.strip())
            except Exception:
                return []
        if not isinstance(coord_raw, list):
            return []

        parsed = []
        is_relative = None
        for item in coord_raw:
            if not (isinstance(item, (list, tuple)) and len(item) >= 2):
                continue
            try:
                a, b = item[0], item[1]
                if is_relative is None:
                    is_relative = isinstance(a, int) and isinstance(b, int)
                parsed.append((a, b))
            except Exception:
                continue
        if not parsed:
            return []

        if is_relative:
            rel_list = []
            for a, b in parsed:
                try:
                    rel_list.append((int(a), int(b)))
                except Exception:
                    rel_list.append((a, b))
            abs_list = self.selected_to_current_coords(rel_list) or []
            return self._normalize_slipway_abs_centers(abs_list)

        return self._normalize_slipway_abs_centers(parsed)

    def _normalize_slipway_abs_centers(self, centers):
        """slipway 绝对坐标去重（key6）。"""

        def key6(x, y):
            return (round(float(x), 6), round(float(y), 6))

        seen = set()
        out = []
        for c in centers or []:
            try:
                if isinstance(c, (list, tuple)) and len(c) >= 2:
                    k = key6(c[0], c[1])
                    if k not in seen:
                        seen.add(k)
                        out.append((float(c[0]), float(c[1])))
            except Exception:
                pass
        return out

    def _canonical_buguan_param_name(self, param_name):
        """布管参数名归一（AKU/BKU 壳体小端内直径 → 壳体内直径 Dis）。"""
        name = str(param_name or "").strip()
        try:
            hx = str(getattr(self, "heat_exchanger", "") or "").strip().upper()
            if hx in ("AKU", "BKU") and name == "壳体小端内直径":
                return "壳体内直径 Dis"
        except Exception:
            pass
        if name.startswith("是否以外径为基准"):
            return "是否以外径为基准"
        return name

    @staticmethod
    def _buguan_param_value_nonempty(val):
        if val is None:
            return False
        return str(val).strip() != ""

    def _dedupe_buguan_params(self, params):
        """
        布管参数列表去重：同一归一化参数名只保留一条。
        优先保留非空参数值；均非空时保留后出现的一条（视为较新）。
        """
        if not params:
            return []
        merged = {}
        order = []
        for p in params:
            if not isinstance(p, dict):
                continue
            raw_name = p.get("参数名")
            if raw_name is None:
                continue
            canon = self._canonical_buguan_param_name(raw_name)
            entry = {
                "参数名": canon,
                "参数值": p.get("参数值"),
                "单位": p.get("单位", ""),
            }
            if canon not in merged:
                merged[canon] = entry
                order.append(canon)
                continue
            old = merged[canon]
            old_ok = self._buguan_param_value_nonempty(old.get("参数值"))
            new_ok = self._buguan_param_value_nonempty(entry.get("参数值"))
            if new_ok and not old_ok:
                merged[canon] = entry
            elif new_ok and old_ok:
                merged[canon] = entry
        out = [merged[k] for k in order]
        removed = len(params) - len(out)
        if removed > 0:
            try:
                print(
                    f"[布管参数去重] 产品 {getattr(self, 'productID', '')} "
                    f"合并重复参数 {removed} 项",
                    flush=True,
                )
            except Exception:
                pass
        return out

    def _true_slipway_key_set(self):
        return {
            (round(float(x), 6), round(float(y), 6))
            for x, y in (getattr(self, "true_slipway_centers", None) or [])
        }

    def _expand_single_center_linkage(self, rel_coord):
        tube_num = self.get_tube_pass_count()
        if tube_num == "2" and self.heat_exchanger in ["AEU", "BEU", "AKU", "BKU"]:
            return self.judge_linkage_x([rel_coord])
        return self.judge_linkage_y([rel_coord])

    def _coord_hits_true_slipway(self, coord):
        true_set = self._true_slipway_key_set()
        if not true_set or not coord:
            return False
        try:
            a, b = coord[0], coord[1]
        except Exception:
            return False
        if isinstance(a, int) and isinstance(b, int):
            expanded = self._expand_single_center_linkage((int(a), int(b)))
            abs_list = self.selected_to_current_coords(expanded) or []
        else:
            abs_list = [(float(a), float(b))]
        return any(
            (round(float(x), 6), round(float(y), 6)) in true_set
            for x, y in abs_list
        )

    def _filter_coords_blocked_by_true_slipway(
        self, centers, suppress_warning=False
    ):
        """剔除与 true_slipway_centers 干涉的坐标（含对称联动），返回 (allowed, had_blocked)。"""
        if not centers:
            return [], False
        if not getattr(self, "true_slipway_centers", None):
            return list(centers), False

        allowed = []
        had_blocked = False
        for coord in centers:
            if self._coord_hits_true_slipway(coord):
                had_blocked = True
            else:
                allowed.append(coord)

        if had_blocked and not suppress_warning:

            QMessageBox.warning(
                self,
                "提示",
                "部分位置与滑道干涉，不允许添加换热管/拉杆",
            )
            self.clear_selection_highlight()

        return allowed, had_blocked

    @staticmethod
    def _point_in_convex_polygon(point, polygon):
        x, y = point
        if len(polygon) < 3:
            return False

        def cross(o, a, b):
            return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

        c_vals = [
            cross(polygon[i], polygon[(i + 1) % len(polygon)], point)
            for i in range(len(polygon))
        ]
        has_neg = any(v < -1e-8 for v in c_vals)
        has_pos = any(v > 1e-8 for v in c_vals)
        return not (has_neg and has_pos)

    @staticmethod
    def _point_to_segment_distance(point, seg_start, seg_end):
        x, y = point
        x1, y1 = seg_start
        x2, y2 = seg_end
        dx = x2 - x1
        dy = y2 - y1
        if dx == 0 and dy == 0:
            return math.hypot(x - x1, y - y1)
        t = ((x - x1) * dx + (y - y1) * dy) / (dx * dx + dy * dy)
        t = max(0.0, min(1.0, t))
        proj_x = x1 + t * dx
        proj_y = y1 + t * dy
        return math.hypot(x - proj_x, y - proj_y)

    def _tube_intersects_slide_rect(self, center, radius, slide_corners):
        if not center or not slide_corners:
            return False
        try:
            cx, cy = float(center[0]), float(center[1])
            r = float(radius)
        except Exception:
            return False
        if self._point_in_convex_polygon((cx, cy), slide_corners):
            return True
        for i in range(len(slide_corners)):
            p1 = slide_corners[i]
            p2 = slide_corners[(i + 1) % len(slide_corners)]
            if self._point_to_segment_distance((cx, cy), p1, p2) <= r + 1e-8:
                return True
        return False

    def _collect_geometric_slipway_hits(self, slide_corners, tube_centers, tube_radius):
        hits = []
        for center in tube_centers or []:
            if self._tube_intersects_slide_rect(center, tube_radius, slide_corners):
                hits.append(center)
        return hits

    def _apply_slipway_linkage_abs(self, abs_centers):
        if not abs_centers:
            return []
        rel = []
        for c in abs_centers:
            rc = self.actual_to_selected_coords(c)
            if rc is not None:
                rel.append(rc)
        if not rel:
            return self._normalize_slipway_abs_centers(abs_centers)
        tube_num = self.get_tube_pass_count()
        if tube_num == "2" and self.heat_exchanger in ["AEU", "BEU", "AKU", "BKU"]:
            expanded_rel = self.judge_linkage_x(rel)
        else:
            expanded_rel = self.judge_linkage_y(rel)
        abs_expanded = self.selected_to_current_coords(expanded_rel) or []
        return self._normalize_slipway_abs_centers(abs_expanded)

    def _update_true_slipway_centers(
        self, slide_corners1, slide_corners2, tube_centers, tube_diameter
    ):
        """按滑道矩形几何干涉 + 对称联动，更新 true_slipway_centers。"""
        try:
            radius = float(tube_diameter) / 2.0
        except Exception:
            radius = float(getattr(self, "r", 0) or 0)
        hits = []
        for corners in (slide_corners1, slide_corners2):
            if not corners:
                continue
            hits.extend(
                self._collect_geometric_slipway_hits(corners, tube_centers, radius)
            )
        hits = self._normalize_slipway_abs_centers(hits)
        self.true_slipway_centers = self._apply_slipway_linkage_abs(hits)

    def _read_slipway_draw_params(self):
        """读取滑道绘制参数（高度/厚度/夹角）。"""
        height = thickness = angle = None
        try:
            ij = getattr(self, "input_json", None)
            if isinstance(ij, dict):
                height = ij.get("LB_SlipWayHeight")
                thickness = ij.get("LB_SlipWayThick")
                angle = ij.get("LB_SlipWayAngle")
        except Exception:
            pass
        try:
            if height is None:
                height = self._read_param_table_float("滑道高度")
            if thickness is None:
                thickness = self._read_param_table_float("滑道厚度")
            if angle is None:
                angle = self._read_param_table_float("滑道与竖直中心线夹角")
        except Exception:
            pass
        try:
            if height is None or thickness is None or angle is None:
                return None
            return float(height), float(thickness), float(angle)
        except Exception:
            return None

    def _remove_tubes_for_slipway_restore(self):
        """按 slipway_centers 删除换热管（不写入 del_centers）。"""
        centers = self._normalize_slipway_abs_centers(
            getattr(self, "slipway_centers", None) or []
        )
        if not centers:
            return
        self.delete_huanreguan(centers, for_slipway=True)

    def restore_slipway_from_saved(self):
        """滑道：逻辑已迁移至 component/slipway.py。"""
        from modules.buguan.buguan_ziyong.component.slipway import (
            restore_slipway_from_saved as _restore_slipway_from_saved,
        )

        return _restore_slipway_from_saved(self)

    def handle_symmetric_layout(self, state):
        if state == Qt.Checked:
            self.isSymmetry = True
        else:
            self.isSymmetry = False

    @property
    def current_centers(self):
        return self._current_centers

    @current_centers.setter
    def current_centers(self, value):
        self._current_centers = value
        self.update_total_holes_count()

        # 每次 current_centers 变化时，更新 R 值和最小非0 R值
        # 确保 hole_distribution_table 已经创建（避免初始化时出错）
        if (
                hasattr(self, "hole_distribution_table")
                and self.hole_distribution_table is not None
        ):
            try:
                # 更新水平表的最小非0 R值（self.min_distance_row）
                self.get_current_tube_hole_data()
            except Exception as e:
                # 如果计算失败，不影响主流程，只记录日志
                print(f"【警告】更新水平表最小R值时出错: {e}")

            try:
                # 更新竖直表的最小非0 R值（self.min_distance_col）
                self.update_min_distance_col()
            except Exception as e:
                # 如果计算失败，不影响主流程，只记录日志
                print(f"【警告】更新竖直表最小R值时出错: {e}")

        # current_centers 整体赋值时，同步维护 current_centers_lagan
        try:
            if hasattr(self, "_sync_current_centers_lagan"):
                self._sync_current_centers_lagan()
        except Exception:
            pass

    @property
    def selected_centers(self):
        return self._selected_centers

    @selected_centers.setter
    def selected_centers(self, value):
        if self._selected_centers != value:
            self._selected_centers = value
            # print("self.selected_centers发生变化")
            if getattr(self, "is_arrange_by_row", True):
                self.highlight_right_table_row()
            else:
                self.highlight_right_table_col()
            self.show_distance()
            # 当选中换热管孔集合发生变化时，提示当前选中数量
            try:
                count = (
                    len(self.selected_centers)
                    if hasattr(self, "selected_centers")
                    else 0
                )
                # 当选中数量为2时，仅显示两孔间距提示，不再显示数量提示
                if count == 1:
                    # 只选中一个换热管孔：在底部提示该孔绝对坐标
                    # 绝对坐标取 self.selected_to_current_coords 的结果（与 global_centers 同源的当前坐标系）
                    abs_x = None
                    abs_y = None
                    try:
                        coords = self.selected_to_current_coords(self.selected_centers)
                        if isinstance(coords, tuple) and len(coords) == 2:
                            abs_x, abs_y = coords
                        elif (
                            isinstance(coords, list)
                            and len(coords) == 1
                            and isinstance(coords[0], (tuple, list))
                            and len(coords[0]) == 2
                        ):
                            abs_x, abs_y = coords[0]
                    except Exception:
                        abs_x = None
                        abs_y = None

                    if abs_x is not None and abs_y is not None:
                        # 说明：当前用于计算/绘制的坐标系与肉眼象限显示的 y 方向相反
                        # 所以这里做 y 取反，保证用户看到的“第一/第二/三/四象限”与提示一致。
                        try:
                            abs_y_display = -float(abs_y)
                        except Exception:
                            abs_y_display = abs_y
                        # 单选换热管时在控制台输出圆心坐标（普通拉杆/自由拉杆各自处理）
                        try:
                            lagan_n = len(getattr(self, "selected_lagans", []) or [])
                            side_n = sum(
                                1
                                for it in getattr(self, "selected_side_rods", []) or []
                                if getattr(it, "is_selected", False)
                            )
                            if lagan_n == 0 and side_n == 0:
                                self.print_selected_circle_center(
                                    "换热管", abs_x, abs_y
                                )
                        except Exception:
                            pass
                        message = (
                            f"您当前选中的换热管孔坐标为 ({float(abs_x):.4f}, {abs_y_display:.4f})"
                        )
                    else:
                        # 坐标取不到时退回数量提示，避免无提示
                        message = f"您当前选中的换热管孔的数量为{count}个"

                    if hasattr(self, "line_tip") and self.line_tip is not None:
                        self.line_tip.setText(message)
                        self.line_tip.setStyleSheet("color: black;")
                        self.line_tip.setVisible(True)

                        from PyQt5.QtCore import QTimer

                        expected_text = message

                        def _clear_if_same():
                            try:
                                if self.line_tip and self.line_tip.text() == expected_text:
                                    self.line_tip.setText("")
                            except Exception:
                                pass

                        QTimer.singleShot(5000, _clear_if_same)
                    else:
                        print(message)
                elif count != 2:
                    message = f"您当前选中的换热管孔的数量为{count}个"
                    if hasattr(self, "line_tip") and self.line_tip is not None:
                        self.line_tip.setText(message)
                        self.line_tip.setStyleSheet("color: black;")
                        self.line_tip.setVisible(True)

                        from PyQt5.QtCore import QTimer

                        expected_text = message

                        def _clear_if_same():
                            try:
                                if self.line_tip and self.line_tip.text() == expected_text:
                                    self.line_tip.setText("")
                            except Exception:
                                pass

                        QTimer.singleShot(5000, _clear_if_same)
                    else:
                        print(message)
            except Exception:
                try:
                    count = (
                        len(self.selected_centers)
                        if hasattr(self, "selected_centers")
                        else 0
                    )
                    if count != 2:
                        message = f"您当前选中的换热管孔的数量为{count}个"
                        print(message)
                except Exception:
                    pass
            # 当换热管选中发生变化时，尝试显示“自由拉杆-换热管”间距
            try:
                if hasattr(self, "check_and_show_lagan_tube_distance"):
                    self.check_and_show_lagan_tube_distance()
            except Exception:
                pass
            for callback in self.selected_centers_changed_callbacks:
                callback(value)

    def register_selected_centers_callback(self, callback):
        """注册 selected_centers 变化的回调函数"""
        if callback not in self.selected_centers_changed_callbacks:
            self.selected_centers_changed_callbacks.append(callback)

    def unregister_selected_centers_callback(self, callback):
        """取消注册回调函数"""
