    def check_and_show_lagan_tube_distance(self):
        """当且仅当选中一个自由拉杆和一个换热管时，提示两者间距（四位小数）。其它情况不提示。"""
        try:
            import math

            # 优先判断自由拉杆（build_free_form_lagan 生成，标记为 is_side_rod）
            side_rods = [
                it
                for it in getattr(self, "selected_side_rods", [])
                if getattr(it, "is_selected", False)
            ]
            target_items = side_rods
            if len(target_items) != 1:
                # 兼容普通拉杆（is_lagan）
                lagans = [
                    it
                    for it in getattr(self, "selected_lagans", [])
                    if getattr(it, "is_selected", False)
                ]
                target_items = lagans
            if len(target_items) != 1:
                return

            # 2) 恰好一个换热管被选中
            if not hasattr(self, "selected_centers") or len(self.selected_centers) != 1:
                return

            # 自由拉杆圆心（场景坐标）
            lagan_item = target_items[0]
            p = lagan_item.sceneBoundingRect().center()
            x1, y1 = p.x(), p.y()

            # 换热管圆心（当前坐标系）
            coords = self.selected_to_current_coords(self.selected_centers)
            # 兼容函数返回单个元组或单元素列表
            if not coords:
                return
            if isinstance(coords, tuple) and len(coords) == 2:
                x2, y2 = coords
            elif (
                    isinstance(coords, list)
                    and len(coords) == 1
                    and isinstance(coords[0], (tuple, list))
                    and len(coords[0]) == 2
            ):
                x2, y2 = coords[0]
            else:
                return

            dist = math.hypot(x1 - x2, y1 - y2)
            message = f"您选中的换热管孔和自由拉杆的间距为  {dist:.4f} mm。"
            print(message)
            print(
                f"换热管孔圆心坐标: ({x2:.4f}, {y2:.4f}), "
                f"自由拉杆圆心坐标: ({x1:.4f}, {y1:.4f})"
            )
            try:
                self.line_tip.setText(message)
                self.line_tip.setStyleSheet("color: black;")
                self.line_tip.setVisible(True)
                from PyQt5.QtCore import QTimer

                expected_text = message

                def _clear_if_same():
                    try:
                        if self.line_tip and self.line_tip.text() == expected_text:
                            self.line_tip.setText("")
                    except Exception:
                        pass

                QTimer.singleShot(5000, _clear_if_same)
            except AttributeError:
                pass
        except Exception:
            # 静默捕获
            pass

    def setup_param_listeners(self):
        """为参数表格添加变化监听，实时更新参数列表"""
        # 监听表格内容变化（先断开避免与 setup_parameter_listeners 叠加重复触发）
        try:
            self.param_table.itemChanged.disconnect(self.update_leftpad_params)
        except Exception:
            pass
        self.param_table.itemChanged.connect(self.update_leftpad_params)
        # 遍历表格，为下拉框添加监听
        row_count = self.param_table.rowCount()
        for row in range(row_count):
            widget = self.param_table.cellWidget(row, 2)
            if isinstance(widget, QComboBox):
                widget.currentIndexChanged.connect(self.update_leftpad_params)

    # TODO 获取选中的两个换热管的编号
    def get_selected_y_center_numbers(
            self, selected_centers, print_cross_y_left, print_cross_y_right, row
    ):
        # 仅按当前可交叉布管候选（print_cross_*）匹配，避免使用 full_* 导致已删除管孔误参与
        left_number = None
        right_number = None

        for center in selected_centers:
            for item in print_cross_y_left:
                # item格式：(编号, x, y)，center格式：(x, y)
                if (item[1], item[2]) == center:
                    left_number = item[0]
                    break
            for item in print_cross_y_right:
                if (item[1], item[2]) == center:
                    right_number = item[0]
                    break

        if left_number is None or right_number is None:
            raise ValueError(
                "selected_centers中的坐标未完全匹配到print_cross_y_left或print_cross_y_right"
            )

        return {"left_number": left_number, "right_number": right_number}

    def update_leftpad_params(self):
        """实时更新左侧参数为列表形式"""
        self.current_leftpad = []  # 清空现有列表
        row_count = self.param_table.rowCount()

        for row in range(row_count):
            # 跳过隐藏行
            if self.param_table.isRowHidden(row):
                continue

            # 序号（第0列）
            num_item = self.param_table.item(row, 0)
            num = num_item.text() if num_item else str(row + 1)

            # 参数名（第1列）
            name_item = self.param_table.item(row, 1)
            name = name_item.text() if name_item else "未知参数"

            # 参数值（第2列，处理输入框和下拉框）
            value_widget = self.param_table.cellWidget(row, 2)
            if isinstance(value_widget, QComboBox):
                value = value_widget.currentText()
            else:
                value_item = self.param_table.item(row, 2)
                value = value_item.text() if value_item else ""

            # 单位（第3列）
            unit_item = self.param_table.item(row, 3)
            unit = unit_item.text() if unit_item else ""

            # 添加到列表（每个元素是一个字典，方便后续取值）
            self.current_leftpad.append(
                {"序号": num, "参数名": name, "参数值": value, "单位": unit}
            )

    def _get_lagan_required_count(self):
        """按公称直径DN+拉杆直径查标准要求数量。"""
        try:
            dn = float(self.get_gongchengzhijing_count())
            lagan_d = float(self.get_laganzhijing_count())
        except (TypeError, ValueError):
            return None

        try:
            print(f"[lagan标准查表] DN={dn}, 拉杆直径={lagan_d}")
        except Exception:
            pass

        standard_table = {
            10.0: [(0, 400, 4), (400, 700, 6), (700, 900, 10), (900, 1300, 12), (1300, 1500, 16), (1500, 1800, 18), (1800, 2000, 24), (2000, 2300, 32), (2300, 2600, 40), (2600, 2800, 48), (2800, 3000, 56), (3000, 3200, 64), (3200, 3400, 72), (3400, 3600, 80), (3600, 3800, 88), (3800, 4000, 98), (4000, 5000, 136), (5000, 6000, 178)],
            12.0: [(0, 400, 4), (400, 700, 4), (700, 900, 8), (900, 1300, 10), (1300, 1500, 12), (1500, 1800, 14), (1800, 2000, 18), (2000, 2300, 24), (2300, 2600, 28), (2600, 2800, 32), (2800, 3000, 40), (3000, 3200, 44), (3200, 3400, 52), (3400, 3600, 56), (3600, 3800, 64), (3800, 4000, 68), (4000, 5000, 96), (5000, 6000, 124)],
            16.0: [(0, 400, 4), (400, 700, 4), (700, 900, 6), (900, 1300, 6), (1300, 1500, 8), (1500, 1800, 10), (1800, 2000, 12), (2000, 2300, 14), (2300, 2600, 16), (2600, 2800, 20), (2800, 3000, 24), (3000, 3200, 26), (3200, 3400, 28), (3400, 3600, 32), (3600, 3800, 36), (3800, 4000, 40), (4000, 5000, 56), (5000, 6000, 74)],
        }
        if lagan_d not in standard_table:
            try:
                print(f"[lagan标准查表] 拉杆直径={lagan_d} 不在标准表(10/12/16)中，返回None")
            except Exception:
                pass
            return None
        for low, high, required in standard_table[lagan_d]:
            if low <= dn < high:
                try:
                    print(f"[lagan标准查表] 命中区间: [{low},{high}) -> {required}")
                except Exception:
                    pass
                return required
        try:
            print("[lagan标准查表] 未命中任何DN区间，返回None")
        except Exception:
            pass
        return None

    def update_total_holes_count(self):
        """更新“总管孔数量”提示。

        统一按当前界面上的实际换热管数量（current_centers）更新，
        避免接口返回值与当前画面状态不一致。
        """
        total = None
        try:
            total = len(getattr(self, "current_centers", []) or [])
        except Exception:
            total = 0

        # 处理初始值：如果未布管且 current_centers 为空，显示 980
        if not getattr(self, "has_piped", False) and total == 0:
            total = 980

        self.total_holes_label.setText(f"总管孔数量: {total}")
        # 右侧管孔数量分布表必须随“当前数据”同步更新：
        # 许多操作会原地修改 self._current_centers（不触发 setter），但会调用 update_total_holes_count。
        try:
            if hasattr(self, "hole_distribution_table") and self.hole_distribution_table is not None:
                self.update_tube_nums()
        except Exception:
            pass

    def toggle_arrange_text(self):
        """切换按钮文字（按行排列 <-> 按列排列）并更新表格数据"""
        if hasattr(self, 'is_arrange_by_row'):
            self.is_arrange_by_row = not self.is_arrange_by_row
            if self.is_arrange_by_row:
                self.arrange_button.setText("按行")
            else:
                self.arrange_button.setText("按列")
            # 切换后同步切换右侧表头
            self.update_hole_distribution_headers()
            # 切换后更新表格数据
            self.update_tube_nums()
            # 重新绑定表格选中逻辑
            self.bind_table_selection_handler()

    def update_hole_distribution_headers(self):
        """根据按钮状态切换右侧管孔数量分布表的表头"""
        if not hasattr(self, "hole_distribution_table"):
            return

        if hasattr(self, "is_arrange_by_row") and self.is_arrange_by_row:
            headers = ["至水平中心线行号", "管孔数量(上)", "管孔数量(下)"]
        else:
            headers = ["至竖直中心线列号", "管孔数量(左)", "管孔数量(右)"]

        self.hole_distribution_table.setHorizontalHeaderLabels(headers)
        for i, header_text in enumerate(headers):
            header_item = self.hole_distribution_table.horizontalHeaderItem(i)
            if header_item:
                header_item.setToolTip(header_text)

    def _set_hole_distribution_table_readonly(self):
        """右侧管孔数量表：禁止编辑，保留可选中。"""
        if not hasattr(self, "hole_distribution_table"):
            return
        table = self.hole_distribution_table
        table.setEditTriggers(QTableWidget.NoEditTriggers)
        readonly_flags = Qt.ItemIsSelectable | Qt.ItemIsEnabled
        for row in range(table.rowCount()):
            for col in range(table.columnCount()):
                item = table.item(row, col)
                if item is not None:
                    item.setFlags(readonly_flags)

    def _get_total_lagan_count(self):
        """普通拉杆 + 自由拉杆总数（与左下角「标准要求数量/已有数量」统计一致）。"""
        # 场景图元是当前实际存在数量的唯一可靠来源；lagan_info、
        # red_dangban_abs 在删除、转换或旧数据加载时可能短暂残留。
        scene = getattr(self, "graphics_scene", None)
        if scene is not None:
            try:
                seen = set()
                for item in scene.items():
                    if not (
                            getattr(item, "is_lagan", False)
                            or getattr(item, "is_side_rod", False)
                    ):
                        continue
                    try:
                        center = item.mapToScene(item.rect().center())
                        seen.add(
                            (
                                round(float(center.x()), 6),
                                round(float(center.y()), 6),
                            )
                        )
                    except Exception:
                        pass
                return len(seen)
            except Exception:
                pass

        # 场景尚未创建时保留缓存兜底。
        lagan_list = getattr(self, "lagan_info", []) or []
        red_abs_list = getattr(self, "red_dangban_abs", []) or []
        red_list = getattr(self, "red_dangban", []) or []
        free_count = len(red_abs_list) if red_abs_list else len(red_list)
        if isinstance(lagan_list, (list, tuple)):
            return len(lagan_list) + free_count
        if isinstance(lagan_list, int):
            return int(lagan_list) + free_count
        return free_count

    def update_total_lagan_count(self):
        """更新拉杆要求/已有数量显示。"""
        total = self._get_total_lagan_count()
        std = self._get_lagan_required_count()
        self.current_lagan_standard_required = std
        if hasattr(self, "lagan_required_label"):
            if isinstance(std, (int, float)):
                std_num = int(std) if float(std).is_integer() else std
                if total < std:
                    text = f"拉杆标准要求数量{std_num}/已有数量<span style='color:red;'>{total}</span>"
                else:
                    text = f"拉杆标准要求数量{std_num}/已有数量{total}"
            else:
                text = f"拉杆标准要求数量-/已有数量{total}"
            self.lagan_required_label.setText(text)

