        """创建选项卡标题"""
        self.header = QTabWidget()
        self.header.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        self.header.addTab(QWidget(), "管板型式")
        self.header.addTab(QWidget(), "布管")  # 默认显示
