                        # 强制更新/添加DL参数到processed_params（只有当计算了DL时才更新）
                        if DL is not None and should_calculate_dl:
                            dl_exists = False
                            # 检查是否已有DL参数，有则更新
                            for i, param in enumerate(processed_params):
                                if param["参数名"] == "布管限定圆 DL":
                                    processed_params[i]["参数值"] = f"{DL: .1f}"
                                    dl_exists = True
