                cursor = product_conn.cursor()
                query_sql = (
                    "SELECT 防冲板厚度, 防冲板折边角度, 防冲板宽度, 防冲板方位角, 至圆筒内壁距离 "
                    "FROM 产品设计活动表_布管焊接式防冲板表 WHERE 产品ID = %s"
                )
                cursor.execute(query_sql, (self.productID,))
                rows = cursor.fetchall() or []

                def _safe_float(v):
                    if v in ("", None):
                        return None
                    try:
                        return float(v)
                    except Exception:
                        return None

                for row in rows:
                    if not isinstance(row, dict):
                        continue
                    thk_v = row.get("防冲板厚度")
                    ang_v = row.get("防冲板折边角度")
                    wid_v = row.get("防冲板宽度")
                    az_v = row.get("防冲板方位角")
                    dist_v = row.get("至圆筒内壁距离")

                    thk_f = _safe_float(thk_v)
                    ang_f = _safe_float(ang_v)
                    wid_f = _safe_float(wid_v)
                    az_f = _safe_float(az_v)
                    dist_f = _safe_float(dist_v)

                    # 若数据库缺值，则回退到 initial_operation 中解析得到的全局参数
                    if thk_f is None:
                        thk_f = baffle_thickness
                    if ang_f is None:
                        ang_f = baffle_angle

