    # 10/27 修改，布管界面点击确认按钮时，根据公称直径、拉杆直径和拉杆数量跳出提示
    # 获取公称直径的值
    def get_gongchengzhijing_count(self):
        row_count = self.param_table.rowCount()
        for row in range(row_count):
            # 获取当前行的参数名
            name_item = self.param_table.item(row, 1)
            if not name_item:
                continue

            if name_item.text() == "公称直径 DN":
                # 检查单元格是否是QComboBox控件
                cell_widget = self.param_table.cellWidget(row, 2)
                if isinstance(cell_widget, QComboBox):
                    return cell_widget.currentText()
                else:
                    # 普通文本单元格
                    value_item = self.param_table.item(row, 2)
                    return value_item.text() if value_item else None

        # 未找到参数时返回None
        return None

    # 获取拉杆直径的值
    def get_laganzhijing_count(self):
        row_count = self.param_table.rowCount()
        for row in range(row_count):
            # 获取当前行的参数名
            name_item = self.param_table.item(row, 1)
            if not name_item:
                continue

            if name_item.text() == "拉杆直径":
                # 检查单元格是否是QComboBox控件
                cell_widget = self.param_table.cellWidget(row, 2)
                if isinstance(cell_widget, QComboBox):
                    return cell_widget.currentText()
                else:
                    # 普通文本单元格
                    value_item = self.param_table.item(row, 2)
                    return value_item.text() if value_item else None

        # 未找到参数时返回None
        return None

    def update_lagan_standard_from_params(self):
        """
        根据当前参数表中的公称直径 DN 和拉杆直径，计算标准拉杆最少数量，
        写入 self.current_lagan_standard_required，并刷新左下角摘要。
        """
        try:
            self.current_lagan_standard_required = self._get_lagan_required_count()
        except Exception:
            self.current_lagan_standard_required = None

        # 用最新标准刷新左下角摘要
        try:
            if hasattr(self, "update_total_lagan_count"):
                self.update_total_lagan_count()
        except Exception:
            pass

    def _apply_baffle_placement_visibility(self):
        """左侧参数表始终隐藏「放置位置」；该参数仅在防冲板弹窗等中编辑，数据仍保留在隐藏行。"""
        try:
            if not hasattr(self, "param_table") or self.param_table is None:
                return
        except Exception:
            return

        def _find_row(name: str) -> int:
            try:
                for r in range(self.param_table.rowCount()):
                    it = self.param_table.item(r, 1)
                    if it and it.text().strip() == name:
                        return r
            except Exception:
                pass
            return -1

        place_row = _find_row("放置位置")
        if place_row == -1:
            return
        try:
            self.set_param_visibility(place_row, False, force=True)
        except Exception:
            pass

    # 10/29 修改，添加了保存的逻辑
    def check_before_save(self):
        """
        在保存前检查公称直径、拉杆直径和 self.lagan_info（拉杆数量）之间的关系，
        若数量不足则弹窗提示。
        """
        from PyQt5.QtWidgets import QPushButton

        try:
            # === 1️⃣ 获取参数 ===
            gongcheng_zhijing = self.get_gongchengzhijing_count()
            lagan_zhijing = self.get_laganzhijing_count()

            # === 2️⃣ 计算已有拉杆数量（普通拉杆 + 自由拉杆，与左下角统计一致）===
            lagan_count = self._get_total_lagan_count()

            # === 3️⃣ 类型转换并验证有效性 ===
            try:
                gongcheng_zhijing = float(gongcheng_zhijing)
                lagan_zhijing = float(lagan_zhijing)
            except (TypeError, ValueError):
                print("[警告] 参数值无效，跳过检查。")
                return True

            # === 4️⃣ 查找标准要求 ===
            min_required = self._get_lagan_required_count()

            if min_required is None:
                return True

            # === 5️⃣ 弹窗提示判断 ===
            if lagan_count < min_required:
                msg_box = QMessageBox()
                msg_box.setWindowTitle("提示")
                msg_box.setText(
                    f"当前产品公称直径DN为{int(gongcheng_zhijing) if float(gongcheng_zhijing).is_integer() else gongcheng_zhijing}mm，"
                    f"拉杆直径为{int(lagan_zhijing) if float(lagan_zhijing).is_integer() else lagan_zhijing}mm。"
                    f"根据标准要求，拉杆数量不应小于{min_required}根，是否继续保存？"
                )
                # 设置按钮
                yes_button = QPushButton("是")
                no_button = QPushButton("否")
                msg_box.addButton(yes_button, QMessageBox.YesRole)
                msg_box.addButton(no_button, QMessageBox.NoRole)
                ret = msg_box.exec_()
                # 判断用户点击的是哪个按钮
                if msg_box.clickedButton() == yes_button:
                    return True
                else:
                    return False
            return True
        except Exception as e:
            print(f"[错误] 保存前检查时出错: {str(e)}")
            return True  # 避免程序崩溃

    def _notify_save_success_ui(self, message="数据保存成功！"):
        """
        在底部 line_tip 显示保存成功；与主窗体 _tip_timer→clear_line_tip 竞争时先停主定时器，
        避免刚写入即被清空；line_tip 不可用时用 QMessageBox 兜底，保证用户能看到文案。
        """
        # 主窗体单发定时器会清空 line_tip，保存成功后先停掉，避免“有时不显示”
        try:
            import importlib

            mw = None
            for _mod in (sys.modules.get("main"), sys.modules.get("__main__")):
                if _mod is not None:
                    mw = getattr(_mod, "APP_MAIN_WINDOW", None)
                    if mw is not None:
                        break
            if mw is None:
                try:
                    mw = getattr(importlib.import_module("main"), "APP_MAIN_WINDOW", None)
                except Exception:
                    mw = None
            if mw is not None:
                _tm = getattr(mw, "_tip_timer", None)
                if _tm is not None:
                    try:
                        _tm.stop()
                    except Exception:
                        pass
        except Exception:
            pass

        tip_ok = False
        try:
            tip = getattr(self, "line_tip", None)
            if tip is not None:
                tip.setText(message)
                tip.setStyleSheet("color: black;")
                tip.setVisible(True)
                try:
                    tip.setToolTip(message)
                except Exception:
                    pass
                try:
                    tip.repaint()
                except Exception:
                    pass
                tip_ok = True
                try:
                    from PyQt5.QtWidgets import QApplication

                    QApplication.processEvents()
                except Exception:
                    pass
        except Exception as e:
            try:
                print(f"[_notify_save_success_ui] line_tip 写入失败: {e}")
            except Exception:
                pass

        if not tip_ok:
            try:

                QMessageBox.information(self, "提示", message)
            except Exception as e2:
                try:
                    print(message)
                    print(f"[_notify_save_success_ui] 弹窗也失败: {e2}")
                except Exception:
                    pass

        # 用实例上的单发定时器清空，避免 lambda 在 line_tip 已销毁时抛错
        try:
            from PyQt5.QtCore import QTimer

            if not hasattr(self, "_save_success_tip_clear_timer"):
                self._save_success_tip_clear_timer = QTimer(self)
                self._save_success_tip_clear_timer.setSingleShot(True)

            def _safe_clear():
                try:
                    t = getattr(self, "line_tip", None)
                    if t is not None:
                        t.setText("")
                except Exception:
                    pass

            try:
                self._save_success_tip_clear_timer.timeout.disconnect()
            except TypeError:
                pass
            try:
                self._save_success_tip_clear_timer.timeout.connect(_safe_clear)
                self._save_success_tip_clear_timer.start(5000)
            except Exception as e3:
                try:
                    print(f"[_notify_save_success_ui] 启动清空定时器失败: {e3}")
                except Exception:
                    pass
        except Exception as e4:
            try:
                print(f"[_notify_save_success_ui] 定时器创建失败: {e4}")
            except Exception:
                pass

    # 10/29 修改，布管界面保存时需要先判断，满足条件才保存
    def save_data(self):
        current_page_index = self.header.currentIndex()

        # 统一逻辑：不论在哪个界面点“保存”，都尝试把多个页面的“当前数据”落库
        # 说明：
        # - 各页面数据可能为空/未编辑，此时对应保存逻辑会自行跳过或写入空集（按原实现）
        # - 布管页面若尚未布管(has_piped=False)：静默跳过，避免在其他页面保存时弹窗打断
        # - 若当前就在布管页面：仍执行原有的保存前检查
        if current_page_index == 1:
            if not self.check_before_save():
                return

        try:
            # 保存顺序：先管板形式(0) → 布管(1) → 管-板连接(2) → 轴向设计(3)
            # 其中 1/3 的分支内部会有自身的“空数据直接返回”逻辑
            for idx in (0, 1, 2, 3):
                try:
                    # 非布管页触发的全量保存：布管未布管时不弹窗
                    silent = (idx == 1 and current_page_index != 1)
                    self.actual_save_operation(idx, silent=silent)
                except Exception as e:
                    print(f"[save_data] 保存 page_index={idx} 失败: {e}")

            if current_page_index == 0:
                try:
                    self.clear_modification_marks()
                except Exception:
                    pass
        except Exception as e:
            try:
                print(f"[save_data] 保存流程异常: {e}")
                import traceback

                traceback.print_exc()
            except Exception:
                pass
        finally:
            try:
                self._notify_save_success_ui("数据保存成功！")
            except Exception as e:
                try:
                    print(f"[save_data] 成功提示仍失败: {e}")
                except Exception:
                    pass
                try:

                    QMessageBox.information(self, "提示", "数据保存成功！")
                except Exception:
                    try:
                        print("数据保存成功！")
                    except Exception:
                        pass

    def build_sql_for_screw_ring(self):
        """吊环螺钉：逻辑已迁移至 component/screw_ring.py。"""
        from modules.buguan.buguan_ziyong.component.screw_ring import (
            build_sql_for_screw_ring as _build_sql_for_screw_ring,
        )

        return _build_sql_for_screw_ring(self)

    def build_sql_for_u_tube_calculation_results(
        self,
        product_id=None,
        tube_form=None,
        max_x_gap=0.0,
        max_y_gap=0.0,
        horizontal_total=0,
        snh_val=0.0,
        sn_val=0.0,
        s_val=0.0,
        tubes_count=0,
        getiao_chicun=0.0,
        is_deleted=None,
    ):
        """
        生成 U 型管布管计算结果表（产品设计活动表_布管计算结果表）的 SQL 语句。

        说明：
        - 这段逻辑之前误落在 build_sql_for_screw_ring() 的 return 之后，导致 IDE 视为不可达（变灰）。
        - 现在抽成独立函数，供需要时显式调用，保证可达且不影响“吊环螺钉保存”流程。
        """
        # --- 参数兜底/初始化（避免未定义变量导致 IDE 灰显/运行错误）---
        if product_id is None:
            product_id = getattr(self, "productID", None)
        if tube_form is None:
            try:
                tube_form = str(self.get_tube_pass_count()).strip()
            except Exception:
                tube_form = ""
        if not callable(is_deleted):
            is_deleted = lambda x, y: False

        calc_results = {}

        try:
            max_x_gap = float(max_x_gap or 0.0)
        except Exception:
            max_x_gap = 0.0
        try:
            max_y_gap = float(max_y_gap or 0.0)
        except Exception:
            max_y_gap = 0.0
        try:
            horizontal_total = int(horizontal_total or 0)
        except Exception:
            horizontal_total = 0
        try:
            snh_val = float(snh_val or 0.0)
        except Exception:
            snh_val = 0.0
        try:
            sn_val = float(sn_val or 0.0)
        except Exception:
            sn_val = 0.0
        try:
            s_val = float(s_val or 0.0)
        except Exception:
            s_val = 0.0
        try:
            tubes_count = int(float(tubes_count or 0))
        except Exception:
            tubes_count = 0
        try:
            getiao_chicun = float(getiao_chicun or 0.0)
        except Exception:
            getiao_chicun = 0.0

        # U型管弯曲直径：取最大X/Y间距的较大值（保留3位小数）
        u_max_diameter = max(max_x_gap, max_y_gap) * 2
        u_max_diameter = round(u_max_diameter, 3)

        # 3.2 计算沿竖直隔板槽一侧的排管根数（基于管程程数）
        vertical_total = 0
        if tube_form == "2":
            # 管程=2时，竖直隔板排管根数固定为0（原逻辑）
            horizontal_total = 0
            conn = create_product_connection()
            if conn:
                with conn.cursor(pymysql.cursors.DictCursor) as cursor:
                    cursor.execute(
                        """
                            SELECT CAST(`至水平中心线行号` AS SIGNED) AS line_no,
                                   `管孔数量（上）`, `管孔数量（下）`
                            FROM 产品设计活动表_布管数量表_显示
                            WHERE 产品ID = %s
                            ORDER BY line_no ASC
                        """,
                        (product_id,),
                    )
                    qty_rows = cursor.fetchall() or []

                    if qty_rows:
                        # 逐行按升序查，找到第一个 下 管孔数量 > 0 的就用它
                        for r in qty_rows:
                            # 解析行号（保险起见）
                            try:
                                line_no = int(r.get("line_no", 0))
                            except Exception:
                                line_no = 0

                            # 解析下值为整数（若为 None、"None"、"" 或 "0" 则视为 0）
                            raw_down = r.get("管孔数量（下）")
                            try:
                                down_val = (
                                    int(raw_down)
                                    if (
                                            raw_down is not None
                                            and str(raw_down).strip() not in ("", "None")
                                    )
                                    else 0
                                )
                            except Exception:
                                down_val = 0

                            if down_val > 0:
                                vertical_total = down_val
                                break
            calc_results["沿水平隔板槽一侧的排管根数"] = str(int(vertical_total))

        elif tube_form == "4":
            # 管程≠2时，从布管数量表_显示按至水平中心线行号升序查找第一个管孔数量（下）不为0的值作为 vertical_total
            try:
                conn = create_product_connection()
                if conn:
                    with conn.cursor(pymysql.cursors.DictCursor) as cursor:
                        cursor.execute(
                            """
                                SELECT CAST(`至水平中心线行号` AS SIGNED) AS line_no,
                                       `管孔数量（上）`, `管孔数量（下）`
                                FROM 产品设计活动表_布管数量表_显示
                                WHERE 产品ID = %s
                                ORDER BY line_no ASC
                            """,
                            (product_id,),
                        )
                        qty_rows = cursor.fetchall() or []

                        vertical_total = 0
                        if qty_rows:
                            # 逐行按升序查，找到第一个 下 管孔数量 > 0 的就用它
                            for r in qty_rows:
                                # 解析行号（保险起见）
                                try:
                                    line_no = int(r.get("line_no", 0))
                                except Exception:
                                    line_no = 0

                                # 解析下值为整数（若为 None、"None"、"" 或 "0" 则视为 0）
                                raw_down = r.get("管孔数量（下）")
                                try:
                                    down_val = (
                                        int(raw_down)
                                        if (
                                                raw_down is not None
                                                and str(raw_down).strip()
                                                not in ("", "None")
                                        )
                                        else 0
                                    )
                                except Exception:
                                    down_val = 0

                                if down_val > 0:
                                    vertical_total = down_val
                                    break
                        # 如果没有任何不为0的，则 vertical_total 保持 0

            except Exception as e:
                # 根据你现有代码风格处理异常（这里示例打印）
                print("读取布管数量表出错：", e)
                vertical_total = 0
            finally:
                if conn and conn.open:
                    conn.close()
            calc_results["沿水平隔板槽一侧的排管根数"] = str(int(vertical_total))

        elif tube_form == "6":
            coords = []
            for center in self.current_centers:
                if len(center) >= 2:
                    x = float(center[0])
                    y = float(center[1])
                    coords.append((x, y))
            if not coords:
                # QMessageBox.warning(self, "警告", "布管坐标数据为空或格式无效！")
                return None
            filtered_coords = [(x, y) for x, y in coords if not is_deleted(x, y)]

            y_above = [y for x, y in filtered_coords if y < getiao_chicun]
            positive_ys = [y for x, y in filtered_coords if y > 0]
            if positive_ys:
                target_y = min(positive_ys)
            else:
                all_ys = [y for x, y in filtered_coords]
                target_y = min(all_ys) if all_ys else 0.0
            # 筛选目标y的坐标
            selected_coords_cross = []

            # if y_above:
            #     min_above_y = min(y_above)
            #     selected_coords_cross.extend([
            #         (x, y) for x, y in filtered_coords
            #         if abs(y - min_above_y) < 1e-6
            #     ])
            # # 下侧：y<-getiao_chicun的最大y
            y_below = [y for x, y in filtered_coords if y > -getiao_chicun]
            if y_below:
                max_below_y = min(y_below)
                selected_coords_cross.extend(
                    [(x, y) for x, y in filtered_coords if abs(y - max_below_y) < 1e-6]
                )
            # 赋值排管根数和管排1中心距
            calc_results["沿水平隔板槽一侧的排管根数"] = str(len(selected_coords_cross))

        # calc_results["沿水平隔板槽一侧的排管根数"] = str(int(vertical_total))
        calc_results["沿竖直隔板槽一侧的排管根数"] = str(horizontal_total)
        calc_results["水平隔板槽两侧相邻管中心距"] = str(round(snh_val, 3))
        calc_results["垂直隔板槽两侧相邻管中心距"] = str(round(sn_val, 3))
        calc_results["换热管中心距 S"] = str(round(s_val, 3))
        calc_results["U型管弯曲直径"] = str(u_max_diameter)
        calc_results["管总数 tubes_count"] = str(tubes_count)

        table_name = "`产品设计活动表_布管计算结果表`"
        sql_statements = []

        # SQL转义函数：防止单引号导致的SQL注入
        def escape_sql(value):
            if isinstance(value, str):
                return value.replace("'", "''")  # 单引号替换为两个单引号
            return str(value)

        delete_sql = (
            f"DELETE FROM {table_name} "
            f"WHERE `产品ID` = '{escape_sql(product_id)}' "
            f"AND `产品类型` = '2'"  # U型管产品类型固定为2
        )
        sql_statements.append(delete_sql)

        for calc_name, calc_val in calc_results.items():
            esc_product_id = escape_sql(product_id)
            esc_calc_name = escape_sql(calc_name)
            esc_calc_val = escape_sql(calc_val)
            esc_product_type = "2"

            insert_sql = (
                f"INSERT INTO {table_name} "
                f"(`产品ID`, `计算值名称`, `计算值`, `产品类型`) "
                f"VALUES ("
                f"'{esc_product_id}', "
                f"'{esc_calc_name}', "
                f"'{esc_calc_val}', "
                f"'{esc_product_type}'"
                f")"
            )
            sql_statements.append(insert_sql)

        return sql_statements

    def build_sql_for_cross_pipes(self):
        import json

        table_name = "`产品设计活动表_布管交叉布管表`"
        product_id = self.productID
        sql_statements = []

        # 1. 基础参数合法性校验：产品ID不可为空
        if not product_id or str(product_id).strip() == "":
            # QMessageBox.warning(self, "警告", "缺少必要的产品ID参数！")
            return None

        def process_row(x2, y2, x4, y4):
            """
            处理单排交叉布管数据，返回三个结果：
            - 布管数据列表（非空的x/y列表）
            - 交叉类型（0/2/4）
            - 轴类型（x/y，若均为空则返回空字符串）
            """
            # 检查2管交叉：x2非空则用x2，否则用y2
            if x2:
                return x2, 2, "x"
            elif y2:
                return y2, 2, "y"
            # 检查4管交叉：x4非空则用x4，否则用y4
            elif x4:
                return x4, 4, "x"
            elif y4:
                return y4, 4, "y"
            # 所有列表均为空：未布置交叉布管
            else:
                return [], 0, ""  # 空列表+类型0+空轴标识

        # 2. 分别处理第一、二、三排数据（含轴类型判断）
        # 第一排
        first_row_data, first_row_type, axis_type = process_row(
            self.coord_x_line1_2,
            self.coord_y_line1_2,
            self.coord_x_line1_4,
            self.coord_y_line1_4,
        )
        # 第二排
        second_row_data, second_row_type, _ = process_row(
            self.coord_x_line2_2,
            self.coord_y_line2_2,
            self.coord_x_line2_4,
            self.coord_y_line2_4,
        )
        # 第三排
        third_row_data, third_row_type, _ = process_row(
            self.coord_x_line3_2,
            self.coord_y_line3_2,
            self.coord_x_line3_4,
            self.coord_y_line3_4,
        )

        # 3. 处理数据格式：保持元组括号，空列表转换为"0"
        def format_data(data):
            if not data:  # 空列表处理
                return "0"
            # 将列表中的元组转换为字符串形式保持括号
            return str(data).replace("[", "[").replace("]", "]")

        # 处理绝对坐标对：转换为JSON字符串
        def format_abs_coords(abs_coords):
            if not abs_coords:  # 空列表处理
                return "0"
            try:
                # 将绝对坐标对转换为JSON字符串
                return json.dumps(abs_coords, ensure_ascii=False)
            except Exception as e:
                print(f"序列化绝对坐标对时出错: {e}")
                return "0"

        first_row_str = format_data(first_row_data)
        second_row_str = format_data(second_row_data)
        third_row_str = format_data(third_row_data)

        # 直接使用当前排维护的绝对坐标对（每排“全部配对”），并规范化去重后入库。
        # 不再从 cross_pipe_lines 反推，避免“每对两条线重复”及行归属误判造成入库不正确。
        def normalize_abs_coord_pairs(raw_pairs):
            normalized = []
            seen = set()
            if not isinstance(raw_pairs, (list, tuple)):
                return normalized
            for pair in raw_pairs:
                if not (isinstance(pair, (list, tuple)) and len(pair) == 2):
                    continue
                p1, p2 = pair
                if not (
                    isinstance(p1, (list, tuple))
                    and isinstance(p2, (list, tuple))
                    and len(p1) == 2
                    and len(p2) == 2
                ):
                    continue
                try:
                    x1, y1 = float(p1[0]), float(p1[1])
                    x2, y2 = float(p2[0]), float(p2[1])
                except Exception:
                    continue
                k1 = (round(x1, 6), round(y1, 6))
                k2 = (round(x2, 6), round(y2, 6))
                pair_key = tuple(sorted((k1, k2)))
                if pair_key in seen:
                    continue
                seen.add(pair_key)
                normalized.append([[x1, y1], [x2, y2]])
            return normalized

        first_abs_coords = normalize_abs_coord_pairs(getattr(self, "abs_coords_line1", []))
        second_abs_coords = normalize_abs_coord_pairs(getattr(self, "abs_coords_line2", []))
        third_abs_coords = normalize_abs_coord_pairs(getattr(self, "abs_coords_line3", []))

        first_abs_str = format_abs_coords(first_abs_coords)
        second_abs_str = format_abs_coords(second_abs_coords)
        third_abs_str = format_abs_coords(third_abs_coords)

        # 4. 构建SQL：先删除当前产品的旧记录（避免数据冗余）
        delete_sql = f"DELETE FROM {table_name} WHERE `产品ID` = '{product_id}'"
        sql_statements.append(delete_sql)

        # 5. 构建插入SQL：新增绝对坐标对字段
        # 转义单引号，避免SQL注入
        def escape_sql_str(s):
            if s == "0":
                return "0"
            return s.replace("'", "''")

        first_abs_str_escaped = escape_sql_str(first_abs_str)
        second_abs_str_escaped = escape_sql_str(second_abs_str)
        third_abs_str_escaped = escape_sql_str(third_abs_str)

        insert_sql = (
            f"INSERT INTO {table_name} ("
            f"`产品ID`, `第一排`, `第二排`, `第三排`, "
            f"`第一排交叉类型`, `第二排交叉类型`, `第三排交叉类型`, `x轴或y轴`, "
            f"`第一排绝对坐标对`, `第二排绝对坐标对`, `第三排绝对坐标对`) "
            f"VALUES ("
            f"'{product_id}', '{first_row_str}', '{second_row_str}', '{third_row_str}', "
            f"{first_row_type}, {second_row_type}, {third_row_type}, "
            f"'{axis_type}', "
            f"'{first_abs_str_escaped}', '{second_abs_str_escaped}', '{third_abs_str_escaped}')"
        )
        sql_statements.append(insert_sql)

        # 6. 数据库连接与SQL执行（保持原有事务逻辑）
        conn = create_product_connection()
        if not conn:
            # QMessageBox.critical(self, "数据库错误", "无法建立数据库连接！")
            return None
        try:
            with conn.cursor() as cursor:
                for sql in sql_statements:
                    cursor.execute(sql)
            conn.commit()
            return sql_statements

        except pymysql.Error as e:
            # 错误时回滚，避免数据不一致
            conn.rollback()

            return None

        finally:
            if conn and conn.open:
                conn.close()

    def build_sql_for_tube_sheet_connection(self):
        # 从管板连接页面获取参数
        page_data = self.tube_sheet_page.get_current_parameters()
        # print(f"🔍 [调试] 获取到的page_data类型: {type(page_data)}")
        # print(f"🔍 [调试] 获取到的page_data内容: {page_data}")
        # print(f"🔍 [调试] page_data长度: {len(page_data) if page_data else 0}")

        if not page_data:
            print("❌ [调试] page_data为空，返回None")
            return None
        table_name = "`产品设计活动表_管板连接表`"

        def escape_str(value):
            if isinstance(value, str):
                # 只转义单引号，其他字符保持原样
                return value.replace("'", "''")
            return str(value) if value is not None else ""

        # 获取选中图片的绝对路径
        connection_diagram = ""
        for label in self.tube_sheet_page.image_labels:
            if label.property("selected"):
                connection_diagram = getattr(label, "image_path", "")
                if connection_diagram:
                    connection_diagram = os.path.abspath(connection_diagram)
                break

        connection_type = ""
        tube_sheet_type_str = ""
        # print(f"🔍 [调试] 开始解析page_data中的参数:")
        for i, param in enumerate(page_data):
            # print(f"🔍 [调试] 参数{i}: {param} (类型: {type(param)})")
            # param 是元组格式 (参数名, 参数值)
            param_name = param[0]  # 参数名
            param_value = param[1]  # 参数值
            # print(f"🔍 [调试] 参数名: '{param_name}', 参数值: '{param_value}'")
            if param_name == "换热管与管板连接方式":
                connection_type = param_value
                # print(f"✅ [调试] 找到连接方式: '{connection_type}'")
            elif param_name == "管板类型":
                tube_sheet_type_str = param_value
                # print(f"✅ [调试] 找到管板类型: '{tube_sheet_type_str}'")

        # print(f"🔍 [调试] 解析完成后的结果:")
        # print(f"🔍 [调试] connection_type: '{connection_type}' (长度: {len(connection_type) if connection_type else 0})")
        # print(
        #     f"🔍 [调试] tube_sheet_type_str: '{tube_sheet_type_str}' (长度: {len(tube_sheet_type_str) if tube_sheet_type_str else 0})")

        # 管板类型直接使用，不需要映射
        tube_sheet_type = tube_sheet_type_str
        # print(f"🔍 [调试] 最终连接方式: '{connection_type}'")
        # print(f"🔍 [调试] 最终管板类型字符串: '{tube_sheet_type_str}'")
        # print(f"🔍 [调试] 直接使用的管板类型: '{tube_sheet_type}'")

        # 检查关键参数是否为空
        if not connection_type or not tube_sheet_type:
            # print(f"❌ [调试] 关键参数为空！连接方式: '{connection_type}', 管板类型: '{tube_sheet_type}'")
            # print(f"❌ [调试] 无法执行数据库操作，返回None")
            return None

        filtered_params = page_data[2:] if len(page_data) >= 2 else []
        # print(f"🔍 [调试] 过滤后的参数数量: {len(filtered_params)}")
        # print(f"🔍 [调试] 过滤后的参数内容: {filtered_params}")
        if not filtered_params:
            return None

        # 生成SQL语句列表
        sql_statements = []
        product_id = escape_str(self.productID)
        safe_connection_type = escape_str(connection_type)
        safe_tube_sheet_type = escape_str(tube_sheet_type)
        safe_diagram = escape_str(connection_diagram)

        # 先删除该产品ID下的所有旧记录
        delete_sql = f"DELETE FROM {table_name} WHERE " f"`产品ID` = '{product_id}';"
        sql_statements.append(delete_sql)
        # print(f"✅ [调试] 添加DELETE语句: {delete_sql}")

        # 再把当前过滤后的所有参数作为新记录插入
        for param in filtered_params:
            # param 是元组格式 (参数名, 参数值)
            param_name = param[0]  # 参数名
            param_value = param[1]  # 参数值

            safe_param_name = escape_str(param_name)
            safe_param_value = escape_str(param_value)

            insert_sql = (
                f"INSERT INTO {table_name} ("
                f"`产品ID`, `参数名`, `参数值`, `管板连接示意图`, "
                f"`管板连接方式`, `管板类型`, `管板连接更改状态`"
                f") VALUES ("
                f"'{product_id}', '{safe_param_name}', '{safe_param_value}', '{safe_diagram}', "
                f"'{safe_connection_type}', '{safe_tube_sheet_type}', '1'"
                f");"
            )
            sql_statements.append(insert_sql)

        result = "; ".join(sql_statements) if sql_statements else None
        return result

    @staticmethod
    def _build_axis_cluster_reps(abs_values, merge_tol=1.0):
        """将绝对坐标值按 merge_tol 合并为簇，返回升序簇代表值列表。"""
        if not abs_values:
            return []
        sorted_vals = sorted(float(v) for v in abs_values)
        reps = [sorted_vals[0]]
        for v in sorted_vals[1:]:
            if v - reps[-1] > float(merge_tol) + 1e-9:
                reps.append(v)
        return reps

    @staticmethod
    def _nearest_axis_cluster_key(abs_value, cluster_reps, merge_tol=1.0):
        """返回 abs_value 在容差内最近簇的下标；无匹配则返回 None。"""
        abs_v = abs(float(abs_value))
        best_i = None
        best_d = None
        for i, rep in enumerate(cluster_reps):
            d = abs(abs_v - rep)
            if d <= float(merge_tol) + 1e-9:
                if best_d is None or d < best_d:
                    best_i = i
                    best_d = d
        return best_i

    def _get_x_cluster_reps(self, merge_tol=None):
        """满布 global_centers 上的列簇代表（带缓存）。"""
        if merge_tol is None:
            merge_tol = self.AXIS_GROUP_TOL
        gc = getattr(self, "global_centers", None) or []
        cache = getattr(self, "_x_cluster_reps_cache", None)
        cache_key = (float(merge_tol), len(gc))
        if cache and cache[0] == cache_key:
            return cache[1]
        abs_x = [abs(float(x)) for x, _y in gc]
        reps = self._build_axis_cluster_reps(abs_x, merge_tol)
        self._x_cluster_reps_cache = (cache_key, reps)
        return reps

    def _get_y_cluster_reps(self, merge_tol=None):
        """满布 global_centers 上的行簇代表（带缓存）。"""
        if merge_tol is None:
            merge_tol = self.AXIS_GROUP_TOL
        gc = getattr(self, "global_centers", None) or []
        cache = getattr(self, "_y_cluster_reps_cache", None)
        cache_key = (float(merge_tol), len(gc))
        if cache and cache[0] == cache_key:
            return cache[1]
        abs_y = [abs(float(y)) for _x, y in gc]
        reps = self._build_axis_cluster_reps(abs_y, merge_tol)
        self._y_cluster_reps_cache = (cache_key, reps)
        return reps

    def _invalidate_axis_cluster_cache(self):
        """global_centers 变更后清除行/列簇缓存。"""
        self._x_cluster_reps_cache = None
        self._y_cluster_reps_cache = None
        try:
            self._coord_to_col_cache_key = None
        except Exception:
            pass

    def _vertical_col_key(self, x, merge_tol=None):
        """竖直表按列分组键：与 group_centers_by_x 一致，容差内视为同一列。"""
        if merge_tol is None:
            merge_tol = self.AXIS_GROUP_TOL
        reps = self._get_x_cluster_reps(merge_tol)
        if not reps:
            return 0
        key = self._nearest_axis_cluster_key(abs(float(x)), reps, merge_tol)
        if key is None:
            key = min(
                range(len(reps)),
                key=lambda i: abs(abs(float(x)) - reps[i]),
            )
        return key

    def _unique_positive_x_by_col_key(self, centers, merge_tol=None):
        """竖直表 R 计算：按列键去重后的 x 坐标（升序）。"""
        if merge_tol is None:
            merge_tol = self.AXIS_GROUP_TOL
        reps = self._get_x_cluster_reps(merge_tol)
        keys = set()
        for x, _y in centers:
            if float(x) >= 0:
                k = self._nearest_axis_cluster_key(abs(float(x)), reps, merge_tol)
                if k is not None:
                    keys.add(k)
        return [reps[k] for k in sorted(keys)]

    def build_sql_for_tube_hole(self, tube_hole_data):
        self.sorted_current_centers_left, self.sorted_current_centers_right = (
            self.group_centers_by_x(self.current_centers)
        )
        self.sorted_current_centers_up, self.sorted_current_centers_down = (
            self.group_centers_by_y(self.current_centers)
        )
        if not tube_hole_data:
            return None
        tube_num = self.get_tube_pass_count()

        # 验证产品ID是否存在
        if not hasattr(self, "productID") or not self.productID:
            return None

        # 处理产品ID的SQL注入防护
        safe_product_id = self.productID.replace("'", "''")

        # 判断使用哪个表
        use_vertical_table = False
        if self.heat_exchanger in ["AEU", "BEU", "AKU", "BKU"]:
            # AEU/BEU型号：2管程用水平表，其他管程用竖直表
            if tube_num != "2":
                use_vertical_table = True

        if use_vertical_table:
            # 使用竖直表（按列分组）
            # print(f"[build_sql_for_tube_hole] 使用竖直表，管程数={tube_num}")
            table_name = "产品设计活动表_布管数量表_竖直"
            other_table_name = "产品设计活动表_布管数量表_水平"

            # 构建查询SQL：检查是否存在该产品ID的记录
            query_sql = f"SELECT 1 FROM {table_name} WHERE `产品ID` = '{safe_product_id}' LIMIT 1;"

            # 构建删除另一个表的SQL：删除水平表中该产品ID的所有记录
            delete_other_table_sql = (
                f"DELETE FROM {other_table_name} WHERE `产品ID` = '{safe_product_id}';"
            )

            # 构建删除SQL：仅删除该产品ID的记录
            delete_sql = (
                f"DELETE FROM {table_name} WHERE `产品ID` = '{safe_product_id}';"
            )

            # 构建插入数据的SQL语句（竖直表使用列号、左/右）
            insert_sql = f"INSERT INTO {table_name} (`产品ID`, `至竖直中心线行号`, `管孔数量（左）`, `管孔数量（右）`) VALUES "
            values = []

            # 直接从 global_centers 和 current_centers 计算列分组
            # 与 group_centers_by_x 一致：统一用 abs(x) 列键，左右对称列占同一行
            from collections import defaultdict

            merge_tol = self.AXIS_GROUP_TOL
            master_reps = self._get_x_cluster_reps(merge_tol)

            # 1. 满布状态的所有列键（簇下标）
            global_col_keys = set(range(len(master_reps)))

            # 2. 当前状态按列键分组
            current_left_groups = defaultdict(list)
            current_right_groups = defaultdict(list)
            for x, y in self.current_centers:
                col_key = self._vertical_col_key(x, merge_tol)
                if float(x) < 0:
                    current_left_groups[col_key].append((x, y))
                else:
                    current_right_groups[col_key].append((x, y))

            sorted_col_keys = sorted(global_col_keys)

            # 3. 遍历所有列（包括空列）
            for i, col_key in enumerate(sorted_col_keys):
                # 行号（从1开始）
                line_num = str(i + 1)

                holes_left = len(current_left_groups.get(col_key, []))
                holes_right = len(current_right_groups.get(col_key, []))

                # 转义单引号防止SQL注入
                safe_line_num = line_num.replace("'", "''")
                safe_holes_left = str(holes_left)
                safe_holes_right = str(holes_right)

                # 加入产品ID到VALUES中（即使数量为0也要插入记录）
                values.append(
                    f"('{safe_product_id}', '{safe_line_num}', '{safe_holes_left}', '{safe_holes_right}')"
                )

                # print(f"[build_sql_for_tube_hole] 列{i+1}: 左={holes_left}, 右={holes_right}")

            # print(f"[build_sql_for_tube_hole] 生成了 {len(values)} 条记录")
            if values:
                # print(f"[build_sql_for_tube_hole] 第一条记录: {values[0]}")
                # print(f"[build_sql_for_tube_hole] 最后一条记录: {values[-1]}")
                insert_sql += ",\n".join(values) + ";"
            else:
                # print(f"[build_sql_for_tube_hole] ❌ values 列表为空，无法生成 INSERT SQL")
                return None

        else:
            # 使用水平表（按行分组）- 原逻辑
            table_name = "产品设计活动表_布管数量表_水平"
            other_table_name = "产品设计活动表_布管数量表_竖直"

            # 构建查询SQL：检查是否存在该产品ID的记录
            query_sql = f"SELECT 1 FROM {table_name} WHERE `产品ID` = '{safe_product_id}' LIMIT 1;"

            # 构建删除另一个表的SQL：删除竖直表中该产品ID的所有记录
            delete_other_table_sql = (
                f"DELETE FROM {other_table_name} WHERE `产品ID` = '{safe_product_id}';"
            )

            # 构建删除SQL：仅删除该产品ID的记录
            delete_sql = (
                f"DELETE FROM {table_name} WHERE `产品ID` = '{safe_product_id}';"
            )

            # 构建插入数据的SQL语句，增加产品ID字段
            insert_sql = f"INSERT INTO {table_name} (`产品ID`, `至水平中心线行号`, `管孔数量（上）`, `管孔数量（下）`) VALUES "
            values = []

            for data in tube_hole_data:
                line_num = data.get("至水平中心线行号", "")
                holes_up = data.get("管孔数量(上)", "")
                holes_down = data.get("管孔数量(下)", "")

                # 转义单引号防止SQL注入
                safe_line_num = line_num.replace("'", "''")
                safe_holes_up = (
                    holes_up.replace("'", "''") if holes_up is not None else ""
                )
                safe_holes_down = (
                    holes_down.replace("'", "''") if holes_down is not None else ""
                )

                # 加入产品ID到VALUES中
                values.append(
                    f"('{safe_product_id}', '{safe_line_num}', '{safe_holes_up}', '{safe_holes_down}')"
                )

            insert_sql += ",\n".join(values) + ";"

        # 返回SQL语句列表：查询 -> 删除另一个表 -> 删除当前表 -> 插入
        # 调用方需要按顺序执行这些SQL语句
        return [query_sql, delete_other_table_sql, delete_sql, insert_sql]

    def build_sql_for_tube_hole_present(self, tube_hole_data):
        """构建布管数量表_显示的SQL语句"""
        if not tube_hole_data:
            return None

        # 验证产品ID是否存在
        if not hasattr(self, "productID") or not self.productID:
            return None

        # 处理产品ID的SQL注入防护
        safe_product_id = self.productID.replace("'", "''")

        # 表名
        table_name = "产品设计活动表_布管数量表_显示"

        # 构建查询SQL：检查是否存在该产品ID的记录
        query_sql = (
            f"SELECT 1 FROM {table_name} WHERE `产品ID` = '{safe_product_id}' LIMIT 1;"
        )

        # 构建删除SQL：仅删除该产品ID的记录
        delete_sql = f"DELETE FROM {table_name} WHERE `产品ID` = '{safe_product_id}';"

        # 构建插入数据的SQL语句，增加产品ID字段
        insert_sql = f"INSERT INTO {table_name} (`产品ID`, `至水平中心线行号`, `管孔数量（上）`, `管孔数量（下）`, `删除管孔位置`, `R`) VALUES "
        values = []

        for data in tube_hole_data:
            line_num = data.get("至水平中心线行号", "")
            holes_up = data.get("管孔数量(上)", "")
            holes_down = data.get("管孔数量(下)", "")
            deleted_positions = data.get("删除管孔位置", "")
            r_value = data.get("R", "")

            # 转义单引号防止SQL注入
            safe_line_num = line_num.replace("'", "''")
            safe_holes_up = holes_up.replace("'", "''") if holes_up is not None else ""
            safe_holes_down = (
                holes_down.replace("'", "''") if holes_down is not None else ""
            )
            safe_deleted_positions = (
                deleted_positions.replace("'", "''")
                if deleted_positions is not None
                else ""
            )
            safe_r_value = r_value.replace("'", "''") if r_value is not None else ""

            # 加入产品ID到VALUES中
            values.append(
                f"('{safe_product_id}', '{safe_line_num}', '{safe_holes_up}', '{safe_holes_down}', '{safe_deleted_positions}', '{safe_r_value}')"
            )

        insert_sql += ",\n".join(values) + ";"

        # 返回SQL语句列表：查询 -> 删除 -> 插入
        # 调用方需要按顺序执行这些SQL语句
        return [query_sql, delete_sql, insert_sql]

    def build_sql_for_radial_holes(self):
        if not hasattr(self, "productID") or not self.productID:
            return None

        table_name = "`产品设计活动表_布管管口表`"

        def escape_str(value):
            return value.replace("'", "''") if isinstance(value, str) else value

        safe_product_id = escape_str(str(self.productID))

        # Always include the delete SQL to clear existing records
        delete_sql = f"DELETE FROM {table_name} WHERE `产品ID` = '{safe_product_id}';"

        # If there's no radial hole data, just return the delete SQL
        if (
                not isinstance(getattr(self, "radial_hole_dict", None), dict)
                or not self.radial_hole_dict
        ):
            return [delete_sql]

        insert_sqls = []
        for code, info in self.radial_hole_dict.items():
            if not isinstance(info, dict):
                continue
            port_code = escape_str(str(code))
            direction = escape_str(str(info.get("连通方向", "壳程") or "壳程"))

            coord = info.get("换热管坐标")
            if coord is None:
                coord_str = ""
            else:
                try:
                    coord_str = f"({float(coord[0])}, {float(coord[1])})"
                except Exception:
                    coord_str = str(coord)
            coord_str = escape_str(coord_str)

            insert_sqls.append(
                f"INSERT INTO {table_name} (`产品ID`, `管口号`, `连通方向`, `坐标`) "
                f"VALUES ('{safe_product_id}', '{port_code}', '{direction}', '{coord_str}');"
            )

        if not insert_sqls:
            return None

        return [delete_sql] + insert_sqls

    def build_sql_for_tube_form(self):
        """构建管板形式表的SQL语句，处理元组列表格式的参数"""
        if not self.tube_form_data:
            return None

        table_name = "`产品设计活动表_管板形式表`"
        product_id = self.productID

        def escape_str(value):
            if isinstance(value, str):
                # 只转义单引号，其他字符保持原样
                return value.replace("'", "''")
            return value


        # 解析参数，获取管板类型
        plate_type = ""
        for param in self.tube_form_data:
            if param[0] == "管板类型":  # param是元组格式 (参数名, 参数值)
                plate_type = param[1]
                break

        if not plate_type:
            return None

        # 构建图片路径
        try:
            cleaned_type = plate_type.replace("型管板", "")
            image_name = f"{cleaned_type}.png"

            current_dir = os.path.dirname(os.path.abspath(__file__))
            image_base_path = os.path.join(
                current_dir, "static", "管板与壳体、管箱的连接"
            )
            first_char = image_name[0] if image_name else ""
            image_path = os.path.join(image_base_path, first_char, image_name)
            # 转换为绝对路径
            image_path = os.path.abspath(image_path)
        except Exception as e:
            print(f"路径计算失败: {e}")
            return None

        # 转义路径
        safe_image = escape_str(image_path)
        safe_type = escape_str(cleaned_type)
        safe_product_id = escape_str(product_id)

        sql_statements = []

        # 先按产品ID整体删除旧记录
        delete_sql = (
            f"DELETE FROM {table_name} WHERE " f"`产品ID` = '{safe_product_id}';"
        )
        sql_statements.append(delete_sql)

        # 再插入当前这次的所有管板形式参数（跳过管板类型参数）
        for param in self.tube_form_data:
            param_name = param[0]  # 参数名
            param_value = param[1]  # 参数值

            if param_name == "管板类型":
                continue  # 跳过管板类型参数

            safe_symbol = escape_str(param_name)
            safe_value = escape_str(param_value)

            insert_sql = (
                f"INSERT INTO {table_name} ("
                f"`产品ID`, `管板形式示意图`, `管板类型`, `参数符号`, `管板形式更改状态`, `默认值`"
                f") VALUES ("
                f"'{safe_product_id}', '{safe_image}', '{safe_type}', '{safe_symbol}', '1', '{safe_value}'"
                f");"
            )
            sql_statements.append(insert_sql)
        return sql_statements

    def save_current_centers_to_product_json(self):
        """
        将当前 self.current_centers 保存到 `{目标目录}/{productID}.json`。
        目标目录规则：
        1) 优先查询产品设计活动表中的“产品文件夹绝对路径”
        2) 若未查到、为空或不可用，则回退到 `modules/buguan/buguan_ziyong/coords`
        """
        try:
            product_id = getattr(self, "productID", None)
        except Exception:
            product_id = None
        if product_id is None or str(product_id).strip() == "":
            product_id = "unknown"
        product_id = str(product_id).strip()

        fallback_dir = os.path.join(os.path.dirname(__file__), "coords")
        target_dir = None

        # 优先从产品设计活动表读取“产品文件夹绝对路径”
        conn = None
        try:
            conn = create_product_connection()
            if conn:
                with conn.cursor() as cursor:
                    cursor.execute(
                        """
                        SELECT 产品文件夹绝对路径
                        FROM 产品设计活动表
                        WHERE 产品ID = %s
                        LIMIT 1
                        """,
                        (product_id,),
                    )
                    row = cursor.fetchone()
                    if row and isinstance(row, dict):
                        db_dir = row.get("产品文件夹绝对路径")
                        if db_dir is not None:
                            db_dir = str(db_dir).strip()
                            if db_dir:
                                target_dir = db_dir
        except Exception:
            target_dir = None
        finally:
            try:
                if conn and conn.open:
                    conn.close()
            except Exception:
                pass

        # 目录可用性兜底：目标目录异常时回退到原 coords 目录
        if not target_dir:
            target_dir = fallback_dir
        try:
            os.makedirs(target_dir, exist_ok=True)
        except Exception:
            target_dir = fallback_dir
            os.makedirs(target_dir, exist_ok=True)

        output_path = os.path.join(target_dir, f"{product_id}.json")

        centers = getattr(self, "current_centers", None) or []
        # 统一为 JSON 友好的二维数组，避免 tuple/非数值导致序列化异常
        safe_centers = []
        for c in centers:
            try:
                if isinstance(c, (list, tuple)) and len(c) >= 2:
                    safe_centers.append([float(c[0]), float(c[1])])
            except Exception:
                continue

        # 覆盖写入（存在则截断，不存在则新建）
        with open(output_path, "w", encoding="utf-8") as f:
            json.dump(safe_centers, f, ensure_ascii=False, indent=2)

