    def update_min_distance_col(self):
        """
        独立函数：计算并更新 self.min_distance_col（竖直表的最小非0 R值）
        适用于所有 4、6 管程（无论热交换器类型）
        """
        # 判断是否需要计算竖直表的 min_distance_col
        tube_num = self.get_tube_pass_count()

        # 只在 4、6 管程时计算
        if tube_num not in ["4", "6"]:
            self.min_distance_col = 0
            return

        if not hasattr(self, "current_centers") or not isinstance(
                self.current_centers, (list, set, tuple)
        ):
            self.min_distance_col = 0
            return

        unique_x_sorted = self._unique_positive_x_by_col_key(self.current_centers)
        if not unique_x_sorted:
            self.min_distance_col = 0
            return

        diameters = [x * 2 for x in unique_x_sorted]

        # 计算最小非0的R值
        non_zero_r_values = [r for r in diameters if r > 0]
        if non_zero_r_values:
            self.min_distance_col = min(non_zero_r_values)
            # print(f"【竖直表更新】计算出最小非0 R值: {self.min_distance_col}")
        else:
            self.min_distance_col = 0
            # print(f"【竖直表更新】没有非0 R值，设置为: 0")

    def update_buguan_quantity(self):

        product_id = self.productID  # 固定产品ID

        if not hasattr(self, "current_centers") or not isinstance(
                self.current_centers, (list, set, tuple)
        ):
            # QMessageBox.warning(self, "警告", "缺少有效布管坐标数据（self.current_centers异常）！")
            return None

        # 判断使用哪个表（与build_sql_for_tube_hole逻辑一致）
        tube_num = self.get_tube_pass_count()
        use_vertical_table = False
        if self.heat_exchanger in ["AEU", "BEU", "AKU", "BKU"]:
            if tube_num != "2":
                use_vertical_table = True

        if use_vertical_table:

            unique_x_sorted = self._unique_positive_x_by_col_key(self.current_centers)
            if not unique_x_sorted:
                # QMessageBox.information(self, "提示", "没有找到 x >= 0 的布管坐标。")
                return None

            diameters = [x * 2 for x in unique_x_sorted]

            table_name = "产品设计活动表_布管数量表_竖直"
            col_name = "至竖直中心线行号"
            qty_col_name = "管孔数量（右）"
        else:

            # 使用水平表：提取 y >= 0 的坐标，并转 float
            y_values = [float(y) for (x, y) in self.current_centers if float(y) >= 0]
            if not y_values:
                # QMessageBox.information(self, "提示", "没有找到 y >= 0 的布管坐标。")
                return None

            # 去重并升序排序
            unique_y_sorted = sorted(set(y_values))

            diameters = [y * 2 for y in unique_y_sorted]

            table_name = "产品设计活动表_布管数量表_水平"
            col_name = "至水平中心线行号"
            qty_col_name = "管孔数量（上）"

        # 数据库连接
        conn = pymysql.connect(
            host="localhost",
            port=3306,
            user="root",
            password="123456",
            database="产品设计活动库",
            charset="utf8mb4",
        )
        try:
            cursor = conn.cursor()

            # 5. 读取所有行号/列号（保持原表顺序，不强制 order by；但为匹配我们按行号排序处理，先取出并转为 int）
            cursor.execute(
                f"SELECT {col_name} FROM {table_name} WHERE 产品ID = %s", (product_id,)
            )
            rows = cursor.fetchall()
            if not rows:
                # QMessageBox.warning(self, "警告", f"未找到产品 {product_id} 的布管数量表记录！")

                return None

            # 将行号/列号安全转为 int（有可能是字符串或 decimal）
            rows_sorted = sorted([int(float(r[0])) for r in rows])

            # 6. 读取每行/列对应的"管口数量"，用于判断是否为0
            cursor.execute(
                f"""
                SELECT {col_name}, `{qty_col_name}`
                FROM {table_name}
                WHERE 产品ID = %s
            """,
                (product_id,),
            )
            row_records = cursor.fetchall()

            # 转换为 {行号: 数量} 字典
            row_quantity_map = {}
            zero_qty_count = 0
            for rn, qty in row_records:
                try:
                    rn_int = int(float(rn))
                    qty_val = int(float(qty)) if qty is not None else None
                    row_quantity_map[rn_int] = qty_val
                    if qty_val == 0:
                        zero_qty_count += 1
                except Exception:
                    continue

            # 按顺序填充：数量=0 → R=0，数量≠0 → 用直径
            # 正确的逻辑：遍历所有行号，为非0行分配直径
            updates = {}
            dia_iter = iter(diameters)  # 直径迭代器
            dia_idx = 0
            skipped_rows = []  # 记录被跳过的行

            for candidate_line in rows_sorted:  # 遍历所有行号
                qty = row_quantity_map.get(candidate_line, None)

                if qty == 0:
                    # 数量为0，R值设为0
                    updates[candidate_line] = 0

                else:
                    # 数量不为0，从直径列表中取一个
                    try:
                        dia = next(dia_iter)
                        updates[candidate_line] = dia
                        dia_idx += 1
                        # if dia_idx <= 5 or dia_idx > len(diameters) - 3:  # 只打印前5个和后3个
                        #     print(f"[调试]   行号{candidate_line}: 数量={qty}, 分配R={dia}")
                    except StopIteration:
                        # 直径用完了，剩余的行直接设为R=0
                        # print(f"[调试]   行号{candidate_line}: 数量={qty}, 直径已用完，设置R=0")
                        updates[candidate_line] = 0  # 直接设为0，不要留空！
                        skipped_rows.append(candidate_line)

            if skipped_rows:
                print(
                    f"[调试] 有{len(skipped_rows)}个非0行因直径不足被设为R=0: {skipped_rows}"
                )

            # 调用独立函数计算并保存最小非0的R值（竖直表）
            self.update_min_distance_col()

            # print(f"[调试] ========== R值分配统计 ==========")
            # print(f"[调试] unique坐标数量(直径总数): {len(diameters)}")
            # print(f"[调试] 实际使用的直径数量: {dia_idx}")
            # print(f"[调试] 剩余未用直径数量: {len(diameters) - dia_idx}")
            # print(f"[调试] 分配R=0的数量: {sum(1 for v in updates.values() if v == 0)}")
            # print(f"[调试] 分配R≠0的数量: {sum(1 for v in updates.values() if v != 0)}")
            # print(f"[调试] 总分配数量(updates): {len(updates)}")
            # print(f"[调试] 管孔数量表总行数: {len(rows_sorted)}")
            # print(f"[调试] ====================================")

            # 验证所有行都被处理了
            if len(updates) != len(rows_sorted):
                missing_rows = set(rows_sorted) - set(updates.keys())

            else:
                print(f"[调试] ✓ 所有行都已分配R值")

            # 验证逻辑：unique坐标数 + 数量为0的行数 = 总行数
            expected_total = len(diameters) + zero_qty_count
            actual_total = len(rows_sorted)
            # if expected_total != actual_total:
            #     print(f"[调试] ⚠️ 警告：数据不一致！")
            #     print(f"[调试]    unique坐标数({len(diameters)}) + 数量为0的行数({zero_qty_count}) = {expected_total}")
            #     print(f"[调试]    实际管孔数量表行数 = {actual_total}")
            #     print(f"[调试]    差值: {actual_total - expected_total}")
            # else:
            #     print(f"[调试] ✓ 数据一致性检查通过")
            # 7. 读取布管交叉布管表的前三列（第一/第二/第三排列）
            cursor.execute(
                """
                SELECT 第一排, 第二排, 第三排
                FROM 产品设计活动表_布管交叉布管表
                WHERE 产品ID = %s
                LIMIT 1
            """,
                (product_id,),
            )
            cross_row = cursor.fetchone()

            if cross_row:
                for idx in (1, 2, 3):
                    raw_val = cross_row[idx - 1]
                    if raw_val is None:
                        continue
                    # 如果是数字0或字符串'0'，则跳过（保持原有 R）
                    if raw_val == 0 or (
                            isinstance(raw_val, str) and raw_val.strip() in ("0", "0.0")
                    ):
                        continue

                    # 尝试解析为 python 结构（列表/元组等），安全方式 ast.literal_eval
                    parsed = None
                    if isinstance(raw_val, str):
                        s = raw_val.strip()
                        try:
                            parsed = ast.literal_eval(s)
                        except Exception:
                            # 解析失败，跳过该项
                            parsed = None
                    else:
                        parsed = raw_val

                    # 支持几种格式：
                    # 1) [(x1,y1),(x2,y2)] 或 ((x1,y1),(x2,y2))
                    # 2) [x1,y1,x2,y2] 或 (x1,y1,x2,y2)
                    # 3) [[x1,y1],[x2,y2]]
                    if isinstance(parsed, (list, tuple)):
                        try:
                            # 格式 A: 两个点，每个点是长度为2的 list/tuple
                            if len(parsed) == 2 and all(
                                    isinstance(p, (list, tuple)) and len(p) == 2
                                    for p in parsed
                            ):
                                x1, y1 = map(float, parsed[0])
                                x2, y2 = map(float, parsed[1])
                            # 格式 B: 平展四个数 [x1,y1,x2,y2]
                            elif len(parsed) == 4 and all(
                                    isinstance(n, (int, float, str)) for n in parsed
                            ):
                                x1, y1, x2, y2 = map(float, parsed)
                            else:
                                # 其他不支持的结构，跳过
                                continue

                            # **按你最新要求：R = (x1-x2)**2 + (y1-y2)**2
                            r_value = math.sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2)

                            # 将该 r_value 写入对应的行号 idx (1/2/3)
                            updates[int(idx)] = r_value
                        except Exception:
                            # 任意转换/计算错误，跳过该排列
                            continue
            # 8. 执行更新 —— 只更新 updates 中存在的行/列

            update_sql = (
                f"UPDATE {table_name} SET R = %s WHERE 产品ID = %s AND {col_name} = %s"
            )
            updated_count = 0
            for ln, val in updates.items():
                cursor.execute(update_sql, (val, product_id, ln))
                updated_count += 1

            conn.commit()

            # 验证数据库中的R值
            cursor.execute(
                f"SELECT COUNT(*) as cnt FROM {table_name} WHERE 产品ID = %s AND (R IS NULL OR R = '' OR R = '0' OR R = 0)",
                (product_id,),
            )
            zero_r_count = cursor.fetchone()[0]

            cursor.execute(
                f"SELECT COUNT(*) as cnt FROM {table_name} WHERE 产品ID = %s AND R IS NOT NULL AND R != '' AND R != '0' AND R != 0",
                (product_id,),
            )
            nonzero_r_count = cursor.fetchone()[0]

            cursor.execute(
                f"SELECT COUNT(*) as cnt FROM {table_name} WHERE 产品ID = %s",
                (product_id,),
            )
            total_count = cursor.fetchone()[0]
            if zero_r_count + nonzero_r_count != total_count:
                print(
                    f"[调试] ⚠️ 警告：还有 {total_count - zero_r_count - nonzero_r_count} 条记录的R值为空！"
                )

        finally:
            conn.close()

    def execute_sql(self, sql, fetch=False):
        """执行SQL语句"""
        try:
            from modules.buguan.buguan_ziyong.database_utils import create_connection

            connection = create_connection()
            cursor = connection.cursor()
            cursor.execute(sql)

            if fetch:
                # 如果是查询操作，返回结果
                result = cursor.fetchall()
                connection.close()
                return result
            else:
                # 如果是更新操作，提交事务
                connection.commit()
                connection.close()
        except Exception as e:
            QMessageBox.critical(self, "错误", f"保存数据时出错:\n{str(e)}")
            print("保存数据时出错")
            if fetch:
                return None

    def _sync_tube_sheet_snapshot_and_update_dl(self):
        """从管板形式页同步参数快照，并在命中特殊节点时重算布管限定圆 DL。"""
        plate_type = None
        full_params = []

        if hasattr(self, "sheet_form_page") and hasattr(
                self.sheet_form_page, "get_current_tube_form_data"
        ):
            try:
                full_params = self.sheet_form_page.get_current_tube_form_data() or []
            except Exception as e:
                print(f"[My_Piping] 获取当前管板形式参数时出错: {e}")
                full_params = []

        for name, value in full_params:
            if str(name).strip() == "管板类型":
                plate_type = str(value).strip()
                break

        main_category = None
        node_name = None
        if plate_type:
            parts = plate_type.split("_", 1)
            if len(parts) >= 1 and parts[0]:
                main_category = parts[0].lower()
            if len(parts) == 2 and parts[1]:
                node_name = parts[1].lower()

        self.is_suitable_tube_sheet = (
            ((main_category == "b") and (node_name in ["c", "d", "e", "h", "a"]))
            or
            ((main_category == "e") and (node_name in ["a", "b", "c", "d", "e", "f", "b"]))
            if main_category
            else False
        )

        try:
            update_is_suitable_tube_sheet(self.is_suitable_tube_sheet)
        except Exception:
            pass

        try:
            print(
                f"[My_Piping] plate_type={plate_type!r}, "
                f"main_category={main_category!r}, node_name={node_name!r}, "
                f"is_suitable_tube_sheet={self.is_suitable_tube_sheet}, "
                f"full_params_len={len(full_params) if full_params else 0}"
            )
        except Exception:
            pass

        if self.is_suitable_tube_sheet and full_params:
            print("[My_Piping] 命中特殊管板节点分支，准备保存快照并重算 DL。")

            filtered_params = [
                (name, value)
                for name, value in full_params
                if str(name).strip() != "管板类型"
            ]

            snapshot = {
                "plate_type": plate_type,
                "main_category": main_category,
                "node_name": node_name,
                "params": filtered_params,
            }

            try:
                self.tube_sheet_params_snapshot = snapshot
            except Exception:
                pass
            try:
                update_tube_sheet_params_snapshot(snapshot)
            except Exception:
                pass

            prev_suppress = getattr(self, "_suppress_open_s_dl_autoupdate", False)
            if prev_suppress:
                print("[My_Piping] 管板形式变更：临时允许 DL 自动重算（覆盖加载阶段抑制）")
            self._suppress_open_s_dl_autoupdate = False
            try:
                self.update_tube_layout_circle_dl()
            except Exception as e:
                print(f"[My_Piping] 根据管板形式快照更新 DL 时发生异常: {e}")
            finally:
                self._suppress_open_s_dl_autoupdate = prev_suppress
        else:
            print("[My_Piping] 未命中特殊管板节点分支，清空管板参数快照。")
            try:
                self.tube_sheet_params_snapshot = {}
            except Exception:
                pass
            try:
                update_tube_sheet_params_snapshot({})
            except Exception:
                pass

        try:
            from pprint import pformat

            snapshot_for_print = getattr(self, "tube_sheet_params_snapshot", {}) or {}
            print("当前管板形式：\n" + pformat(snapshot_for_print))
        except Exception:
            pass

    def switch_page(self, index):
        # TODO 切换页面
        self.stacked_widget.setCurrentIndex(index)

        if index == 1:
            self.update_cross_pipe_button_state()

        # 如果切换到轴向设计页面，实时刷新其基础参数
        try:
            target_widget = self.stacked_widget.currentWidget()
            if isinstance(target_widget, AxialDesignPage):
                try:
                    target_widget._update_basic_params_from_parent()
                    # 每次切换到轴向设计页面时，重新运行 initial_draw_layout
                    try:
                        target_widget.initial_draw_layout()
                    except Exception:
                        pass
                except Exception:
                    pass
        except Exception:
            pass

        # 如果切换到“布管”tab（索引1），检查当前管板形式并按需获取参数
        try:
            if index == 1:
                self._sync_tube_sheet_snapshot_and_update_dl()
        except Exception as e:
            print(f"[My_Piping] 切换到布管 tab 时检查管板形式发生异常: {e}")

        if index == 1:
            def _defer_lock_outer_on_buguan_tab():
                try:
                    self._lock_outer_base_flag_param_cell()
                except Exception:
                    pass

            QTimer.singleShot(0, _defer_lock_outer_on_buguan_tab)
            QTimer.singleShot(100, _defer_lock_outer_on_buguan_tab)

        # 切换页面时更新底部按钮
        self.update_footer_buttons()

    def create_footer(self):
        """创建底部按钮区域（保存按钮靠右，样式与产品管理一致）"""
        self.footer_frame = QFrame()
        self.footer_frame.setStyleSheet(
            "background-color: transparent; border: none;"
        )
        self.footer_layout = QHBoxLayout(self.footer_frame)
        self.footer_frame.setVisible(True)
        self.footer_layout.setContentsMargins(10, 8, 12, 8)

        # 初始化按钮（内部会 addStretch 并将保存按钮推到右下角）
        self.update_footer_buttons()

        self.main_layout.addWidget(self.footer_frame)

    def show_preview(self):
        """显示参数预览对话框，含管程分程形式对应图片"""
        # 1. 定义需要隐藏的参数列表
        hidden_params = [
            "滑道定位",
            "滑道高度",
            "滑道切边长度",
            "滑道切边高度",
            "滑道厚度",
            "滑道与竖直中心线夹角",
            "滑道数量",
            "滑道方位角",
            "旁路挡板厚度",
            "防冲板形式",
            "放置位置",
            "防冲板厚度",
            "防冲板折边角度",
            "防冲板宽度",
            "防冲板方位角",
            "至圆筒内壁距离",
            "切边长度 L1",
            "切边高度 h",
            "中间挡板厚度",
            "中间挡板宽度",
            "旁路挡板宽度",
            "吊环螺钉起始方位角",
            "吊环螺钉规格",
            "吊环螺钉孔中心距",
            "吊环螺钉数量",
            "折流/支持板外径",
            "折流/支持板间距",
            "折流板类型",
            "折流板切口方向",
            "折流板要求切口率",
            "折流板切口与中心线间距a",
            "弓形弦高切口率",
            "内侧中心切口率",
            "A型板切口与中心线间距a",
            "B型板切口与中心线间距b",
        ]

        # 2. 获取当前页面的参数表格
        current_page = self.stacked_widget.currentWidget()
        param_table = current_page.findChild(QTableWidget)

        if param_table:
            parameters = []
            # 获取当前管程分程形式标识（核心：使用当前实际选中的值）
            current_tube_partition = getattr(self, "tube_pass_form_value", "")

            # 图片基础路径
            current_dir = os.path.dirname(os.path.abspath(__file__))
            tube_pattern_base_path = os.path.join(current_dir, "static", "TubePattern")

            for row in range(param_table.rowCount()):
                # 3. 提取参数名，过滤隐藏参数
                name_item = param_table.item(row, 1)
                param_name = name_item.text() if name_item else "N/A"
                if param_name in hidden_params:
                    continue  # 隐藏参数直接跳过，不加入预览

                # 4. 提取序号（第一列）
                num_item = param_table.item(row, 0)
                param_num = num_item.text() if num_item else str(row + 1)

                # 5. 提取参数值+管程分程形式的图片
                param_value = "N/A"
                param_image = None  # 存储管程分程形式的图片
                cell_widget = param_table.cellWidget(row, 2)

                if cell_widget and isinstance(cell_widget, QComboBox):
                    # 非管程分程形式的下拉框：用显示文本作为值
                    if param_name != "管程分程形式":
                        param_value = cell_widget.currentText()
                    # 管程分程形式：特殊处理（值+图片）
                    else:
                        # 参数值：使用当前选中的管程分程形式标识
                        param_value = (
                            current_tube_partition
                            if current_tube_partition
                            else "未选择"
                        )

                        # 图片：根据current_tube_partition匹配对应文件
                        if current_tube_partition and os.path.exists(
                                tube_pattern_base_path
                        ):
                            image_file_map = {
                                "2.1": "2.1.png",
                                "4.1": "4.1.png",
                                "4.2": "4.2.1.png",
                                "4.3": "4.3.1.png",
                                "6.1": "6.1.1.png",
                                "6.2": "6.2.1.png",
                                "1.1": "1.1.png",
                            }

                            # 获取对应的图片文件名
                            image_filename = image_file_map.get(
                                current_tube_partition, f"{current_tube_partition}.png"
                            )
                            image_path = os.path.join(
                                tube_pattern_base_path, image_filename
                            )

                            # 如果首选图片不存在，尝试其他可能的文件名
                            if not os.path.exists(image_path):
                                # 尝试不带后缀的版本
                                alt_filename = f"{current_tube_partition}.png"
                                alt_path = os.path.join(
                                    tube_pattern_base_path, alt_filename
                                )
                                if os.path.exists(alt_path):
                                    image_path = alt_path

                            # 加载并处理图片
                            if os.path.exists(image_path):
                                loaded_pixmap = QPixmap(image_path)
                                if not loaded_pixmap.isNull():
                                    # 缩放图片：保持比例+平滑处理
                                    param_image = loaded_pixmap.scaled(
                                        100,
                                        85,
                                        Qt.KeepAspectRatio,
                                        Qt.SmoothTransformation,
                                    )
                else:
                    # 非下拉框单元格：直接取文本值
                    value_item = param_table.item(row, 2)
                    param_value = value_item.text() if value_item else "N/A"

                # 6. 提取单位（第四列）
                unit_item = param_table.item(row, 3)
                param_unit = unit_item.text() if unit_item else "N/A"

                # 7. 组装参数数据（含图片，仅管程分程形式有）
                param_data = {
                    "序号": param_num,
                    "参数名": param_name,
                    "参数值": param_value,
                    "单位": param_unit,
                }
                # 仅管程分程形式添加图片（确保图片非空）
                if (
                        param_name == "管程分程形式"
                        and param_image
                        and not param_image.isNull()
                ):
                    param_data["image"] = param_image

                parameters.append(param_data)

            # 8. 打开预览对话框
            dialog = PreviewDialog(parameters, self)
            dialog.exec_()
        # else:
        #     QMessageBox.warning(self, "警告", "未找到参数表格！")

    def update_right_table_column_widths(self):
        """右侧管孔分布表：稳定的列宽控制（避免初始布局阶段列宽异常）"""
        if not hasattr(self, "hole_distribution_table"):
            return

        table = self.hole_distribution_table
        header = table.horizontalHeader()

        # 强制固定模式（避免 Qt 自己再算）
        header.setSectionResizeMode(QHeaderView.Fixed)
        header.setStretchLastSection(False)

        w = table.viewport().width()
        col_count = table.columnCount()

        # 关键：初始布局未稳定时，w 可能为 0 或非常离谱；此时先不算
        if w <= 0 or col_count <= 0:
            return

        screen = self.screen()
        dpi_scale = screen.logicalDotsPerInch() / 96.0 if screen else 1.0

        # 这里的 max_w 才是“防止初始列宽很大”的硬限制
        min_w = int(60 * dpi_scale)
        max_w = int(220 * dpi_scale)

        # 3列时按你的表头含义分配比例（可按需调整）
        if col_count == 3:
            ratios = [0.30, 0.35, 0.35]  # 行号列稍窄，上/下数量列稍宽
        else:
            ratios = [1.0 / col_count] * col_count

        widths = [int(w * r) for r in ratios]
        widths = [max(min_w, min(x, max_w)) for x in widths]

        # 如果 clamp 后总宽仍超过 viewport，就等比缩小
        total = sum(widths)
        if total > w and total > 0:
            scale = w / total
            widths = [max(min_w, int(x * scale)) for x in widths]

        # 最终强制覆盖缓存的列宽（这一步才能“打掉初始异常列宽”）
        for i in range(col_count):
            header.resizeSection(i, widths[i])

