    # TODO 交叉布管绘制函数，可修改样式
    def build_2_cross_pipes(self, selected_centers):
        if len(selected_centers) != 2:
            return

        self.sorted_current_centers_up, self.sorted_current_centers_down = (
            self.group_centers_by_y(self.current_centers)
        )

        # 获取两个选中圆的圆心坐标
        points = []
        for row_label, col_label in selected_centers:
            row_idx = abs(row_label) - 1
            col_idx = abs(col_label) - 1
            centers_group = (
                self.full_sorted_current_centers_up
                if row_label > 0
                else self.full_sorted_current_centers_down
            )
            x, y = centers_group[row_idx][col_idx]
            points.append((x, y))

        (x1, y1), (x2, y2) = points

        # 获取换热管外径 do
        do_value = None
        for row in range(self.param_table.rowCount()):
            name_item = self.param_table.item(row, 1)
            if (
                    name_item
                    and "换热管外径" in name_item.text()
                    and "do" in name_item.text()
            ):
                value_widget = self.param_table.cellWidget(row, 2)
                do_text = (
                    value_widget.currentText()
                    if isinstance(value_widget, QComboBox)
                    else self.param_table.item(row, 2).text()
                )
                do_value = float(do_text.replace(".", "", 1))
                break

        r = do_value / 2.0

        # 计算切线
        dx = x2 - x1
        dy = y2 - y1
        distance = math.hypot(dx, dy)
        ux, uy = dx / distance, dy / distance
        vx1, vy1 = -uy, ux
        vx2, vy2 = uy, -ux

        p1_start = QPointF(x1 + vx1 * r, y1 + vy1 * r)
        p1_end = QPointF(x2 + vx1 * r, y2 + vy1 * r)
        p2_start = QPointF(x1 + vx2 * r, y1 + vy2 * r)
        p2_end = QPointF(x2 + vx2 * r, y2 + vy2 * r)

        # 绘制切线 - 设置为很细的线条（线宽改为1）
        pen = QPen(QColor(0, 0, 139), 1)  # 线宽从2改为1，变得更细
        line1 = self.graphics_scene.addLine(QLineF(p1_start, p1_end), pen)
        line2 = self.graphics_scene.addLine(QLineF(p2_start, p2_end), pen)

        # 使用专门的 cross_pipe_lines 存储交叉布管连接线，与普通连接线隔离
        if not hasattr(self, "cross_pipe_lines"):
            self.cross_pipe_lines = []
        line1.setZValue(10)  # 设置较高的Z值确保显示在上层
        line2.setZValue(10)

        # 在线上存储对应的两个换热管坐标，用于后续删除时匹配
        # 将坐标信息存储为自定义属性，两条线都存储相同的坐标对
        line1.tube_coords = points  # 存储两个换热管的绝对坐标 [(x1, y1), (x2, y2)]
        line2.tube_coords = points  # 两条线都存储相同的坐标对

        self.cross_pipe_lines.extend([line1, line2])

        # 擦除高亮标记
        for x, y in points:
            for item in self.graphics_scene.items(QPointF(x, y)):
                if isinstance(item, QGraphicsEllipseItem):
                    if item.brush().color() == QColor(173, 216, 230):  # 淡蓝色标记
                        self.graphics_scene.removeItem(item)
                        break

        # 记录操作
        if not hasattr(self, "operations"):
            self.operations = []
        self.operations.append(
            {
                "type": "cross_pipe_tangents",
                "points": points,
                "line_width": 1,  # 记录修改后的线宽
                "tube_diameter": do_value,
            }
        )

        # 清空选择
        if hasattr(self, "selected_centers"):
            self.selected_centers = []

        self.graphics_scene.update()
        QApplication.processEvents()

    def selected_to_current_coords(self, selected_centers):
        current_coords = []

        # 处理字符串类型的输入
        if isinstance(selected_centers, str):
            try:
                selected_centers = eval(selected_centers)
            except Exception as e:
                return []  # 转换失败返回空列表

        # 验证输入是否为列表
        if not isinstance(selected_centers, list):
            return []

        # 检查关键数据结构
        if not hasattr(self, "full_sorted_current_centers_up"):
            return []
        if not hasattr(self, "full_sorted_current_centers_down"):
            return []

        for idx, item in enumerate(selected_centers):
            # 验证每个元素是否为包含两个元素的可迭代对象
            if not (isinstance(item, (list, tuple)) and len(item) == 2):
                continue  # 跳过无效元素，继续处理下一个

            row_label, col_label = item
            # 计算行索引和列索引
            row_idx = abs(row_label) - 1
            col_idx = abs(col_label) - 1

            try:
                # 根据行号选择数据源
                if row_label > 0:
                    if row_idx >= len(self.full_sorted_current_centers_up):
                        continue  # 跳过无效坐标
                    row_data = self.full_sorted_current_centers_up[row_idx]
                else:
                    if row_idx >= len(self.full_sorted_current_centers_down):
                        continue  # 跳过无效坐标
                    row_data = self.full_sorted_current_centers_down[row_idx]

                # 检查列索引有效性
                if not (0 <= col_idx < len(row_data)):
                    continue  # 跳过无效列索引

                x, y = row_data[col_idx]
                current_coords.append((x, y))

            except (IndexError, Exception) as e:
                continue  # 跳过出错的坐标

        return current_coords

    # 拉杆功能
    def on_lagan_click(self):
        """拉杆点击事件（无“中间挡管”逻辑；形式+直径均用下拉框，直径随形式联动）"""
        # 互转：选中中间挡管时直接转为拉杆，绝不弹参数窗
        # （即使仍残留换热管选中，也不挡互转；成败都不再走后面的参数弹窗）
        try:
            if self._has_selected_center_dangguan():
                try:
                    ok = self.convert_center_dangguan_to_lagan()
                    print(f"[on_lagan_click] 中间挡管转拉杆完成: ok={ok}")
                except Exception as e:
                    print(f"[on_lagan_click] 中间挡管转拉杆失败: {e}")
                return
        except Exception as e:
            print(f"[on_lagan_click] 中间挡管转拉杆前置判断出错: {e}")

        from PyQt5.QtWidgets import (
            QVBoxLayout,
            QHBoxLayout,
            QLabel,
            QComboBox,
            QPushButton,
            QTableWidgetItem,
        )

        # ---------- 工具函数 ----------
        def find_row_by_name(name: str):
            rc = self.param_table.rowCount()
            for r in range(rc):
                it = self.param_table.item(r, 1)
                if it and it.text().strip() == name:
                    return r
            return -1

        def get_cell_text(row: int) -> str:
            if row < 0:
                return ""
            w = self.param_table.cellWidget(row, 2)
            if w and isinstance(w, QComboBox):
                return w.currentText().strip()
            it = self.param_table.item(row, 2)
            return it.text().strip() if it else ""

        def set_cell_text(row: int, text: str):
            if row < 0:
                return
            w = self.param_table.cellWidget(row, 2)
            if w and isinstance(w, QComboBox):
                w.blockSignals(True)
                # 若下拉里没有该项，先补上
                if w.findText(text) < 0:
                    w.addItem(text)
                w.setEditable(False)
                w.setCurrentText(text)
                w.blockSignals(False)
            else:
                self.param_table.setItem(row, 2, QTableWidgetItem(text))
            # 保持你原有“隐藏参数行”的习惯
            self.set_param_visibility(row, False)

        # ---------- 读取当前默认值 ----------
        row_type = find_row_by_name("拉杆形式")
        row_dia = find_row_by_name("拉杆直径")
        row_do = find_row_by_name("换热管外径 do")

        # 记录原值：用于弹窗取消时回滚（弹窗内会实时联动写回参数表）
        original_type_text = get_cell_text(row_type)
        original_dia_text = get_cell_text(row_dia)

        default_type = get_cell_text(row_type) or "焊接拉杆"
        # 直径默认：尽量从表里拿，否则兜底 12
        txt_d = get_cell_text(row_dia)
        try:
            default_dia = float(txt_d) if txt_d else 12.0
        except Exception:
            default_dia = 12.0

        # 管外径（用于计算焊接拉杆默认直径）
        try:
            tube_do = float(get_cell_text(row_do)) if row_do != -1 else None
        except Exception:
            tube_do = None

        # 若为螺纹拉杆，弹窗默认直径按当前换热管外径 do 推荐
        if default_type == "螺纹拉杆" and tube_do is not None:
            if 10 <= tube_do <= 14:
                default_dia = 10.0
            elif 14 < tube_do < 25:
                default_dia = 12.0
            elif 25 <= tube_do <= 32:
                default_dia = 16.0
            elif 32 < tube_do <= 57:
                default_dia = 20.0

        # 直径选项表
        THREAD_OPTIONS = ["10", "12", "16", "20"]  # 螺纹拉杆固定选项
