    def _remove_normal_lagan_items(self, items):
        """删除普通拉杆图元，并同步 lagan_info / 选中列表 / 转换标记（不做额外对称扩展）。"""
        if not items:
            return
        coords_removed = []
        for item in list(items):
            center = self._item_abs_center(item)
            if center is not None:
                coords_removed.append(center)
            try:
                scene = item.scene() if hasattr(item, "scene") else None
                if scene is not None:
                    scene.removeItem(item)
                elif getattr(self, "graphics_scene", None) is not None:
                    self.graphics_scene.removeItem(item)
            except Exception:
                pass
            try:
                if hasattr(self, "selected_lagans") and item in self.selected_lagans:
                    self.selected_lagans.remove(item)
            except Exception:
                pass

        if coords_removed and hasattr(self, "lagan_info") and self.lagan_info:
            new_info = []
            for coord in self.lagan_info:
                keep = True
                try:
                    for target in coords_removed:
                        if self._abs_coords_close(coord, target):
                            keep = False
                            break
                except Exception:
                    keep = True
                if keep:
                    new_info.append(coord)
            self.lagan_info = new_info
            try:
                self._sync_current_centers_lagan(reason="convert remove lagan")
            except Exception:
                pass

        self._remove_converted_lagan_coords(coords_removed)

    def _remove_free_lagan_items(self, items):
        """删除自由拉杆图元，并同步 red_dangban / red_dangban_abs / 选中列表。"""
        from modules.buguan.buguan_ziyong.component.free_lagan import (
            remove_free_lagan_items,
        )

        return remove_free_lagan_items(items, self)

    def _collect_any_lagan_items_at_coords(self, coords):
        """收集指定绝对坐标上的所有拉杆图元（普通/转换/自由）。"""
        normal_items = []
        free_items = []
        if not coords:
            return normal_items, free_items
        scene = getattr(self, "graphics_scene", None)
        if scene is None:
            return normal_items, free_items

        seen_ids = set()
        for item in list(scene.items()):
            try:
                is_normal = bool(getattr(item, "is_lagan", False))
                is_free = bool(getattr(item, "is_side_rod", False))
                if not (is_normal or is_free):
                    continue
                iid = id(item)
                if iid in seen_ids:
                    continue
                center = self._item_abs_center(item)
                if center is None:
                    continue
                hit = False
                for target in coords:
                    if self._abs_coords_close(center, target):
                        hit = True
                        break
                if not hit:
                    continue
                seen_ids.add(iid)
                # 自由拉杆优先按 is_side_rod 归类（工业上都是拉杆，缓存路径不同）
                if is_free:
                    free_items.append(item)
                else:
                    normal_items.append(item)
            except Exception:
                continue
        return normal_items, free_items

    def _has_any_lagan_at_coords(self, coords):
        """指定绝对坐标上是否已有拉杆（普通/转换/自由）。"""
        normal_items, free_items = self._collect_any_lagan_items_at_coords(coords)
        return bool(normal_items or free_items)

    def _confirm_replace_lagan_for_center_dangguan(self):
        """
        弹窗确认是否用中间挡管替换同位置拉杆。
        同一次批量添加只询问一次；否决后标记本批失败。
        """
        if getattr(self, "_cdg_batch_active", False):
            decided = getattr(self, "_cdg_replace_lagan_decision", None)
            if decided is not None:
                return bool(decided)

        from PyQt5.QtWidgets import QMessageBox

        reply = QMessageBox.question(
            self,
            "提示",
            "此处已有拉杆，是否继续添加中间挡管？",
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        ok = reply == QMessageBox.Yes
        if getattr(self, "_cdg_batch_active", False):
            self._cdg_replace_lagan_decision = ok
            if not ok:
                self._cdg_batch_failed = True
        return ok

    def _remove_any_lagan_at_coords(self, coords):
        """
        清除指定绝对坐标上的所有拉杆（普通/转换/自由）。
        用于中间挡管落点前：同位置只保留一个元件。
        """
        normal_items, free_items = self._collect_any_lagan_items_at_coords(coords)
        if not normal_items and not free_items:
            return 0

        self._remove_normal_lagan_items(normal_items)
        self._remove_free_lagan_items(free_items)
        try:
            if hasattr(self, "update_total_lagan_count"):
                self.update_total_lagan_count()
        except Exception:
            pass
        removed = len(normal_items) + len(free_items)
        print(
            f"[remove_any_lagan_at_coords] 已清除同位置拉杆 {removed} 个"
            f"（普通/转换={len(normal_items)}, 自由={len(free_items)}）"
        )
        return removed

