    def edit_lagan_params_dialog_only(self):
        self.operation_order += 1
        from PyQt5.QtWidgets import (
            QVBoxLayout,
            QHBoxLayout,
            QLabel,
            QComboBox,
            QPushButton,
            QTableWidgetItem,
        )

        def find_row_by_name(name: str):
            rc = self.param_table.rowCount()
            for r in range(rc):
                it = self.param_table.item(r, 1)
                if it and it.text().strip() == name:
                    return r
            return -1

        def get_cell_text(row: int) -> str:
            if row < 0:
                return ""
            w = self.param_table.cellWidget(row, 2)
            if w and isinstance(w, QComboBox):
                return w.currentText().strip()
            it = self.param_table.item(row, 2)
            return it.text().strip() if it else ""

        def set_cell_text(row: int, text: str):
            if row < 0:
                return
            w = self.param_table.cellWidget(row, 2)
            if w and isinstance(w, QComboBox):
                w.blockSignals(True)
                if w.findText(text) < 0:
                    w.addItem(text)
                w.setEditable(False)
                w.setCurrentText(text)
                w.blockSignals(False)
            else:
                self.param_table.setItem(row, 2, QTableWidgetItem(text))
            self.set_param_visibility(row, False)

        row_type = find_row_by_name("拉杆形式")
        row_dia = find_row_by_name("拉杆直径")
        row_do = find_row_by_name("换热管外径 do")

        default_type = get_cell_text(row_type) or "焊接拉杆"
        txt_d = get_cell_text(row_dia)
        try:
            default_dia = float(txt_d) if txt_d else 12.0
        except Exception:
            default_dia = 12.0

        try:
            tube_do = float(get_cell_text(row_do)) if row_do != -1 else None
        except Exception:
            tube_do = None

        # 若为螺纹拉杆，弹窗默认直径按当前换热管外径 do 推荐
        if default_type == "螺纹拉杆" and tube_do is not None:
            if 10 <= tube_do <= 14:
                default_dia = 10.0
            elif 14 < tube_do < 25:
                default_dia = 12.0
            elif 25 <= tube_do <= 32:
                default_dia = 16.0
            elif 32 < tube_do <= 57:
                default_dia = 20.0

        THREAD_OPTIONS = ["10", "12", "16", "20"]
        WELD_OPTIONS = [
            "10", "12", "14", "16", "19", "20", "22", "25",
            "30", "32", "35", "38", "45", "50", "55", "57"
        ]

        dlg = QDialog(self)
        dlg.setWindowTitle("拉杆参数设置")
        main = QVBoxLayout(dlg)

