        type_combo.addItems(["焊接拉杆", "螺纹拉杆"])
        idx = type_combo.findText(default_type)
        type_combo.setCurrentIndex(idx if idx >= 0 else 0)
        line1.addWidget(type_combo)
        main.addLayout(line1)

        line2 = QHBoxLayout()
