        def rebuild_dia_options(cur_type: str, keep_value: float):
            dia_combo.blockSignals(True)
            dia_combo.clear()
            if cur_type == "螺纹拉杆":
                opts = THREAD_OPTIONS[:]
            else:
                opts = WELD_OPTIONS[:]
            keep_txt = f"{keep_value:g}"
            found = False
            for i, t in enumerate(opts):
                dia_combo.addItem(t)
                if t.replace("（", "(").replace("）", ")") == keep_txt or t == keep_txt:
                    dia_combo.setCurrentIndex(i)
                    found = True
            if not found:
                fallback_idx = dia_combo.findText(f"{default_dia:g}")
                dia_combo.setCurrentIndex(fallback_idx if fallback_idx >= 0 else 0)
            dia_combo.blockSignals(False)

