    def build_huanreguan(self, selected_centers, skip_slipway_block=False):
        actual_centers=self.selected_to_current_coords(selected_centers)
        print(actual_centers)
        self.operation_order += 1
        try:
            print(f"[build_huanreguan] selected_centers(raw) = {selected_centers}")
        except Exception:
            pass
        actual_centers = self.selected_to_current_coords(selected_centers)
        try:
            print(f"[build_huanreguan] actual_centers = {actual_centers}")
        except Exception:
            pass

        from PyQt5.QtGui import QPen, QBrush, QColor
        from PyQt5.QtWidgets import QGraphicsEllipseItem
        from PyQt5.QtCore import Qt

        if not selected_centers:
            return

        if not getattr(self, "is_loading_data", False) and not skip_slipway_block:
            selected_centers, _ = self._filter_coords_blocked_by_true_slipway(
                selected_centers
            )
            if not selected_centers:
                return

        # 保证必要属性存在
        if not hasattr(self, "huanreguan"):
            self.huanreguan = []
        if not hasattr(self, "current_centers"):
            self.current_centers = []
        if not hasattr(self, "operations"):
            self.operations = []
        actual_centers = self.selected_to_current_coords(selected_centers)
        self.del_centers = [
            coord for coord in self.del_centers if coord not in actual_centers
        ]

        self.lagan_info = [
            coord for coord in self.lagan_info if coord not in actual_centers
        ]

        # 小工具
        def key6(x, y):
            return (round(float(x), 6), round(float(y), 6))

        def center_scene(item: QGraphicsEllipseItem):
            try:
                p = item.mapToScene(item.rect().center())
                return (p.x(), p.y())
            except Exception:
                r = item.rect()
                p = item.scenePos() + r.center()
                return (p.x(), p.y())

        # 颜色与笔刷
        blue_pen = QPen(QColor(0, 0, 80))
        blue_pen.setWidth(1)
        blue_brush = QBrush(Qt.NoBrush)
        hilite_brush_color = QColor(173, 216, 230)  # 你的淡蓝高亮

        # 先清除可能存在的淡蓝高亮 marker（避免视觉叠层）
        for it in list(self.graphics_scene.items()):
            if (
                    isinstance(it, QGraphicsEllipseItem)
                    and it.brush().color() == hilite_brush_color
            ):
                try:
                    self.graphics_scene.removeItem(it)
                except Exception:
                    pass

        # 建立“坐标 -> 椭圆列表”索引（统一 6 位）
        from collections import defaultdict

        coord_index = defaultdict(list)
        for it in self.graphics_scene.items():
            if isinstance(it, QGraphicsEllipseItem):
                cx, cy = center_scene(it)
                coord_index[key6(cx, cy)].append(it)

        # 相对坐标 -> 绝对坐标
        self.full_sorted_current_centers_up, self.full_sorted_current_centers_down = (
            self.group_centers_by_y(self.global_centers)
        )

        target_points = []  # [(x,y,row_label,col_label)]
        keys_to_purge = set()

        for row_label, col_label in selected_centers:
            try:
                if row_label > 0:
                    group, ri = self.full_sorted_current_centers_up, row_label - 1
                else:
                    group, ri = self.full_sorted_current_centers_down, -row_label - 1
                ci = abs(col_label) - 1
                x, y = group[ri][ci]
                target_points.append((x, y, row_label, col_label))
                keys_to_purge.add(key6(x, y))
            except Exception as e:
                print(
                    f"[build_huanreguan] 相对坐标越界/异常 ({row_label},{col_label}): {e}"
                )

        # 暂停刷新
        v = self.graphics_scene.views()
        if v:
            v[0].setUpdatesEnabled(False)
        added_count = 0
        try:
            # ① 添加前：把该坐标下所有椭圆都清掉（含白实心/老蓝圈/淡蓝/拉杆）
            #    这样当当前位置原来是拉杆时，点击“换热管”也能把其还原为换热管
            for k in keys_to_purge:
                for it in list(coord_index.get(k, [])):
                    try:
                        self.graphics_scene.removeItem(it)
                    except Exception:
                        pass

            # ② 画深蓝空心圈（换热管）
            for x, y, rl, cl in target_points:
                new_circle = self.graphics_scene.addEllipse(
                    x - self.r, y - self.r, 2 * self.r, 2 * self.r, blue_pen, blue_brush
                )
                new_circle.setZValue(2)  # 顶层
                if (x, y) not in self.current_centers:
                    self.current_centers.append((x, y))
                if (x, y) not in self.current_centers_lagan:
                    self.current_centers_lagan.append((x, y))
                self.huanreguan.append((rl, cl))
                # ——保留你的操作记录字段结构——
                self.operations.append(
                    {
                        "type": "add_tube",
                        "relative_coord": (rl, cl),
                        "absolute_coord": (x, y),
                        "draw_coord": (x, y),
                    }
                )
                added_count += 1

        finally:
            if v:
                v[0].setUpdatesEnabled(True)

        # 刷新（沿用你原有逻辑）
        self.selected_centers = []
        self.update_total_holes_count()
        self.update_total_lagan_count()
        self.sorted_current_centers_up, self.sorted_current_centers_down = (
            self.group_centers_by_y(self.current_centers)
        )
        self.find_edge_tube()
        self.update_tube_nums()
        # 统一重算 current_centers_lagan = current_centers + lagan_info
        self._sync_current_centers_lagan()
        if added_count == 0:
            return

    # TODO 删除换热管
    def delete_huanreguan(self, selected_centers, for_slipway=False):
        self.operation_order += 1
        """
        删除换热管（修复版）：
        - 入参可为相对坐标[(row,col)]、绝对坐标[(x,y)]或字符串；稳健解析；
        - 统一 6 位小数坐标，并用 mapToScene(rect.center()) 精确匹配；
        - 在目标坐标：一次性清理所有“非白实心 & 非拉杆”的椭圆，再补白实心占位；
        - 保留并恢复 connection_lines；保留你的操作记录写法；
        - ✅ 完全不触碰拉杆数据（不改 self.lagan_info 等），与拉杆彻底解耦。
        """
        from PyQt5.QtGui import QPen, QBrush, QColor
        from PyQt5.QtWidgets import QGraphicsEllipseItem
        from PyQt5.QtCore import Qt
        import ast

        # 小工具
        def key6(x, y):
            return (round(float(x), 6), round(float(y), 6))

        def center_scene(item: QGraphicsEllipseItem):
            try:
                p = item.mapToScene(item.rect().center())
                return (p.x(), p.y())
            except Exception:
                r = item.rect()
                p = item.scenePos() + r.center()
                return (p.x(), p.y())

        def is_white_solid(it: QGraphicsEllipseItem) -> bool:
            try:
                return (
                        it.pen().color() == QColor(255, 255, 255)
                        and it.brush().style() != Qt.NoBrush
                )
            except Exception:
                return False

        def is_rod(it) -> bool:
            try:
                # 仅将最左/最右自由拉杆视为拉杆，普通拉杆当作普通换热管处理
                return getattr(it, "is_side_rod", False)
            except Exception:
                return False

        # 允许空
        if not selected_centers:
            return []

        # 解析字符串
        if isinstance(selected_centers, str):
            try:
                selected_centers = ast.literal_eval(selected_centers)
            except Exception:
                return []

        # 判断是相对坐标还是绝对坐标：相对坐标一般是整数，绝对坐标一般带小数
        is_relative_coords = False
        if isinstance(selected_centers, list) and len(selected_centers) > 0:
            first_item = selected_centers[0]
            if isinstance(first_item, (list, tuple)) and len(first_item) >= 2:
                first_coord = first_item[0]
                # 判断第一个坐标值是否为整数（相对坐标）还是浮点数（绝对坐标）
                if isinstance(first_coord, int):
                    is_relative_coords = True
                elif isinstance(first_coord, float):
                    is_relative_coords = False
                elif (
                        isinstance(first_coord, (str))
                        and first_coord.replace("-", "").replace(".", "").isdigit()
                ):
                    # 处理字符串形式的数字
                    try:
                        coord_val = float(first_coord)
                        is_relative_coords = coord_val == int(coord_val)
                    except:
                        is_relative_coords = False

        # 如果是相对坐标，转换为绝对坐标；如果是绝对坐标，直接使用
        if is_relative_coords:
            actual_centers = self.selected_to_current_coords(selected_centers)
        else:
            # 绝对坐标，直接使用（确保格式正确）
            actual_centers = selected_centers

        if not for_slipway:
            self.del_centers = list(set(self.del_centers) | set(actual_centers))

        # 用于相对→绝对
        self.full_sorted_current_centers_up, self.full_sorted_current_centers_down = (
            self.group_centers_by_y(self.global_centers)
        )

        # 逐项解析：优先尝试相对坐标，失败则按绝对坐标处理
        abs_keys = set()
        if isinstance(selected_centers, list):
            for item in selected_centers:
                if not (isinstance(item, (list, tuple)) and len(item) == 2):
                    continue
                a, b = item[0], item[1]
                tried_rel = False
                if isinstance(a, int) and isinstance(b, int):
                    try:
                        row_label, col_label = int(a), int(b)
                        if row_label > 0:
                            g, ri = self.full_sorted_current_centers_up, row_label - 1
                        else:
                            g, ri = (
                                self.full_sorted_current_centers_down,
                                -row_label - 1,
                            )
                        ci = abs(col_label) - 1
                        x, y = g[ri][ci]  # 若越界抛异常
                        abs_keys.add(key6(x, y))
                        tried_rel = True
                    except Exception:
                        tried_rel = True  # 尝试过相对但失败，转绝对
                if not tried_rel:
                    # 作为绝对坐标解析
                    try:
                        abs_keys.add(key6(float(a), float(b)))
                    except Exception:
                        pass
        else:
            return []

        if not abs_keys:
            return []

        # 先处理与径向开孔绑定的换热管：
        # 若 selected_centers 中包含某个 radial_hole_dict 条目的“换热管坐标”，
        # 则删除对应的径向开孔绘图，并将该条记录的“换热管坐标”置空。
        try:
            if hasattr(self, "radial_hole_dict") and isinstance(
                    self.radial_hole_dict, dict
            ):
                print(f"[radial_hole] delete_huanreguan abs_keys={abs_keys}")
                for code, info in list(self.radial_hole_dict.items()):
                    if not isinstance(info, dict):
                        continue
                    coord = info.get("换热管坐标")
                    if coord is None:
                        continue
                    try:
                        cx, cy = coord
                        key = key6(cx, cy)
                    except Exception as e:
                        print(f"[radial_hole] coord parse error for code={code}: {e}")
                        continue
                    print(f"[radial_hole] check code={code}, coord={coord}, key={key}")
                    if key in abs_keys:
                        print(f"[radial_hole] match found, remove graphics for code={code}, coord={coord}")
                        # 删除该径向开孔的图形（但保留坐标，以便后续重新绘制）
                        try:
                            if hasattr(self, "remove_radial_hole_graphics"):
                                self.remove_radial_hole_graphics(coord)
                        except Exception as e:
                            print(f"[radial_hole] remove_radial_hole_graphics error: {e}")
                        # 注意：这里不清空坐标，保留坐标以便在函数末尾重新绘制
                        # info["换热管坐标"] = None  # 注释掉，保留坐标
        except Exception as e:
            # 径向开孔处理失败不影响后续删除换热管逻辑
            print(f"[radial_hole] exception in delete_huanreguan radial handling: {e}")

        # 建“坐标 -> 椭圆列表”索引（统一 6 位 + 场景中心）
        from collections import defaultdict

        coord_index = defaultdict(list)
        for it in self.graphics_scene.items():
            if isinstance(it, QGraphicsEllipseItem):
                cx, cy = center_scene(it)
                coord_index[key6(cx, cy)].append(it)

        # ——⚠ 保留你的连线：保存→删除→恢复 —— #
        # 保存普通连接线
        saved_lines = []
        if hasattr(self, "connection_lines"):
            try:
                saved_lines = [
                    (line.line(), line.pen()) for line in self.connection_lines
                ]
                for line in self.connection_lines:
                    self.graphics_scene.removeItem(line)
            except Exception:
                pass

        # 保存交叉布管连接线（使用专门的变量）
        # 在删除换热管时，需要同时删除与被删除换热管相关的交叉布管线
        saved_cross_pipe_lines = []
        lines_to_delete = []  # 记录需要删除的交叉布管线
        deleted_abs_coord_pairs = []  # 记录被删除的绝对坐标对

        if hasattr(self, "cross_pipe_lines") and self.cross_pipe_lines:
            try:
                # 遍历所有交叉布管线，检查是否与被删除的换热管相关
                for line in self.cross_pipe_lines:
                    # 检查线是否存储了换热管坐标信息
                    if hasattr(line, "tube_coords") and line.tube_coords:
                        tube_coords = line.tube_coords
                        # 检查这条线的两个换热管坐标是否包含被删除的坐标
                        line_should_delete = False
                        for coord in tube_coords:
                            if len(coord) == 2:
                                coord_key = key6(coord[0], coord[1])
                                if coord_key in abs_keys:
                                    line_should_delete = True
                                    break

                        if line_should_delete:
                            # 这条线需要删除，不保存它
                            lines_to_delete.append(line)
                            # 记录被删除的绝对坐标对
                            if tube_coords and len(tube_coords) == 2:
                                deleted_abs_coord_pairs.append(tube_coords)
                            continue

                    # 对于没有 tube_coords 属性的旧线，保留它们（因为无法确定是否与删除的换热管相关）
                    # 保存不需要删除的线（包括数据格式：line_data, pen, tube_coords）
                    saved_cross_pipe_lines.append(
                        (line.line(), line.pen(), getattr(line, "tube_coords", None))
                    )

                # 从场景中移除所有线（包括需要删除的）
                for line in self.cross_pipe_lines:
                    try:
                        self.graphics_scene.removeItem(line)
                    except Exception:
                        pass

                # 从 cross_pipe_lines 列表中移除需要删除的线
                if lines_to_delete:
                    self.cross_pipe_lines = [
                        line
                        for line in self.cross_pipe_lines
                        if line not in lines_to_delete
                    ]

                # 从 abs_coords_line1/2/3 中移除被删除的绝对坐标对
                if deleted_abs_coord_pairs:

                    def remove_coord_pairs_from_list(coord_list, pairs_to_remove):
                        """从列表中移除指定的坐标对"""
                        if not coord_list:
                            return []
                        result = []
                        pairs_to_remove_set = set()
                        # 将坐标对转换为key6格式以便比较
                        for pair in pairs_to_remove:
                            if len(pair) == 2:
                                try:
                                    # 处理元组或列表格式的坐标
                                    coord1 = (
                                        pair[0]
                                        if isinstance(pair[0], (list, tuple))
                                        else [pair[0]]
                                    )
                                    coord2 = (
                                        pair[1]
                                        if isinstance(pair[1], (list, tuple))
                                        else [pair[1]]
                                    )
                                    if len(coord1) >= 2 and len(coord2) >= 2:
                                        key1 = key6(coord1[0], coord1[1])
                                        key2 = key6(coord2[0], coord2[1])
                                        pairs_to_remove_set.add((key1, key2))
                                        pairs_to_remove_set.add(
                                            (key2, key1)
                                        )  # 双向匹配
                                except (IndexError, TypeError) as e:
                                    print(f"处理被删除坐标对时出错: {e}, pair: {pair}")
                                    continue

                        for pair in coord_list:
                            try:
                                if len(pair) == 2:
                                    # 处理元组或列表格式的坐标
                                    coord1 = (
                                        pair[0]
                                        if isinstance(pair[0], (list, tuple))
                                        else [pair[0]]
                                    )
                                    coord2 = (
                                        pair[1]
                                        if isinstance(pair[1], (list, tuple))
                                        else [pair[1]]
                                    )
                                    if len(coord1) >= 2 and len(coord2) >= 2:
                                        key1 = key6(coord1[0], coord1[1])
                                        key2 = key6(coord2[0], coord2[1])
                                        if (key1, key2) not in pairs_to_remove_set:
                                            result.append(pair)
                                    else:
                                        # 格式不匹配的保留
                                        result.append(pair)
                                else:
                                    # 格式不匹配的保留（可能是旧数据）
                                    result.append(pair)
                            except (IndexError, TypeError) as e:
                                # 出错时保留该坐标对
                                print(f"处理坐标对时出错: {e}, pair: {pair}")
                                result.append(pair)
                        return result

                    # 更新三个排的绝对坐标对
                    old_line1_count = len(getattr(self, "abs_coords_line1", []))
                    old_line2_count = len(getattr(self, "abs_coords_line2", []))
                    old_line3_count = len(getattr(self, "abs_coords_line3", []))

                    if hasattr(self, "abs_coords_line1") and self.abs_coords_line1:
                        self.abs_coords_line1 = remove_coord_pairs_from_list(
                            self.abs_coords_line1, deleted_abs_coord_pairs
                        )
                    if hasattr(self, "abs_coords_line2") and self.abs_coords_line2:
                        self.abs_coords_line2 = remove_coord_pairs_from_list(
                            self.abs_coords_line2, deleted_abs_coord_pairs
                        )
                    if hasattr(self, "abs_coords_line3") and self.abs_coords_line3:
                        self.abs_coords_line3 = remove_coord_pairs_from_list(
                            self.abs_coords_line3, deleted_abs_coord_pairs
                        )

                    # 调试输出
                    new_line1_count = len(getattr(self, "abs_coords_line1", []))
                    new_line2_count = len(getattr(self, "abs_coords_line2", []))
                    new_line3_count = len(getattr(self, "abs_coords_line3", []))
                    if deleted_abs_coord_pairs:
                        print(
                            f"删除交叉布管配对: 删除了 {len(deleted_abs_coord_pairs)} 个配对"
                        )
                        print(
                            f"第一排: {old_line1_count} -> {new_line1_count}, 第二排: {old_line2_count} -> {new_line2_count}, 第三排: {old_line3_count} -> {new_line3_count}"
                        )

            except Exception as e:
                print(f"处理交叉布管线时出错: {e}")
                pass

        # 批量删除与补白
        white_pen = QPen(QColor(255, 255, 255))
        white_pen.setWidth(3)
        white_brush = QBrush(QColor(255, 255, 255))

        v = self.graphics_scene.views()
        if v:
            v[0].setUpdatesEnabled(False)
        try:
            for kx, ky in abs_keys:
                has_rod = False
                # 清掉该坐标处所有“非白实心 & 非拉杆”的椭圆
                for it in list(coord_index.get((kx, ky), [])):
                    if is_rod(it):
                        has_rod = True
                        continue
                    if not is_white_solid(it):
                        try:
                            self.graphics_scene.removeItem(it)
                        except Exception:
                            pass
                # 若该位置不存在拉杆，再补白实心占位；避免覆盖红色拉杆
                if not has_rod:
                    self.graphics_scene.addEllipse(
                        kx - self.r,
                        ky - self.r,
                        2 * self.r,
                        2 * self.r,
                        white_pen,
                        white_brush,
                    )
        finally:
            if v:
                v[0].setUpdatesEnabled(True)

        # 同步 current_centers（按 6 位匹配）
        if hasattr(self, "current_centers"):
            self.current_centers = [
                (x, y) for (x, y) in self.current_centers if key6(x, y) not in abs_keys
            ]
        if hasattr(self, "current_centers_lagan"):
            self.current_centers_lagan = [
                (x, y)
                for (x, y) in self.current_centers_lagan
                if key6(x, y) not in abs_keys
            ]

        # ——恢复你的连线——
        # 恢复普通连接线
        if saved_lines and hasattr(self, "connection_lines"):
            self.connection_lines = []
            for line_data, pen in saved_lines:
                try:
                    new_line = self.graphics_scene.addLine(line_data, pen)
                    self.connection_lines.append(new_line)
                except Exception:
                    pass

        # 恢复交叉布管连接线（使用专门的变量）
        if saved_cross_pipe_lines and hasattr(self, "cross_pipe_lines"):
            # 清空现有的 cross_pipe_lines 列表（因为上面已经部分更新过，需要完全重建）
            self.cross_pipe_lines = []

            for line_item in saved_cross_pipe_lines:
                try:
                    # 处理不同的保存格式：可能是 (line_data, pen) 或 (line_data, pen, tube_coords)
                    if len(line_item) == 3:
                        line_data, pen, tube_coords = line_item
                    else:
                        line_data, pen = line_item
                        tube_coords = None

                    new_line = self.graphics_scene.addLine(line_data, pen)
                    if new_line:
                        new_line.setZValue(10)  # 设置较高的Z值确保显示在上层
                        # 恢复存储的坐标信息
                        if tube_coords:
                            new_line.tube_coords = tube_coords
                        self.cross_pipe_lines.append(new_line)
                except Exception as e:
                    print(f"恢复交叉布管线时出错: {e}")
                    pass

        # 删除与被删除换热管相关的交叉布管操作记录
        if hasattr(self, "operations") and self.operations:
            operations_to_keep = []
            for op in self.operations:
                if op.get("type") == "cross_pipe_tangents":
                    # 检查这条交叉布管记录的两个点是否包含被删除的坐标
                    points = op.get("points", [])
                    should_remove = False
                    for point in points:
                        if len(point) == 2:
                            point_key = key6(point[0], point[1])
                            if point_key in abs_keys:
                                should_remove = True
                                break
                    if not should_remove:
                        operations_to_keep.append(op)
                else:
                    # 非交叉布管操作记录，保留
                    operations_to_keep.append(op)
            self.operations = operations_to_keep

        # 操作记录（格式统一为与添加换热管一致）
        if not hasattr(self, "operations"):
            self.operations = []

        # --- 反查相对行列(row, col) ---
        def key6(x, y):
            return (round(float(x), 6), round(float(y), 6))

        def find_row_col_from_abs(x, y):
            # 从 full_sorted_current_centers_up/down 中反查 row,col
            k = key6(x, y)
            # 上半区
            for ri, row in enumerate(self.full_sorted_current_centers_up):
                for ci, (cx, cy) in enumerate(row):
                    if key6(cx, cy) == k:
                        return (ri + 1, ci + 1)
            # 下半区
            for ri, row in enumerate(self.full_sorted_current_centers_down):
                for ci, (cx, cy) in enumerate(row):
                    if key6(cx, cy) == k:
                        return (-(ri + 1), -(ci + 1))
            return (0, 0)  # 找不到返回 0,0，避免 KeyError

        for kx, ky in abs_keys:
            row, col = find_row_col_from_abs(kx, ky)
            self.operations.append(
                {
                    "type": "del",  # ✅ 统一格式，与 add_tube 对应
                    "row": row,
                    "col": col,
                    "absolute_coords": (kx, ky),  # 可选保留，便于撤销
                }
            )

        # ---- 刷新 ----
        self.update_total_holes_count()
        self.sorted_current_centers_up, self.sorted_current_centers_down = (
            self.group_centers_by_y(self.current_centers)
        )

        actual_centers = self.selected_to_current_coords(selected_centers)
        self.lagan_info = [
            coord for coord in self.lagan_info if coord not in actual_centers
        ]
        self.lagan_info = [
            coord for coord in self.lagan_info if coord not in selected_centers
        ]

        # 统一重算 current_centers_lagan = current_centers + lagan_info
        self._sync_current_centers_lagan()

        self.update_total_lagan_count()

        # 自动兼容不同命名
        if hasattr(self, "update_tube_nums"):
            self.update_tube_nums()
        elif hasattr(self, "update_tube_nums_y"):
            self.update_tube_nums()

        # 检查被删除的换热管是否作为某个防冲板的 selected_centers，如果是则删除该防冲板
        if hasattr(self, "baffle_items") and self.baffle_items:
            # 将被删除的坐标转换为相对坐标
            deleted_relative_coords = []
            # 方法1：如果输入是相对坐标（整数），直接使用
            if isinstance(selected_centers, list):
                for item in selected_centers:
                    if isinstance(item, (list, tuple)) and len(item) == 2:
                        a, b = item[0], item[1]
                        if isinstance(a, int) and isinstance(b, int):
                            deleted_relative_coords.append((a, b))

            # 方法2：利用已经计算好的 abs_keys，通过 find_row_col_from_abs 转换为相对坐标
            for kx, ky in abs_keys:
                rel_coord = find_row_col_from_abs(kx, ky)
                if rel_coord != (0, 0):  # 找到了有效坐标
                    if rel_coord not in deleted_relative_coords:
                        deleted_relative_coords.append(rel_coord)

            # 收集需要删除的防冲板（删除的换热管若为某防冲板端点，则需删除该防冲板）
            def _coord_match(a, b):
                """兼容 (row,col) 与 [row,col] 比较"""
                if not (isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)) and len(a) >= 2 and len(b) >= 2):
                    return False
                return a[0] == b[0] and a[1] == b[1]

            baffles_to_remove = []
            for baffle_item in self.baffle_items:
                if (
                        hasattr(baffle_item, "original_selected_centers")
                        and baffle_item.original_selected_centers
                ):
                    for deleted_coord in deleted_relative_coords:
                        if any(
                                _coord_match(deleted_coord, c)
                                for c in baffle_item.original_selected_centers
                        ):
                            baffles_to_remove.append(baffle_item)
                            break

            # 删除相关的防冲板
            for baffle_item in baffles_to_remove:
                # 从场景中删除
                if baffle_item.scene() == self.graphics_scene:
                    self.graphics_scene.removeItem(baffle_item)
                # 从 baffle_items 中删除
                if baffle_item in self.baffle_items:
                    self.baffle_items.remove(baffle_item)
                # 从 impingement_plate_1 或 impingement_plate_2 中删除对应的坐标对
                if (
                        hasattr(baffle_item, "original_selected_centers")
                        and baffle_item.original_selected_centers
                ):
                    if baffle_item.baffle_type == "平板形" and hasattr(
                            self, "impingement_plate_1"
                    ):
                        self.impingement_plate_1 = [
                            pair
                            for pair in self.impingement_plate_1
                            if pair != baffle_item.original_selected_centers
                        ]
                    elif baffle_item.baffle_type == "圆弧形" and hasattr(
                            self, "impingement_plate_2"
                    ):
                        self.impingement_plate_2 = [
                            pair
                            for pair in self.impingement_plate_2
                            if pair != baffle_item.original_selected_centers
                        ]
                # 同步从防冲板数据字典中移除
                if hasattr(baffle_item, "impingement_plate_id") and hasattr(
                        self, "impingement_plate_dic"
                ):
                    self.impingement_plate_dic.pop(
                        getattr(baffle_item, "impingement_plate_id"), None
                    )

        if hasattr(self, "clear_selection_highlight"):
            self.clear_selection_highlight()
        self.draw_baffle_plates()
        
        # 重新绘制所有径向开孔（保留坐标的）
        try:
            if hasattr(self, "radial_hole_dict") and isinstance(self.radial_hole_dict, dict):
                print(f"[radial_hole] 开始重新绘制所有径向开孔，字典条目数: {len(self.radial_hole_dict)}")
                redraw_count = 0
                for code, info in self.radial_hole_dict.items():
                    if not isinstance(info, dict):
                        print(f"[radial_hole] 条目 {code} 不是字典类型: {type(info)}")
                        continue
                    coord = info.get("换热管坐标")
                    if coord is None:
                        print(f"[radial_hole] 条目 {code} 的坐标为空")
                        continue
                    print(f"[radial_hole] 重新绘制径向开孔 {code}, 坐标={coord}, 坐标类型={type(coord)}")
                    try:
                        self.draw_radial_hole_tangents(coord)
                        redraw_count += 1
                        print(f"[radial_hole] 成功重新绘制径向开孔 {code}")
                    except Exception as e:
                        print(f"[radial_hole] 重新绘制径向开孔 {code} 时出错: {e}")
                        import traceback
                        traceback.print_exc()
                print(f"[radial_hole] 重新绘制完成，共绘制 {redraw_count} 个径向开孔")
            else:
                print(f"[radial_hole] radial_hole_dict 不存在或不是字典类型")
        except Exception as e:
            print(f"[radial_hole] 重新绘制所有径向开孔时出错: {e}")
            import traceback
            traceback.print_exc()

        if (
                not getattr(self, "_cleanup_unpaired_cross_pipe_busy", False)
                and not getattr(self, "is_loading_data", False)
        ):
            try:
                self.cleanup_unpaired_tubes_after_cross_pipe_delete()
            except Exception as e:
                print(f"[delete_huanreguan] cleanup_unpaired_tubes_after_cross_pipe_delete: {e}")

    # 10/24 修改，解决管板连接页面多次查询后重复展示的问题。修改以下2个函数，加上先删除旧数据
    def copy_tube_sheet_connection_data(self):
        """
        从元件库的管板连接表读取数据，向产品设计活动库的产品设计活动表_管板连接表存储数据
        """
        try:
            # === 连接数据库 ===
            component_conn = create_component_connection()
            if not component_conn:
                print("无法连接到元件库")
                return False

            # 创建产品设计活动库连接
            product_conn = create_product_connection()
            if not product_conn:
                print("无法连接到产品设计活动库")
                return False

            # === 先检查产品设计活动库中是否已存在该产品ID的数据 ===
            with product_conn.cursor() as product_cursor:
                check_query = """
                    SELECT COUNT(*) as count
                    FROM 产品设计活动表_管板连接表
                    WHERE 产品ID = %s
                """
                product_cursor.execute(check_query, (self.productID,))
                result = product_cursor.fetchone()

                if result and result.get("count", 0) > 0:
                    print(f"产品ID={self.productID} 在管板连接表中已存在数据，跳过操作")
                    return True

            # === 从元件库读取数据 ===
            with component_conn.cursor() as component_cursor:
                select_query = """
                    SELECT 参数名, 参数值, 管板连接示意图, 管板连接方式, 管板类型
                    FROM 管板连接表
                """
                component_cursor.execute(select_query)
                tube_sheet_data = component_cursor.fetchall()

            if not tube_sheet_data:
                print("元件库中没有管板连接数据")
                return False

            # === 插入前删除旧数据（关键） ===
            with product_conn.cursor() as product_cursor:
                delete_query = """
                    DELETE FROM 产品设计活动表_管板连接表
                    WHERE 产品ID = %s
                """
                product_cursor.execute(delete_query, (self.productID,))
                print(f"已删除产品ID={self.productID} 的旧管板连接数据")

                # === 插入新数据 ===
                insert_query = """
                    INSERT INTO 产品设计活动表_管板连接表 
                    (产品ID, 参数名, 参数值, 管板连接示意图, 管板连接方式, 管板连接更改状态, 管板类型)
                    VALUES (%s, %s, %s, %s, %s, %s, %s)
                """
                insert_data = [
                    (
                        self.productID,
                        row.get("参数名", ""),
                        row.get("参数值", ""),
                        row.get("管板连接示意图", ""),
                        row.get("管板连接方式", ""),
                        "0",
                        row.get("管板类型", ""),
                    )
                    for row in tube_sheet_data
                ]
                product_cursor.executemany(insert_query, insert_data)
                product_conn.commit()

            print(
                f"✅ 成功从元件库复制了 {len(insert_data)} 条管板连接数据到产品设计活动库"
            )
            return True

        except Exception as e:
            print(f"复制管板连接数据时出错: {e}")
            import traceback

            traceback.print_exc()
            return False

        finally:
            try:
                if "component_conn" in locals() and component_conn:
                    component_conn.close()
                if "product_conn" in locals() and product_conn:
                    product_conn.close()
            except Exception as e:
                print(f"关闭数据库连接时出错: {e}")

