    def delete_cross_pipes_for_selected_centers(self, selected_centers):
        """根据传入的 selected_centers 删除与这些换热管相干涉的交叉布管。

        - selected_centers: 可以是 [(x, y), ...] 或相对坐标 (行, 列)，
          解析和坐标处理逻辑与 build_lagan 中保持一致。
        - 若没有任何相关交叉布管，则不做任何处理。
        """

        import ast

        def key6(x, y):
            return (round(float(x), 6), round(float(y), 6))

        # 解析输入（支持列表或字符串形式）
        selected_centers_list = []
        if isinstance(selected_centers, list):
            selected_centers_list = [
                item
                for item in selected_centers
                if isinstance(item, tuple)
                   and len(item) == 2
                   and all(isinstance(x, (int, float)) for x in item)
            ]
        elif isinstance(selected_centers, str):
            try:
                parsed_list = ast.literal_eval(selected_centers)
                if isinstance(parsed_list, list):
                    selected_centers_list = [
                        item
                        for item in parsed_list
                        if isinstance(item, tuple)
                           and len(item) == 2
                           and all(isinstance(x, (int, float)) for x in item)
                    ]
            except (SyntaxError, ValueError, TypeError):
                selected_centers_list = []
        else:
            selected_centers_list = []

        if not selected_centers_list:
            return

        # 准备坐标分组数据（用于相对→绝对转换）
        self.full_sorted_current_centers_up, self.full_sorted_current_centers_down = (
            self.group_centers_by_y(self.global_centers)
        )

        abs_coords = []  # 存储绝对坐标
        rel_coords = []  # 存储相对坐标（若需要）
        abs_coords_direct = []  # 存储无法反查相对坐标的绝对坐标（直接使用）

        for item in selected_centers_list:
            if not (isinstance(item, (list, tuple)) and len(item) == 2):
                continue

            a, b = item[0], item[1]
            tried_rel = False

            # 判断是否为相对坐标（整数类型）
            if isinstance(a, int) and isinstance(b, int):
                try:
                    row_label, col_label = int(a), int(b)
                    if row_label > 0:
                        g, ri = self.full_sorted_current_centers_up, row_label - 1
                    else:
                        g, ri = self.full_sorted_current_centers_down, -row_label - 1
                    ci = abs(col_label) - 1
                    x, y = g[ri][ci]
                    abs_coords.append(key6(x, y))
                    rel_coords.append((row_label, col_label))
                    tried_rel = True
                except Exception:
                    tried_rel = True

            if not tried_rel:
                # 作为绝对坐标解析
                try:
                    abs_key = key6(float(a), float(b))
                    abs_coords.append(abs_key)
                    rel_coord = self.actual_to_selected_coords((float(a), float(b)))
                    if rel_coord:
                        rel_coords.append(rel_coord)
                    else:
                        abs_coords_direct.append((float(a), float(b)))
                except Exception:
                    pass

        all_abs_coords = abs_coords + [key6(x, y) for x, y in abs_coords_direct]
        if not all_abs_coords:
            return

        # 删除与这些换热管相关的交叉布管线（逻辑参考 build_lagan 中对应部分）
        if hasattr(self, "cross_pipe_lines") and self.cross_pipe_lines:
            try:
                abs_keys = set(all_abs_coords)

                lines_to_delete = []
                deleted_abs_coord_pairs = []

                for line in self.cross_pipe_lines:
                    if hasattr(line, "tube_coords") and line.tube_coords:
                        tube_coords = line.tube_coords
                        line_should_delete = False
                        for coord in tube_coords:
                            if len(coord) == 2:
                                coord_key = key6(coord[0], coord[1])
                                if coord_key in abs_keys:
                                    line_should_delete = True
                                    break

                        if line_should_delete:
                            lines_to_delete.append(line)
                            if tube_coords and len(tube_coords) == 2:
                                deleted_abs_coord_pairs.append(tube_coords)

                for line in lines_to_delete:
                    try:
                        if line.scene() == self.graphics_scene:
                            self.graphics_scene.removeItem(line)
                    except Exception:
                        pass

                if lines_to_delete:
                    self.cross_pipe_lines = [
                        line
                        for line in self.cross_pipe_lines
                        if line not in lines_to_delete
                    ]

                # 从 abs_coords_line1/2/3 中移除被删除的绝对坐标对
                if deleted_abs_coord_pairs:

                    def remove_coord_pairs_from_list(coord_list, pairs_to_remove):
                        if not coord_list:
                            return []
                        result = []
                        pairs_to_remove_set = set()
                        for pair in pairs_to_remove:
                            if len(pair) == 2:
                                try:
                                    coord1 = (
                                        pair[0]
                                        if isinstance(pair[0], (list, tuple))
                                        else [pair[0]]
                                    )
                                    coord2 = (
                                        pair[1]
                                        if isinstance(pair[1], (list, tuple))
                                        else [pair[1]]
                                    )
                                    if len(coord1) >= 2 and len(coord2) >= 2:
                                        key1 = key6(coord1[0], coord1[1])
                                        key2 = key6(coord2[0], coord2[1])
                                        pairs_to_remove_set.add((key1, key2))
                                        pairs_to_remove_set.add((key2, key1))
                                except (IndexError, TypeError):
                                    continue

                        for pair in coord_list:
                            try:
                                if len(pair) == 2:
                                    coord1 = (
                                        pair[0]
                                        if isinstance(pair[0], (list, tuple))
                                        else [pair[0]]
                                    )
                                    coord2 = (
                                        pair[1]
                                        if isinstance(pair[1], (list, tuple))
                                        else [pair[1]]
                                    )
                                    if len(coord1) >= 2 and len(coord2) >= 2:
                                        key1 = key6(coord1[0], coord1[1])
                                        key2 = key6(coord2[0], coord2[1])
                                        if (key1, key2) not in pairs_to_remove_set:
                                            result.append(pair)
                                    else:
                                        result.append(pair)
                                else:
                                    result.append(pair)
                            except (IndexError, TypeError):
                                result.append(pair)
                        return result

                    if hasattr(self, "abs_coords_line1") and self.abs_coords_line1:
                        self.abs_coords_line1 = remove_coord_pairs_from_list(
                            self.abs_coords_line1, deleted_abs_coord_pairs
                        )
                    if hasattr(self, "abs_coords_line2") and self.abs_coords_line2:
                        self.abs_coords_line2 = remove_coord_pairs_from_list(
                            self.abs_coords_line2, deleted_abs_coord_pairs
                        )
                    if hasattr(self, "abs_coords_line3") and self.abs_coords_line3:
                        self.abs_coords_line3 = remove_coord_pairs_from_list(
                            self.abs_coords_line3, deleted_abs_coord_pairs
                        )

                # 同步清理操作记录中的交叉布管条目
                if hasattr(self, "operations") and self.operations:
                    operations_to_keep = []
                    for op in self.operations:
                        if op.get("type") == "cross_pipe_tangents":
                            points = op.get("points", [])
                            should_remove = False
                            for point in points:
                                if len(point) == 2:
                                    point_key = key6(point[0], point[1])
                                    if point_key in abs_keys:
                                        should_remove = True
                                        break
                            if not should_remove:
                                operations_to_keep.append(op)
                        else:
                            operations_to_keep.append(op)
                    self.operations = operations_to_keep

            except Exception as e:
                print(f"处理交叉布管线时出错: {e}")
                return

        # 同步写回产品设计活动表_布管交叉布管表（含第一/二/三排绝对坐标对），避免残留旧数据
        try:
            self.build_sql_for_cross_pipes()
        except Exception as e:
            print(f"[delete_cross_pipes_for_selected_centers] 写回交叉布管表失败: {e}")

        try:
            self.cleanup_unpaired_tubes_after_cross_pipe_delete()
        except Exception as e:
            print(f"[delete_cross_pipes_for_selected_centers] 未配对换热管清理失败: {e}")

    def cleanup_unpaired_tubes_after_cross_pipe_delete(self):
        """
        删除已布置交叉布管后，按“当前剩余配对”二次清理同一行未配对换热管。
        目标：保证同一行最终仅保留仍可成对且已参与交叉布管的换热管。
        """
        if getattr(self, "_cleanup_unpaired_cross_pipe_busy", False):
            return

        if not hasattr(self, "current_centers") or not self.current_centers:
            return

        # 若未启用任一交叉布管行，直接返回
        has_cross_rows = any(
            getattr(self, attr, False)
            for attr in [
                "is_x_line1",
                "is_x_line2",
                "is_x_line3",
                "is_y_line1",
                "is_y_line2",
                "is_y_line3",
            ]
        )
        if not has_cross_rows:
            return

        self._cleanup_unpaired_cross_pipe_busy = True
        try:

            def key6(x, y):
                return (round(float(x), 6), round(float(y), 6))

            def extract_xy(point):
                if not isinstance(point, (list, tuple)):
                    return None
                if len(point) >= 3:
                    return (point[-2], point[-1])
                if len(point) >= 2:
                    return (point[0], point[1])
                return None

            def flatten_pair_keys(pair_list):
                keys = set()
                if not isinstance(pair_list, list):
                    return keys
                for pair in pair_list:
                    if not isinstance(pair, (list, tuple)) or len(pair) != 2:
                        continue
                    p1 = extract_xy(pair[0])
                    p2 = extract_xy(pair[1])
                    if p1 and p2:
                        keys.add(key6(p1[0], p1[1]))
                        keys.add(key6(p2[0], p2[1]))
                return keys

            # 基于当前剩余换热管重算候选行
            self.sorted_current_centers_up, self.sorted_current_centers_down = (
                self.group_centers_by_y(self.current_centers)
            )
            self.find_closest_to_axes()
            self.update_print_cross_lines()

            rows = [
                (
                    1,
                    getattr(self, "is_x_line1", False),
                    getattr(self, "is_y_line1", False),
                    getattr(self, "print_cross_x_up_line1", []),
                    getattr(self, "print_cross_x_down_line1", []),
                    getattr(self, "print_cross_y_left_line1", []),
                    getattr(self, "print_cross_y_right_line1", []),
                    getattr(self, "abs_coords_line1", []),
                ),
                (
                    2,
                    getattr(self, "is_x_line2", False),
                    getattr(self, "is_y_line2", False),
                    getattr(self, "print_cross_x_up_line2", []),
                    getattr(self, "print_cross_x_down_line2", []),
                    getattr(self, "print_cross_y_left_line2", []),
                    getattr(self, "print_cross_y_right_line2", []),
                    getattr(self, "abs_coords_line2", []),
                ),
                (
                    3,
                    getattr(self, "is_x_line3", False),
                    getattr(self, "is_y_line3", False),
                    getattr(self, "print_cross_x_up_line3", []),
                    getattr(self, "print_cross_x_down_line3", []),
                    getattr(self, "print_cross_y_left_line3", []),
                    getattr(self, "print_cross_y_right_line3", []),
                    getattr(self, "abs_coords_line3", []),
                ),
            ]

            to_delete_rel = []
            active_keys = {
                key6(x, y)
                for (x, y) in (self.current_centers if self.current_centers else [])
            }

            lagan_keys = set()
            for c in getattr(self, "lagan_info", None) or []:
                if isinstance(c, (list, tuple)) and len(c) >= 2:
                    try:
                        lagan_keys.add(key6(float(c[0]), float(c[1])))
                    except (TypeError, ValueError):
                        pass

            for row_no, is_x, is_y, x_up, x_down, y_left, y_right, abs_pairs in rows:
                if not is_x and not is_y:
                    continue

                pair_keys = flatten_pair_keys(abs_pairs)
                candidate_points = []
                if is_x:
                    candidate_points = list(x_up or []) + list(x_down or [])
                elif is_y:
                    candidate_points = list(y_left or []) + list(y_right or [])

                candidate_keys = set()
                for p in candidate_points:
                    xy = extract_xy(p)
                    if not xy:
                        continue
                    k = key6(xy[0], xy[1])
                    if k in active_keys:
                        candidate_keys.add(k)

                unmatched_keys = candidate_keys - pair_keys
                if unmatched_keys:
                    print(
                        f"[cleanup_unpaired_tubes_after_cross_pipe_delete] row={row_no}, unmatched={len(unmatched_keys)}"
                    )
                for pt_key in unmatched_keys:
                    if pt_key in lagan_keys:
                        continue
                    rel = self.actual_to_selected_coords((pt_key[0], pt_key[1]))
                    if rel and rel not in to_delete_rel:
                        to_delete_rel.append(rel)

            if to_delete_rel:
                self.delete_huanreguan(to_delete_rel)
        finally:
            self._cleanup_unpaired_cross_pipe_busy = False

    def _find_rod_at_position(self, coord, candidate_radius=None, tolerance=1e-4):
        """查找与候选圆位置重合或相交的普通拉杆/自由拉杆。"""
        try:
            target_x, target_y = float(coord[0]), float(coord[1])
        except (TypeError, ValueError, IndexError, OverflowError):
            return None
        try:
            candidate_radius = (
                float(candidate_radius)
                if candidate_radius is not None
                else None
            )
        except (TypeError, ValueError, OverflowError):
            candidate_radius = None

        scene = getattr(self, "graphics_scene", None)
        if scene is None:
            return None

        for item in scene.items():
            if not (
                    getattr(item, "is_lagan", False)
                    or getattr(item, "is_side_rod", False)
            ):
                continue
            try:
                center = item.mapToScene(item.rect().center())
                item_x, item_y = float(center.x()), float(center.y())
                item_radius = max(
                    float(item.rect().width()),
                    float(item.rect().height()),
                ) / 2.0
            except Exception:
                continue
            dx = item_x - target_x
            dy = item_y - target_y
            if candidate_radius is None:
                conflicts = abs(dx) <= tolerance and abs(dy) <= tolerance
            else:
                conflicts = (
                    dx * dx + dy * dy
                    < (candidate_radius + item_radius - tolerance) ** 2
                )
            if conflicts:
                return item
        return None

    def _find_tube_at_position(self, coord, candidate_radius, tolerance=1e-4):
        """查找与候选自由拉杆圆相交的现存换热管圆心。"""
        try:
            target_x, target_y = float(coord[0]), float(coord[1])
            candidate_radius = float(candidate_radius)
            tube_radius = float(getattr(self, "r", 0) or 0)
        except (TypeError, ValueError, IndexError, OverflowError):
            return None
        if candidate_radius <= 0 or tube_radius <= 0:
            return None

        for tube_coord in list(getattr(self, "current_centers", []) or []):
            try:
                tube_x, tube_y = float(tube_coord[0]), float(tube_coord[1])
            except (TypeError, ValueError, IndexError, OverflowError):
                continue
            dx = tube_x - target_x
            dy = tube_y - target_y
            minimum_distance = candidate_radius + tube_radius
            if dx * dx + dy * dy < (minimum_distance - tolerance) ** 2:
                return tube_x, tube_y
        return None

    def _is_free_rod_position_external(self, coord, tolerance=1e-6):
        """自由拉杆圆心必须位于全部换热管圆心的凸包之外。"""
        try:
            target = float(coord[0]), float(coord[1])
            points = sorted(
                {
                    (float(x), float(y))
                    for x, y in (getattr(self, "global_centers", []) or [])
                }
            )
        except Exception:
            return False
        if len(points) < 3:
            return False

        def cross(origin, point_a, point_b):
            return (
                    (point_a[0] - origin[0]) * (point_b[1] - origin[1])
                    - (point_a[1] - origin[1]) * (point_b[0] - origin[0])
            )

        lower = []
        for point in points:
            while (
                    len(lower) >= 2
                    and cross(lower[-2], lower[-1], point) <= 0
            ):
                lower.pop()
            lower.append(point)

        upper = []
        for point in reversed(points):
            while (
                    len(upper) >= 2
                    and cross(upper[-2], upper[-1], point) <= 0
            ):
                upper.pop()
            upper.append(point)

        hull = lower[:-1] + upper[:-1]
        if len(hull) < 3:
            return False

        return any(
            cross(hull[index], hull[(index + 1) % len(hull)], target)
            < -tolerance
            for index in range(len(hull))
        )

    def build_lagan(self, selected_centers, suppress_conflict_warning=False):
        self.operation_order += 1
        if not selected_centers:
            return None

        import ast

        # 小工具函数
        def key6(x, y):
            return (round(float(x), 6), round(float(y), 6))

        # 解析输入（字符串转列表）
        selected_centers_list = []
        if isinstance(selected_centers, list):
            selected_centers_list = [
                item
                for item in selected_centers
                if isinstance(item, tuple)
                   and len(item) == 2
                   and all(isinstance(x, (int, float)) for x in item)
            ]
        elif isinstance(selected_centers, str):
            try:
                parsed_list = ast.literal_eval(selected_centers)
                if isinstance(parsed_list, list):
                    selected_centers_list = [
                        item
                        for item in parsed_list
                        if isinstance(item, tuple)
                           and len(item) == 2
                           and all(isinstance(x, (int, float)) for x in item)
                    ]
            except (SyntaxError, ValueError, TypeError) as e:
                selected_centers_list = []
        else:
            selected_centers_list = []

        if not selected_centers_list:
            return None

        # 对称分布中，位于 x/y 轴上的点会映射出重复坐标。
        # 同一次构建必须先去重，避免重复绘制或误报位置冲突。
        selected_centers_list = list(dict.fromkeys(selected_centers_list))
        selected_centers_list = self._dedupe_centers_by_absolute(
            selected_centers_list
        )

        if not getattr(self, "is_loading_data", False):
            selected_centers_list, _ = self._filter_coords_blocked_by_true_slipway(
                selected_centers_list,
                suppress_warning=suppress_conflict_warning,
            )
            if not selected_centers_list:
                return None

        # 准备坐标分组数据（用于相对→绝对转换）
        self.full_sorted_current_centers_up, self.full_sorted_current_centers_down = (
            self.group_centers_by_y(self.global_centers)
        )

        # ========== 智能坐标类型判断和转换（参考 delete_huanreguan） ==========
        abs_coords = []  # 存储绝对坐标
        rel_coords = []  # 存储相对坐标（用于绘制）
        abs_coords_direct = []  # 存储无法反查相对坐标的绝对坐标（直接绘制）

        for item in selected_centers_list:
            if not (isinstance(item, (list, tuple)) and len(item) == 2):
                continue

            a, b = item[0], item[1]
            tried_rel = False

            # 判断是否为相对坐标（整数类型）
            if isinstance(a, int) and isinstance(b, int):
                try:
                    row_label, col_label = int(a), int(b)
                    if row_label > 0:
                        g, ri = self.full_sorted_current_centers_up, row_label - 1
                    else:
                        g, ri = self.full_sorted_current_centers_down, -row_label - 1
                    ci = abs(col_label) - 1
                    x, y = g[ri][ci]  # 若越界抛异常
                    abs_coords.append(key6(x, y))
                    rel_coords.append((row_label, col_label))
                    tried_rel = True
                except Exception:
                    tried_rel = True  # 尝试过相对但失败，转绝对

            if not tried_rel:
                # 作为绝对坐标解析
                try:
                    abs_key = key6(float(a), float(b))
                    abs_coords.append(abs_key)
                    # 反查相对坐标（用于绘制）
                    rel_coord = self.actual_to_selected_coords((float(a), float(b)))
                    if rel_coord:
                        rel_coords.append(rel_coord)
                    else:
                        # 如果反查失败，保存到直接绘制列表（使用原始坐标，不是key6格式）
                        abs_coords_direct.append((float(a), float(b)))
                        # 注意：abs_coords 中已经添加了，不需要删除
                except Exception:
                    pass

        # 合并所有绝对坐标（用于 lagan_info 更新）
        all_abs_coords = abs_coords + [key6(x, y) for x, y in abs_coords_direct]

        if not all_abs_coords:
            return None

        # 普通拉杆与自由拉杆共用同一套实际位置占位规则。
        # 任一位置已有拉杆图元时，不允许再次放置另一种拉杆。
        occupied_keys = {
            key6(coord[0], coord[1])
            for coord in all_abs_coords
            if self._find_rod_at_position(
                coord,
                candidate_radius=float(getattr(self, "r", 0) or 0),
            ) is not None
        }
        if occupied_keys:
            if (
                    not getattr(self, "is_loading_data", False)
                    and not suppress_conflict_warning
            ):

                QMessageBox.warning(
                    self,
                    "拉杆位置冲突",
                    "所选位置已存在普通拉杆或自由拉杆，不能重复布置。",
                )
            else:
                print(
                    f"[build_lagan] 加载时跳过 {len(occupied_keys)} 个"
                    f"与已有普通拉杆/自由拉杆重叠的位置"
                )

            abs_coords = [
                coord
                for coord in abs_coords
                if key6(coord[0], coord[1]) not in occupied_keys
            ]
            abs_coords_direct = [
                coord
                for coord in abs_coords_direct
                if key6(coord[0], coord[1]) not in occupied_keys
            ]

            filtered_rel_coords = []
            for rel_coord in rel_coords:
                actual = self.selected_to_current_coords([rel_coord])
                if (
                        actual
                        and key6(actual[0][0], actual[0][1]) not in occupied_keys
                ):
                    filtered_rel_coords.append(rel_coord)
            rel_coords = filtered_rel_coords

            all_abs_coords = list(
                dict.fromkeys(
                    abs_coords
                    + [key6(x, y) for x, y in abs_coords_direct]
                )
            )
            if not all_abs_coords:
                self.clear_selection_highlight()
                self.selected_centers = []
                return None

        # 删除与转为拉杆的换热管相关的交叉布管线（参考 delete_huanreguan 的逻辑）
        if hasattr(self, "cross_pipe_lines") and self.cross_pipe_lines:
            try:
                # 构建 abs_keys 集合（与 delete_huanreguan 中的格式一致）
                # 包含所有绝对坐标（包括直接绘制的坐标）
                abs_keys = set(all_abs_coords)

                lines_to_delete = []  # 记录需要删除的交叉布管线
                deleted_abs_coord_pairs = []  # 记录被删除的绝对坐标对

                # 遍历所有交叉布管线，检查是否与转为拉杆的换热管相关
                for line in self.cross_pipe_lines:
                    # 检查线是否存储了换热管坐标信息
                    if hasattr(line, "tube_coords") and line.tube_coords:
                        tube_coords = line.tube_coords
                        # 检查这条线的两个换热管坐标是否包含转为拉杆的坐标
                        line_should_delete = False
                        for coord in tube_coords:
                            if len(coord) == 2:
                                coord_key = key6(coord[0], coord[1])
                                if coord_key in abs_keys:
                                    line_should_delete = True
                                    break

                        if line_should_delete:
                            # 这条线需要删除
                            lines_to_delete.append(line)
                            # 记录被删除的绝对坐标对
                            if tube_coords and len(tube_coords) == 2:
                                deleted_abs_coord_pairs.append(tube_coords)

                # 从场景中移除需要删除的线
                for line in lines_to_delete:
                    try:
                        if line.scene() == self.graphics_scene:
                            self.graphics_scene.removeItem(line)
                    except Exception:
                        pass

                # 从 cross_pipe_lines 列表中移除需要删除的线
                if lines_to_delete:
                    self.cross_pipe_lines = [
                        line
                        for line in self.cross_pipe_lines
                        if line not in lines_to_delete
                    ]

                # 从 abs_coords_line1/2/3 中移除被删除的绝对坐标对
                if deleted_abs_coord_pairs:

                    def remove_coord_pairs_from_list(coord_list, pairs_to_remove):
                        """从列表中移除指定的坐标对"""
                        if not coord_list:
                            return []
                        result = []
                        pairs_to_remove_set = set()
                        # 将坐标对转换为key6格式以便比较
                        for pair in pairs_to_remove:
                            if len(pair) == 2:
                                try:
                                    # 处理元组或列表格式的坐标
                                    coord1 = (
                                        pair[0]
                                        if isinstance(pair[0], (list, tuple))
                                        else [pair[0]]
                                    )
                                    coord2 = (
                                        pair[1]
                                        if isinstance(pair[1], (list, tuple))
                                        else [pair[1]]
                                    )
                                    if len(coord1) >= 2 and len(coord2) >= 2:
                                        key1 = key6(coord1[0], coord1[1])
                                        key2 = key6(coord2[0], coord2[1])
                                        pairs_to_remove_set.add((key1, key2))
                                        pairs_to_remove_set.add(
                                            (key2, key1)
                                        )  # 双向匹配
                                except (IndexError, TypeError) as e:
                                    print(f"处理被删除坐标对时出错: {e}, pair: {pair}")
                                    continue

                        for pair in coord_list:
                            try:
                                if len(pair) == 2:
                                    # 处理元组或列表格式的坐标
                                    coord1 = (
                                        pair[0]
                                        if isinstance(pair[0], (list, tuple))
                                        else [pair[0]]
                                    )
                                    coord2 = (
                                        pair[1]
                                        if isinstance(pair[1], (list, tuple))
                                        else [pair[1]]
                                    )
                                    if len(coord1) >= 2 and len(coord2) >= 2:
                                        key1 = key6(coord1[0], coord1[1])
                                        key2 = key6(coord2[0], coord2[1])
                                        if (key1, key2) not in pairs_to_remove_set:
                                            result.append(pair)
                                    else:
                                        # 格式不匹配的保留
                                        result.append(pair)
                                else:
                                    # 格式不匹配的保留（可能是旧数据）
                                    result.append(pair)
                            except (IndexError, TypeError) as e:
                                # 出错时保留该坐标对
                                print(f"处理坐标对时出错: {e}, pair: {pair}")
                                result.append(pair)
                        return result

                    # 更新三个排的绝对坐标对
                    old_line1_count = len(getattr(self, "abs_coords_line1", []))
                    old_line2_count = len(getattr(self, "abs_coords_line2", []))
                    old_line3_count = len(getattr(self, "abs_coords_line3", []))

                    if hasattr(self, "abs_coords_line1") and self.abs_coords_line1:
                        self.abs_coords_line1 = remove_coord_pairs_from_list(
                            self.abs_coords_line1, deleted_abs_coord_pairs
                        )
                    if hasattr(self, "abs_coords_line2") and self.abs_coords_line2:
                        self.abs_coords_line2 = remove_coord_pairs_from_list(
                            self.abs_coords_line2, deleted_abs_coord_pairs
                        )
                    if hasattr(self, "abs_coords_line3") and self.abs_coords_line3:
                        self.abs_coords_line3 = remove_coord_pairs_from_list(
                            self.abs_coords_line3, deleted_abs_coord_pairs
                        )

                    # 调试输出
                    new_line1_count = len(getattr(self, "abs_coords_line1", []))
                    new_line2_count = len(getattr(self, "abs_coords_line2", []))
                    new_line3_count = len(getattr(self, "abs_coords_line3", []))
                    if deleted_abs_coord_pairs:
                        print(
                            f"拉杆删除交叉布管配对: 删除了 {len(deleted_abs_coord_pairs)} 个配对"
                        )
                        print(
                            f"第一排: {old_line1_count} -> {new_line1_count}, 第二排: {old_line2_count} -> {new_line2_count}, 第三排: {old_line3_count} -> {new_line3_count}"
                        )

                # 删除与转为拉杆的换热管相关的交叉布管操作记录
                if hasattr(self, "operations") and self.operations:
                    operations_to_keep = []
                    for op in self.operations:
                        if op.get("type") == "cross_pipe_tangents":
                            # 检查这条交叉布管记录的两个点是否包含转为拉杆的坐标
                            points = op.get("points", [])
                            should_remove = False
                            for point in points:
                                if len(point) == 2:
                                    point_key = key6(point[0], point[1])
                                    if point_key in abs_keys:
                                        should_remove = True
                                        break
                            if not should_remove:
                                operations_to_keep.append(op)
                        else:
                            # 非交叉布管操作记录，保留
                            operations_to_keep.append(op)
                    self.operations = operations_to_keep

            except Exception as e:
                print(f"处理交叉布管线时出错: {e}")
                pass

        # 检查是否与防冲板删除的换热管重合
        if (
                hasattr(self, "impingement_plate_del_centers")
                and self.impingement_plate_del_centers
        ):
            # 找出重合的坐标（按绝对坐标比较）
            impingement_set = set(
                key6(x, y) for x, y in self.impingement_plate_del_centers
            )
            # 检查 abs_coords 中的坐标
            overlapping_indices = [
                i for i, coord in enumerate(abs_coords) if coord in impingement_set
            ]
            # 检查 abs_coords_direct 中的坐标
            overlapping_direct = [
                coord
                for coord in abs_coords_direct
                if key6(coord[0], coord[1]) in impingement_set
            ]

            if overlapping_indices or overlapping_direct:

                total_conflicts = len(overlapping_indices) + len(overlapping_direct)
                if not suppress_conflict_warning:
                    QMessageBox.warning(
                        self,
                        "拉杆位置冲突",
                        f"部分坐标与防冲板相干涉，添加拉杆失败。\n\n"
                        f"冲突坐标数量: {total_conflicts}",
                    )

                # 从列表中删除重合的坐标（倒序删除避免索引问题）
                for i in sorted(overlapping_indices, reverse=True):
                    if i < len(abs_coords):
                        abs_coords.pop(i)
                    if i < len(rel_coords):
                        rel_coords.pop(i)

                # 从 abs_coords_direct 中删除重合的坐标
                for coord in overlapping_direct:
                    if coord in abs_coords_direct:
                        abs_coords_direct.remove(coord)

                # 重新计算 all_abs_coords（因为可能删除了重合的坐标）
                all_abs_coords = abs_coords + [key6(x, y) for x, y in abs_coords_direct]

                # 如果删除后没有有效坐标了，直接返回
                if not all_abs_coords:
                    self.selected_centers = []
                    return None

        # ========== 更新 self.lagan_info（统一存储绝对坐标） ==========
        # 合并已有的绝对坐标和新的绝对坐标，去重
        combined_abs = set()

        # 添加已有的拉杆坐标
        for coord in self.lagan_info:
            combined_abs.add(key6(coord[0], coord[1]))

        # 添加新的拉杆坐标
        for coord in all_abs_coords:
            combined_abs.add(coord)

        # 转换为列表形式存储（保留原始坐标格式，用于后续绘制）
        # 注意：这里存储的是 key6 格式的坐标，但我们需要保留原始坐标用于绘制
        self.lagan_info = list(combined_abs)

        # 维护 current_centers_lagan = current_centers + lagan_info
        self._sync_current_centers_lagan()

        # ========== 绘制逻辑（方式1：在换热管上绘制拉杆，不可选中） ==========
        # 初始化操作记录列表（如果不存在）
        if not hasattr(self, "operations"):
            self.operations = []

        # 绘制红色实心圆（改为 ClickableCircleItem，可选中/可双击编辑）
        red_pen = QPen(Qt.red)
        red_pen.setWidth(2)
        red_brush = QBrush(Qt.red)
        msg_lines = []

        # 1. 使用相对坐标进行绘制（原逻辑：直接使用 addEllipse 绘制，不可选中）
        if rel_coords:
            for idx, (row_label, col_label) in enumerate(rel_coords):
                try:
                    # 计算行/列索引（基于绝对值）
                    row_idx = abs(row_label) - 1
                    col_idx = abs(col_label) - 1

                    # 根据行号正负获取原始坐标
                    if row_label > 0:
                        if row_idx >= len(self.full_sorted_current_centers_up):
                            continue
                        if col_idx >= len(self.full_sorted_current_centers_up[row_idx]):
                            continue
                        x, y = self.full_sorted_current_centers_up[row_idx][col_idx]
                    else:
                        if row_idx >= len(self.full_sorted_current_centers_down):
                            continue
                        if col_idx >= len(
                                self.full_sorted_current_centers_down[row_idx]
                        ):
                            continue
                        x, y = self.full_sorted_current_centers_down[row_idx][col_idx]

                    if self._find_rod_at_position((x, y)) is not None:
                        continue

                    # 使用 ClickableCircleItem 绘制普通拉杆，使其支持选中和双击编辑
                    from PyQt5.QtCore import QRectF

                    ellipse_rect = QRectF(
                        x - self.r, y - self.r, 2 * self.r, 2 * self.r
                    )
                    ellipse_item = ClickableCircleItem(
                        ellipse_rect,
                        parent=None,
                        is_side_rod=False,
                        is_lagan=True,
                        editor=self,
                    )
                    ellipse_item.setPen(red_pen)
                    ellipse_item.setBrush(red_brush)
                    # 确保普通拉杆单击选中/取消后能恢复为红色实心样式
                    ellipse_item.original_pen = red_pen
                    ellipse_item.original_brush = red_brush
                    ellipse_item.position = (x, y)
                    ellipse_item.original_selected_center = (row_label, col_label)
                    # 设置 Z 值，确保拉杆可以被选中（与侧拉杆一致）
                    ellipse_item.setZValue(20)
                    self.graphics_scene.addItem(ellipse_item)

                    # 记录日志信息
                    msg_lines.append(f"第 {row_label} 行, 第 {col_label} 列")

                    # 添加操作记录
                    self.operations.append(
                        {
                            "type": "lagan",
                            "row": row_label,
                            "col": col_label,
                            "coord": (x, y),
                        }
                    )
                except Exception as e:
                    pass

        # 2. 直接使用绝对坐标绘制（对于无法反查相对坐标的坐标）
        if abs_coords_direct:
            for coord in abs_coords_direct:
                try:
                    x, y = coord
                    if self._find_rod_at_position((x, y)) is not None:
                        continue

                    # 使用 ClickableCircleItem 绘制普通拉杆，使其支持选中和双击编辑
                    from PyQt5.QtCore import QRectF

                    ellipse_rect = QRectF(
                        x - self.r, y - self.r, 2 * self.r, 2 * self.r
                    )
                    ellipse_item = ClickableCircleItem(
                        ellipse_rect,
                        parent=None,
                        is_side_rod=False,
                        is_lagan=True,
                        editor=self,
                    )
                    ellipse_item.setPen(red_pen)
                    ellipse_item.setBrush(red_brush)
                    # 确保普通拉杆单击选中/取消后能恢复为红色实心样式
                    ellipse_item.original_pen = red_pen
                    ellipse_item.original_brush = red_brush
                    ellipse_item.position = (x, y)
                    ellipse_item.original_selected_center = self.actual_to_selected_coords(
                        (x, y)
                    )
                    # 设置 Z 值，确保拉杆可以被选中（与侧拉杆一致）
                    ellipse_item.setZValue(20)
                    self.graphics_scene.addItem(ellipse_item)

                    # 添加操作记录
                    self.operations.append({"type": "lagan", "coord": (x, y)})
                except Exception as e:
                    pass

        # 更新当前中心点（移除已绘制为拉杆的坐标）
        actual_centers = self.selected_to_current_coords(selected_centers)
        self.del_centers = [
            coord for coord in self.del_centers if coord not in actual_centers
        ]
        # self.del_centers = [
        #     coord for coord in self.del_centers if coord not in selected_centers
        # ]

        # # 显示绘制结果
        # QMessageBox.information(self, "已绘制", "绘制圆心:\n" + "\n".join(msg_lines))
        self.update_total_lagan_count()
        self.clear_selection_highlight()
        self.selected_centers = []

        # 返回移除已绘制拉杆后的中心坐标列表（使用绝对坐标）
        abs_coords_set = set(all_abs_coords)
        # 这里不要更新self.current_centers_lagan
        new_centers = [
            center
            for center in self.current_centers
            if key6(center[0], center[1]) not in abs_coords_set
        ]
        # 先同步 current_centers，再清理未配对管（cleanup 依赖「拉杆已不占换热管位」）
        self.current_centers = new_centers
        if not getattr(self, "is_loading_data", False):
            try:
                self.cleanup_unpaired_tubes_after_cross_pipe_delete()
            except Exception as e:
                print(f"[build_lagan] cleanup_unpaired_tubes_after_cross_pipe_delete: {e}")
        # delete_huanreguan（cleanup 内）可能继续删管，需返回最新 current_centers
        return list(self.current_centers)

    def check_lagan_conflict(self, selected_centers):
        """
        检查选中的坐标是否与拉杆坐标冲突

        参数:
            selected_centers: 相对坐标列表，如 [(-10, -7), (-11, 14)]

        返回:
            bool: 如果有冲突（有相同坐标）返回 False，否则返回 True
                 如果 lagan_info 为空，也返回 True
        """
        # 如果 lagan_info 为空或不存在，返回 True
        if not hasattr(self, "lagan_info") or not self.lagan_info:
            return True

        # 如果 selected_centers 为空，返回 True
        if not selected_centers:
            return True

        # 将 selected_centers 转换为绝对坐标
        current_coords = self.selected_to_current_coords(selected_centers)
        if not current_coords:
            return True

        # 容差比较函数（使用 1e-5 的容差）
        def is_close(coord1, coord2, tol=1e-5):
            """判断两个坐标是否在容差范围内相等"""
            return abs(coord1[0] - coord2[0]) < tol and abs(coord1[1] - coord2[1]) < tol

        # 获取 lagan_info 的绝对坐标
        # 先尝试将 lagan_info 转换为绝对坐标（如果它存储的是相对坐标）
        lagan_abs_coords = self.selected_to_current_coords(self.lagan_info)

        # 如果转换结果为空，说明 lagan_info 可能已经存储的是绝对坐标
        # 在这种情况下，直接使用 lagan_info
        if not lagan_abs_coords:
            lagan_abs_coords = self.lagan_info

        # 检查是否有相同的坐标
        for coord1 in current_coords:
            for coord2 in lagan_abs_coords:
                # 确保 coord2 是包含两个元素的元组或列表
                if isinstance(coord2, (list, tuple)) and len(coord2) >= 2:
                    if is_close(coord1, (coord2[0], coord2[1])):
                        return False

        # 没有找到相同的坐标，返回 True
        return True

    def _dedupe_centers_by_absolute(self, centers_list):
        """相对坐标按映射后的绝对坐标去重（对称展开后轴上点可能重复）。"""
        if not centers_list:
            return []
        seen = set()
        result = []
        for item in centers_list:
            if not (isinstance(item, (list, tuple)) and len(item) == 2):
                continue
            actual_list = self.selected_to_current_coords([item])
            if actual_list:
                ax, ay = actual_list[0]
                key = (round(float(ax), 6), round(float(ay), 6))
                if key in seen:
                    continue
                seen.add(key)
            elif item in seen:
                continue
            else:
                seen.add(item)
            result.append(item)
        return result

    def _expand_centers_by_linkage(self, centers_list):
        """按对称/联动规则扩展坐标列表，与删除中心部件时逻辑一致（24733-24755）。"""
        if not centers_list:
            return list(centers_list) if centers_list is not None else []
        if self.isSymmetry:
            expanded = list(self.judge_linkage(centers_list))
            return self._dedupe_centers_by_absolute(expanded)
        tubeline_num = self.get_tube_pass_count()
        if tubeline_num == "2" and self.heat_exchanger in ["AEU", "BEU", "AKU", "BKU"]:
            return list(self.judge_linkage_x(centers_list))
        if tubeline_num in ("4", "6") and self.heat_exchanger in ["AEU", "BEU", "AKU", "BKU"]:
            return list(self.judge_linkage_y(centers_list))
        return list(centers_list)

    def judge_linkage(self, selected_centers):
        linkage_centers = []
        if not selected_centers:
            return linkage_centers

        # 处理字符串类型的输入
        if isinstance(selected_centers, str):
            try:
                import ast

                selected_centers = ast.literal_eval(selected_centers)
            except (SyntaxError, ValueError) as e:
                print(f"字符串转换失败: {e}")
                return linkage_centers

        current_coords = self.selected_to_current_coords(selected_centers)
        if current_coords:
            linkage_centers.extend(selected_centers)

            y_axis_syms = []
            x_axis_syms = []
            center_syms = []

            for i, (row_label, col_label) in enumerate(selected_centers):
                x, y = current_coords[i]
                y_axis_actual = (-x, y)
                x_axis_actual = (x, -y)
                center_actual = (-x, -y)

                y_axis_sym = self.actual_to_selected_coords(y_axis_actual)
                x_axis_sym = self.actual_to_selected_coords(x_axis_actual)
                center_sym = self.actual_to_selected_coords(center_actual)

                if y_axis_sym:
                    y_axis_syms.append(y_axis_sym)
                if x_axis_sym:
                    x_axis_syms.append(x_axis_sym)
                if center_sym:
                    center_syms.append(center_sym)
            linkage_centers.extend(y_axis_syms)
            linkage_centers.extend(x_axis_syms)
            linkage_centers.extend(center_syms)

        return linkage_centers

    def judge_linkage_lagan(self, selected_centers):
        linkage_centers = []
        if not selected_centers:
            return linkage_centers

        # 处理字符串类型的输入
        if isinstance(selected_centers, str):
            try:
                import ast

                selected_centers = ast.literal_eval(selected_centers)
            except (SyntaxError, ValueError) as e:
                print(f"字符串转换失败: {e}")
                return linkage_centers

        current_coords = self.selected_to_current_coords(selected_centers)
        if current_coords:
            # 添加初始选中的中心点，并检查重复
            for center in selected_centers:
                if center not in linkage_centers:
                    linkage_centers.append(center)

            y_axis_syms = []
            x_axis_syms = []
            center_syms = []

            for i, (row_label, col_label) in enumerate(selected_centers):
                x, y = current_coords[i]
                y_axis_actual = (-x, y)
                x_axis_actual = (x, -y)
                center_actual = (-x, -y)

                y_axis_sym = self.actual_to_selected_coords(y_axis_actual)
                x_axis_sym = self.actual_to_selected_coords(x_axis_actual)
                center_sym = self.actual_to_selected_coords(center_actual)

                if (
                        y_axis_sym
                        and y_axis_sym not in linkage_centers
                        and y_axis_sym not in y_axis_syms
                ):
                    y_axis_syms.append(y_axis_sym)
                if (
                        x_axis_sym
                        and x_axis_sym not in linkage_centers
                        and x_axis_sym not in x_axis_syms
                ):
                    x_axis_syms.append(x_axis_sym)
                if (
                        center_sym
                        and center_sym not in linkage_centers
                        and center_sym not in center_syms
                ):
                    center_syms.append(center_sym)

            # 添加对称点，并检查重复
            for sym_list in [y_axis_syms, x_axis_syms, center_syms]:
                for sym_point in sym_list:
                    if sym_point not in linkage_centers:
                        linkage_centers.append(sym_point)

        return linkage_centers

