        mode_layout.addLayout(mode_btn_layout)

        def _choose_row():
            nonlocal arrange_mode
            arrange_mode = "row"
            mode_dlg.accept()

        def _choose_col():
            nonlocal arrange_mode
            arrange_mode = "col"
            mode_dlg.accept()

        row_btn.clicked.connect(_choose_row)
        col_btn.clicked.connect(_choose_col)
        cancel_btn.clicked.connect(mode_dlg.reject)
