    def build_center_dangguan(self, selected_centers):
        self.operation_order += 1
        """构建中间挡管，支持选中功能（修复对称模式下多选删除问题）"""

        if not selected_centers:
            return []

        # 初始化center_dangguan
        if not hasattr(self, "center_dangguan"):
            self.center_dangguan = []

        import ast

        # 特殊处理：如果传入的是一个小列表（包含2个坐标），正常处理
        # 如果传入的是嵌套列表（多个挡管的坐标对），需要递归处理每一对
        if isinstance(selected_centers, list):
            # 检查是否是嵌套列表（如 [[coord1, coord2], [coord3, coord4]]）
            if (
                    len(selected_centers) > 0
                    and isinstance(selected_centers[0], list)
                    and all(
                isinstance(sublist, list) and len(sublist) == 2
                for sublist in selected_centers
            )
            ):

                # 这是嵌套列表，清空并逐对处理
                self.center_dangguan = []
                results = []
                for pair in selected_centers:
                    result = self._draw_single_dangguan_pair(pair)
                    if result:
                        results.extend(result)
                return results

            # 检查是否是扁平的长列表（如 [coord1, coord2, coord3, coord4]），需要成对拆分
            elif len(selected_centers) > 2 and all(
                    isinstance(item, tuple) and len(item) == 2 for item in selected_centers
            ):

                # 这是扁平列表，清空并成对处理
                self.center_dangguan = []
                results = []
                for i in range(0, len(selected_centers), 2):
                    if i + 1 < len(selected_centers):
                        pair = [selected_centers[i], selected_centers[i + 1]]
                        result = self._draw_single_dangguan_pair(pair)
                        if result:
                            results.extend(result)
                return results

        # 解析选中的坐标
        selected_centers_list = []
        if isinstance(selected_centers, list):
            selected_centers_list = [
                item
                for item in selected_centers
                if isinstance(item, tuple)
                   and len(item) == 2
                   and all(isinstance(x, (int, float)) for x in item)
            ]
        elif isinstance(selected_centers, str):
            try:
                parsed_list = ast.literal_eval(selected_centers)
                if isinstance(parsed_list, list):
                    selected_centers_list = [
                        item
                        for item in parsed_list
                        if isinstance(item, tuple)
                           and len(item) == 2
                           and all(isinstance(x, (int, float)) for x in item)
                    ]
            except (SyntaxError, ValueError, TypeError) as e:
                selected_centers_list = []
        else:
            selected_centers_list = []

        # 检查坐标对是否已存在（center_dangguan 现在是嵌套列表）
        # center_dangguan 格式：[[coord1, coord2], [coord3, coord4], ...]
        current_pair_set = set(selected_centers_list)

        # 检查是否已存在相同的坐标对
        pair_exists = False
        for existing_pair in self.center_dangguan:
            if set(existing_pair) == current_pair_set:
                pair_exists = True
                break

        # 保留原来的变量名以兼容后续代码
        has_any_existing = pair_exists

        # 检查当前坐标对是否会产生(0,0)位置的中间挡管
        should_skip = False

        if len(selected_centers_list) == 2:
            current_coords_temp = self.selected_to_current_coords(selected_centers_list)
            if current_coords_temp and len(current_coords_temp) == 2:
                points_temp = []
                for row_label, col_label in selected_centers_list:
                    row_idx = abs(row_label) - 1
                    col_idx = abs(col_label) - 1
                    centers_group = (
                        self.full_sorted_current_centers_up
                        if row_label > 0
                        else self.full_sorted_current_centers_down
                    )
                    if row_idx < len(centers_group) and col_idx < len(
                            centers_group[row_idx]
                    ):
                        x, y = centers_group[row_idx][col_idx]
                        points_temp.append((x, y))

                if len(points_temp) == 2:
                    x1, y1 = points_temp[0]
                    x2, y2 = points_temp[1]

                    # 根据管程数计算中间挡管的位置
                    tube_num = self.get_tube_pass_count()
                    dangguan1_pos = None

                    if tube_num == "2":
                        # 2管程时：y坐标为0
                        if x1 == x2:
                            dangguan1_pos = (x1, 0)
                        elif y1 == y2:
                            x_mid = (x1 + x2) / 2
                            dangguan1_pos = (x_mid, 0)
                        else:
                            x_mid = (x1 + x2) / 2
                            dangguan1_pos = (x_mid, 0)
                    else:
                        # 4,6管程时：x坐标为0
                        if x1 == x2:
                            y_mid = (y1 + y2) / 2
                            dangguan1_pos = (0, y_mid)
                        elif y1 == y2:
                            dangguan1_pos = (0, y1)
                        else:
                            y_mid = (y1 + y2) / 2
                            dangguan1_pos = (0, y_mid)

                    # 检查是否有挡管位置为(0, 0)
                    if dangguan1_pos == (0, 0):
                        # 检查self.center_dangguan中是否已经有会产生(0,0)位置的坐标对
                        # center_dangguan 现在是嵌套列表：[[coord1, coord2], [coord3, coord4], ...]
                        has_zero_position_pair = False
                        if len(self.center_dangguan) > 0:
                            for pair in self.center_dangguan:
                                if isinstance(pair, list) and len(pair) == 2:
                                    current_coords_check = (
                                        self.selected_to_current_coords(pair)
                                    )
                                    if (
                                            current_coords_check
                                            and len(current_coords_check) == 2
                                    ):
                                        points_check = []
                                        for row_label, col_label in pair:
                                            row_idx = abs(row_label) - 1
                                            col_idx = abs(col_label) - 1
                                            centers_group = (
                                                self.full_sorted_current_centers_up
                                                if row_label > 0
                                                else self.full_sorted_current_centers_down
                                            )
                                            if row_idx < len(
                                                    centers_group
                                            ) and col_idx < len(centers_group[row_idx]):
                                                x, y = centers_group[row_idx][col_idx]
                                                points_check.append((x, y))

                                        if len(points_check) == 2:
                                            x1, y1 = points_check[0]
                                            x2, y2 = points_check[1]

                                            # 根据管程数计算中间挡管的位置
                                            tube_num = self.get_tube_pass_count()
                                            dangguan1_pos_check = None

                                            if tube_num == "2":
                                                if x1 == x2:
                                                    dangguan1_pos_check = (x1, 0)
                                                elif y1 == y2:
                                                    x_mid = (x1 + x2) / 2
                                                    dangguan1_pos_check = (x_mid, 0)
                                                else:
                                                    x_mid = (x1 + x2) / 2
                                                    dangguan1_pos_check = (x_mid, 0)
                                            else:
                                                if x1 == x2:
                                                    y_mid = (y1 + y2) / 2
                                                    dangguan1_pos_check = (0, y_mid)
                                                elif y1 == y2:
                                                    dangguan1_pos_check = (0, y1)
                                                else:
                                                    y_mid = (y1 + y2) / 2
                                                    dangguan1_pos_check = (0, y_mid)

                                            if dangguan1_pos_check == (0, 0):
                                                has_zero_position_pair = True
                                                break

                        # 如果还没有添加过会产生(0,0)位置的坐标对，保留第一对；否则跳过
                        if not has_zero_position_pair:
                            # 标记这是第一对(0,0)位置挡管，需要加1
                            is_first_zero_position = True
                            # 在保留第一对坐标时同时给center_dangguan_num加1
                            self.center_dangguan_num += 1
                        else:
                            should_skip = True

        if not has_any_existing:
            # 坐标对不存在，可以安全添加
            # 注意：坐标会通过 draw_center_dangguan_at_position 函数自动添加到 center_dangguan 列表
            if not should_skip:
                # 不再手动添加，由 draw_center_dangguan_at_position 函数处理
                pass
            else:
                # 即使跳过添加坐标，也要计算数量
                # 只有第一对(0,0)位置挡管才加1，其他跳过的都不加
                if "is_first_zero_position" in locals() and is_first_zero_position:
                    self.center_dangguan_num += 1
                # 计算current_coords并返回
                current_coords = self.selected_to_current_coords(selected_centers)
                return current_coords

        current_coords = self.selected_to_current_coords(selected_centers)
        if not current_coords:
            return

        # 校验选中的圆心数量是否为2
        if not selected_centers:
            return current_coords

        if isinstance(selected_centers, str):
            try:
                import ast

                selected_centers = ast.literal_eval(selected_centers)
            except (SyntaxError, ValueError) as e:
                return current_coords

        points = []
        if selected_centers:
            for row_label, col_label in selected_centers:
                row_idx = abs(row_label) - 1
                col_idx = abs(col_label) - 1

                centers_group = (
                    self.full_sorted_current_centers_up
                    if row_label > 0
                    else self.full_sorted_current_centers_down
                )

                if row_idx < len(centers_group) and col_idx < len(
                        centers_group[row_idx]
                ):
                    x, y = centers_group[row_idx][col_idx]
                    points.append((x, y))

                    # 只移除临时的高亮图形，不删除换热管本身
                    click_point = QPointF(x, y)
                    for item in self.graphics_scene.items(click_point):
                        if isinstance(item, QGraphicsEllipseItem) and hasattr(
                                item, "is_temporary_highlight"
                        ):
                            self.graphics_scene.removeItem(item)
                            break

        if selected_centers and len(points) == 2:
            # 初始化选中列表
            if not hasattr(self, "selected_center_dangguan"):
                self.selected_center_dangguan = []

            # 定义创建挡管的函数，避免重复代码（返回创建的挡管对象）
            def create_dangguan(x, y, selected_center):
                # 关键修复：检查该位置是否已经存在挡管
                for item in self.graphics_scene.items():
                    if isinstance(item, ClickableRectItem) and item.is_center_dangguan:
                        # 获取挡管的位置（圆心）
                        item_rect = item.boundingRect()
                        item_center_x = item.x() + item_rect.center().x()
                        item_center_y = item.y() + item_rect.center().y()

                        if abs(item_center_x - x) < 2 and abs(item_center_y - y) < 2:
                            return None

                pen = QPen(QColor(128, 0, 128))  # 紫色
                pen.setWidth(3)
                brush = QBrush(Qt.NoBrush)  # 空心圆样式

                # 创建圆形路径
                path = QPainterPath()
                path.addEllipse(x - self.r, y - self.r, 2 * self.r, 2 * self.r)

                # 使用ClickableRectItem创建可选中中间挡管
                center_dangguan_item = ClickableRectItem(
                    path=path, is_center_dangguan=True, editor=self
                )
                center_dangguan_item.setPen(pen)
                center_dangguan_item.setBrush(brush)  # 设置为空心
                center_dangguan_item.original_pen = pen
                center_dangguan_item.original_selected_center = (
                    selected_center  # 存储原始选中坐标
                )
                center_dangguan_item.setZValue(10)
                self.graphics_scene.addItem(center_dangguan_item)

                # 记录操作
                if not hasattr(self, "operations"):
                    self.operations = []
                self.operations.append(
                    {"type": "center_block", "coord": (x, y), "from": points}
                )

                # print(f"创建挡管: selected_center={selected_center}, 位置=({x}, {y})")

                return center_dangguan_item

            x1, y1 = points[0]
            x2, y2 = points[1]

            # 根据管程数确定挡管位置规则
            tube_num = self.get_tube_pass_count()

            # 2管程时：y坐标为0
            if tube_num == "2":
                # X坐标相等时，挡管Y坐标应为0
                if x1 == x2:
                    # 挡管位置：X坐标保持，Y坐标为0
                    print(f"[调试] 中间挡管位置: ({x1}, 0)")
                    dangguan1 = create_dangguan(x1, 0, selected_centers[0])
                # Y坐标相等时，计算X轴中点，Y坐标为0
                elif y1 == y2:
                    x_mid = (x1 + x2) / 2
                    print(f"[调试] 中间挡管位置: ({x_mid}, 0)")
                    dangguan1 = create_dangguan(x_mid, 0, selected_centers[0])
                # 其他情况，计算X轴中点，Y坐标为0
                else:
                    x_mid = (x1 + x2) / 2
                    print(f"[调试] 中间挡管位置: ({x_mid}, 0)")
                    dangguan1 = create_dangguan(x_mid, 0, selected_centers[0])

                # 维护中间挡管数量
                if dangguan1:
                    self.center_dangguan_num += 1
                    print(
                        f"[调试] 中间挡管数量+1，当前总数: {self.center_dangguan_num}"
                    )

            # 4,6管程时：x坐标为0
            else:
                # X坐标相等时，计算Y轴中点，X坐标为0
                if x1 == x2:
                    y_mid = (y1 + y2) / 2
                    print(f"[调试] 中间挡管位置: (0, {y_mid})")
                    dangguan1 = create_dangguan(0, y_mid, selected_centers[0])
                # Y坐标相等时，挡管X坐标应为0
                elif y1 == y2:
                    # 挡管位置：Y坐标保持，X坐标为0
                    print(f"[调试] 中间挡管位置: (0, {y1})")
                    dangguan1 = create_dangguan(0, y1, selected_centers[0])
                # 其他情况，计算Y轴中点，X坐标为0
                else:
                    y_mid = (y1 + y2) / 2
                    print(f"[调试] 中间挡管位置: (0, {y_mid})")
                    dangguan1 = create_dangguan(0, y_mid, selected_centers[0])

                # 维护中间挡管数量
                if dangguan1:
                    self.center_dangguan_num += 1
                    print(
                        f"[调试] 中间挡管数量+1，当前总数: {self.center_dangguan_num}"
                    )

        return current_coords

    def _draw_single_dangguan_pair(self, selected_centers):
        """绘制单个挡管对的内部函数（不修改center_dangguan）"""
        from PyQt5.QtGui import QPen, QBrush, QColor, QPainterPath
        from PyQt5.QtCore import Qt
        import ast

        # 解析坐标
        selected_centers_list = []
        if isinstance(selected_centers, list):
            selected_centers_list = [
                item
                for item in selected_centers
                if isinstance(item, tuple)
                   and len(item) == 2
                   and all(isinstance(x, (int, float)) for x in item)
            ]
        elif isinstance(selected_centers, str):
            try:
                parsed_list = ast.literal_eval(selected_centers)
                if isinstance(parsed_list, list):
                    selected_centers_list = [
                        item
                        for item in parsed_list
                        if isinstance(item, tuple)
                           and len(item) == 2
                           and all(isinstance(x, (int, float)) for x in item)
                    ]
            except (SyntaxError, ValueError, TypeError):
                return []
        else:
            return []

        if len(selected_centers_list) != 2:
            return []

        # 坐标转换
        current_coords = self.selected_to_current_coords(selected_centers)
        if not current_coords:
            return []

        # 提取画布坐标
        points = []
        if selected_centers:
            for row_label, col_label in selected_centers:
                row_idx = abs(row_label) - 1
                col_idx = abs(col_label) - 1
                centers_group = (
                    self.full_sorted_current_centers_up
                    if row_label > 0
                    else self.full_sorted_current_centers_down
                )

                if row_idx < len(centers_group) and col_idx < len(
                        centers_group[row_idx]
                ):
                    x, y = centers_group[row_idx][col_idx]
                    points.append((x, y))

        if len(points) != 2:
            return []

        # 定义创建挡管的函数
        def create_dangguan(x, y, selected_center):
            # 检查该位置是否已经存在挡管
            for item in self.graphics_scene.items():
                if isinstance(item, ClickableRectItem) and item.is_center_dangguan:
                    item_rect = item.boundingRect()
                    item_center_x = item.x() + item_rect.center().x()
                    item_center_y = item.y() + item_rect.center().y()

                    if abs(item_center_x - x) < 2 and abs(item_center_y - y) < 2:
                        return None

            pen = QPen(QColor(128, 0, 128))
            pen.setWidth(3)
            brush = QBrush(Qt.NoBrush)

            path = QPainterPath()
            path.addEllipse(x - self.r, y - self.r, 2 * self.r, 2 * self.r)

            center_dangguan_item = ClickableRectItem(
                path=path, is_center_dangguan=True, editor=self
            )
            center_dangguan_item.setPen(pen)
            center_dangguan_item.setBrush(brush)
            center_dangguan_item.original_pen = pen
            center_dangguan_item.original_selected_center = selected_center
            center_dangguan_item.setZValue(10)
            self.graphics_scene.addItem(center_dangguan_item)

            return center_dangguan_item

        x1, y1 = points[0]
        x2, y2 = points[1]

        # 根据管程数确定挡管位置规则
        tube_num = self.get_tube_pass_count()

        if tube_num == "2":
            # 2管程时：y坐标为0
            if x1 == x2:
                dangguan1 = create_dangguan(x1, 0, selected_centers[0])
            elif y1 == y2:
                x_mid = (x1 + x2) / 2
                dangguan1 = create_dangguan(x_mid, 0, selected_centers[0])
            else:
                x_mid = (x1 + x2) / 2
                dangguan1 = create_dangguan(x_mid, 0, selected_centers[0])
        else:
            # 4,6管程时：x坐标为0
            if x1 == x2:
                y_mid = (y1 + y2) / 2
                dangguan1 = create_dangguan(0, y_mid, selected_centers[0])
            elif y1 == y2:
                dangguan1 = create_dangguan(0, y1, selected_centers[0])
            else:
                y_mid = (y1 + y2) / 2
                dangguan1 = create_dangguan(0, y_mid, selected_centers[0])

        return current_coords

    def delete_selected_center_dangguan(self):
        self.operation_order += 1
        """删除选中的中间挡管（完全照搬旁路挡板删除逻辑）"""
        try:
            if (
                    not hasattr(self, "selected_center_dangguan")
                    or not self.selected_center_dangguan
            ):
                return

            danguan_to_remove_info = []  # 存储要删除的挡管信息

            # 找出选中挡管对应的绘制坐标信息
            for dangguan in self.selected_center_dangguan:
                if hasattr(dangguan, "original_selected_center"):
                    dangguan_info = dangguan.original_selected_center
                    danguan_to_remove_info.append(dangguan_info)

            # 去重
            danguan_to_remove_info = list(set(danguan_to_remove_info))

            if not danguan_to_remove_info:
                return

            # 如果是对称模式，获取所有对称坐标
            if self.isSymmetry:
                try:
                    # 使用 judge_linkage 获取所有对称坐标
                    all_symmetric_coords = self.judge_linkage_y(danguan_to_remove_info)
                    danguan_to_remove_info = all_symmetric_coords
                except Exception as e:
                    # 出错时继续使用原始坐标，不中断删除操作
                    pass

            # 从 self.center_dangguan 中删除包含这些坐标的坐标对（小列表）
            # center_dangguan 是嵌套列表：[[coord1, coord2], [coord3, coord4], ...]
            if hasattr(self, "center_dangguan"):
                coords_to_remove = set(danguan_to_remove_info)

                # 过滤掉包含任何要删除坐标的坐标对
                new_center_dangguan = []
                for pair in self.center_dangguan:
                    # 如果这个坐标对中有任何一个坐标需要删除，就移除整个坐标对
                    if not any(coord in coords_to_remove for coord in pair):
                        new_center_dangguan.append(pair)
                    else:
                        print(f"删除坐标对: {pair}")

                self.center_dangguan = new_center_dangguan
                print(
                    f"✓ 删除完成，当前 center_dangguan 包含 {len(self.center_dangguan)} 个挡管"
                )

            # 复制选中列表避免迭代中修改列表导致错误
            danguan_to_remove = list(self.selected_center_dangguan)
            removed_danguan = set()

            # 收集所有需要删除的挡管（包括对称的）
            # 关键修复：确保选中的挡管一定在删除列表中
            all_danguan_to_remove = set(danguan_to_remove)

            # 如果是对称模式，找到所有相关的挡管
            if self.isSymmetry and danguan_to_remove:
                try:
                    # 先列出场景中所有中间挡管及其 original_selected_center
                    all_center_dangguan_in_scene = []
                    for item in self.graphics_scene.items():
                        if (
                                isinstance(item, ClickableRectItem)
                                and item.is_center_dangguan
                                and hasattr(item, "original_selected_center")
                        ):
                            all_center_dangguan_in_scene.append(item)

                    # 关键修复：找出与选中挡管"相关"的那一组挡管
                    # 策略：判断挡管的 original_selected_center 的行号/列号是否在 judge_linkage 返回的坐标中
                    # 提取 judge_linkage 返回的坐标（标准化为绝对值的元组集合）
                    target_coords_normalized = set()
                    for coord in danguan_to_remove_info:
                        row, col = coord
                        # 创建标准化坐标（使用绝对值）
                        normalized = (abs(row), abs(col))
                        target_coords_normalized.add(normalized)

                    for item in all_center_dangguan_in_scene:
                        item_coord = item.original_selected_center
                        row, col = item_coord
                        # 标准化挡管坐标
                        item_normalized = (abs(row), abs(col))
                        # 判断这个挡管是否属于这一组（标准化坐标匹配）
                        if item_normalized in target_coords_normalized:
                            all_danguan_to_remove.add(item)
                except Exception as e:
                    pass
            else:
                # 非对称模式：只删除选中的挡管
                pass

            # 删除所有相关的挡管图形项
            for dangguan in all_danguan_to_remove:
                if dangguan in removed_danguan:
                    continue

                # 删除关联的临时矩形
                if hasattr(dangguan, "related_temp_items") and isinstance(
                        dangguan.related_temp_items, list
                ):
                    for temp_item in dangguan.related_temp_items:
                        if temp_item and temp_item.scene() == self.graphics_scene:
                            self.graphics_scene.removeItem(temp_item)

                # 移除自身
                if dangguan.scene() == self.graphics_scene:  # 确认在当前场景中
                    self.graphics_scene.removeItem(dangguan)
                    removed_danguan.add(dangguan)

            # 维护中间挡管数量
            # 计算删除的挡管数量
            deleted_count = len(removed_danguan)
            if deleted_count > 0:
                old_count = self.center_dangguan_num
                self.center_dangguan_num = max(
                    0, self.center_dangguan_num - deleted_count
                )
                print(
                    f"[调试] 删除中间挡管数量: {deleted_count}，从 {old_count} 减少到 {self.center_dangguan_num}"
                )

            # 清空选中列表
            self.selected_center_dangguan = []

            # 强制刷新视图
            self.graphics_scene.update()
            self.graphics_view.viewport().update()

        except Exception as e:
            pass

