    def clear_connection_lines(self, scene):
        """安全清除所有连线，处理无效对象"""
        if not hasattr(self, "connection_lines"):
            self.connection_lines = []
            return

        for line in reversed(self.connection_lines):
            try:
                if line in scene.items():
                    scene.removeItem(line)
            except RuntimeError:
                pass

        self.connection_lines.clear()

    def clear_cross_pipe_lines(self):
        """
        清除所有交叉布管连线
        包括：
        1. 从场景中移除所有交叉布管连接线图形
        2. 清空 cross_pipe_lines 列表
        3. 清空交叉布管坐标数据
        4. 重置交叉布管状态标志
        """
        if self.selected_centers:
            self.delete_cross_pipes_for_selected_centers(self.selected_centers)
            self.clear_selection_highlight()
        else:
            # 1. 从场景中移除所有交叉布管连接线
            if hasattr(self, "cross_pipe_lines") and self.cross_pipe_lines:
                for line in reversed(self.cross_pipe_lines):
                    try:
                        if line and line.scene() == self.graphics_scene:
                            self.graphics_scene.removeItem(line)
                    except (RuntimeError, AttributeError) as e:
                        print(f"移除交叉布管连接线时出错: {e}")
                        pass
            # 2. 清空 cross_pipe_lines 列表
            if hasattr(self, "cross_pipe_lines"):
                self.cross_pipe_lines.clear()

            # 3. 清空交叉布管坐标数据
            if hasattr(self, "coord_x_line1_2"):
                self.coord_x_line1_2 = []
            if hasattr(self, "coord_x_line2_2"):
                self.coord_x_line2_2 = []
            if hasattr(self, "coord_x_line3_2"):
                self.coord_x_line3_2 = []
            if hasattr(self, "coord_y_line1_2"):
                self.coord_y_line1_2 = []
            if hasattr(self, "coord_y_line2_2"):
                self.coord_y_line2_2 = []
            if hasattr(self, "coord_y_line3_2"):
                self.coord_y_line3_2 = []
            if hasattr(self, "coord_x_line1_4"):
                self.coord_x_line1_4 = []
            if hasattr(self, "coord_x_line2_4"):
                self.coord_x_line2_4 = []
            if hasattr(self, "coord_x_line3_4"):
                self.coord_x_line3_4 = []
            if hasattr(self, "coord_y_line1_4"):
                self.coord_y_line1_4 = []
            if hasattr(self, "coord_y_line2_4"):
                self.coord_y_line2_4 = []
            if hasattr(self, "coord_y_line3_4"):
                self.coord_y_line3_4 = []
            # 同步清空每排绝对坐标对缓存，避免后续保存交叉布管时写入旧数据
            if hasattr(self, "abs_coords_line1"):
                self.abs_coords_line1 = []
            if hasattr(self, "abs_coords_line2"):
                self.abs_coords_line2 = []
            if hasattr(self, "abs_coords_line3"):
                self.abs_coords_line3 = []
            if hasattr(self, "_current_abs_coords"):
                self._current_abs_coords = []

            # 4. 重置交叉布管状态标志
            if hasattr(self, "is_x_line1"):
                self.is_x_line1 = False
            if hasattr(self, "is_x_line2"):
                self.is_x_line2 = False
            if hasattr(self, "is_x_line3"):
                self.is_x_line3 = False
            if hasattr(self, "is_y_line1"):
                self.is_y_line1 = False
            if hasattr(self, "is_y_line2"):
                self.is_y_line2 = False
            if hasattr(self, "is_y_line3"):
                self.is_y_line3 = False

            # 5. 恢复因交叉布管而被删除的换热管
            if (
                    hasattr(self, "cross_pipe_deleted_tubes")
                    and self.cross_pipe_deleted_tubes
            ):
                # 恢复所有被删除的换热管
                self.build_huanreguan(self.cross_pipe_deleted_tubes)
                # 清空记录列表
                self.cross_pipe_deleted_tubes.clear()

            # 刷新场景
            if hasattr(self, "graphics_scene"):
                self.graphics_scene.update()

            # 清空交叉布管后立即落库，确保第一/二/三排绝对坐标对列同步置空（0）
            try:
                self.build_sql_for_cross_pipes()
            except Exception as e:
                print(f"[clear_cross_pipe_lines] 写回交叉布管表失败: {e}")

            print("已清除所有交叉布管连线")

